#      発走前判定・再構築）でそれぞれ掛ける形にすると、1つ忘れた経路だけが
#      1点買いを出し続ける——このリポジトリが繰り返し踏んでいる型。
#   ⚠️ **ROI で採否を語らないこと。** どの案も 77.7〜78.5% で差は有意でない。
#      この変更が動かすのは的中率と払戻の大きさだけ。
RANK_7C_TRIO_LEGS_FLOOR = 2
#
# 【✂️ 相手の絞りをやめて総流しに戻す案は 2026-08-19 に検証して不採用 — 再提案しない】
