#     | 2026-06-08〜08-18 / **朝の板あり** | **−1.9pt [−3.9,−0.2]** 有意 | **−4.6pt** 有意 |
#
#   ⚠️ **最初の「+1.0pt 有意」は前提違い**だった。本番の配分は
#      朝の板 × p3 × 予測オッズ（`src/stake_allocation.py`）なのに p3 のみで測り、
#      さらに窓が全期間だった。**同じ窓・同じ配分に揃えると絞りありが勝つ。**
#      朝の板スナップショット（`wt_odds_snapshot` の morning）は **2026-06-08 以降
#      しか無い**ので、板込みの検証はこの窓でしかできない。
#
#   ✅ 教訓: 買い目の形を比べるときは **配分を本番に揃えること**。
#      絞りは1点あたりを厚くするので、配分が違うと効果が丸ごと変わる。
#
# 🔴 **2026-08-17: 1点まで縮んだときの差し替えを「2,3番手2点」から「総流し」へ変更した**
#    （ユーザー判断。方針「看板レース以外は精度が大事」に基づく）。
#
#    2026-08-15 に 1点帯を「相手の2,3番手2点」へ差し替えたが、**その2点買いだけを
#    取り出すと精度が突出して低い**ことが分かった。7C を本番と同じ買い方で再現した
#    全期間（7,999R・593日）の点数別:
#
#      看板以外の 三連複 2点   2.98件/日  **的中 22.9%**  ROI 81.4%
#      看板以外の 三連複 3点   2.17件/日    的中 41.6%   ROI 84.5%
#      看板以外の 三連複 4点   1.41件/日    的中 52.4%   ROI 77.3%
#      看板以外の 三連複 5点   0.42件/日    的中 68.1%   ROI 77.9%
#      看板以外の 三連単切替   3.20件/日    的中 47.5%   ROI 84.8%
#
#    同じレースを総流しへ戻したときの比較（両年で符号一致）:
#
#      母集団                     案            素の的中  表示的中    ROI
#      看板 ∧ 2点(1.07件/日)      現行(2点)      19.6%   19.4%  67.1%
#                                **総流し**    60.4%   27.4%  72.8%   ← 3指標とも改善
#      看板以外 ∧ 2点(2.98件/日)  現行(2点)      22.9%   22.6%  81.4%
#                                **総流し**    65.9%   30.0%  78.4%   ← ROI のみ −3.0pt
#
#    🔴 **看板側は3指標すべてで総流しが勝つ**（素 +40.8pt / 表示 +8.0pt / ROI +5.7pt）。
#       看板は方針上見送れないので、ここは総流し一択。
#    ⚠️ 看板以外は ROI が −3.0pt 落ちる。それでも採ったのは
#       「看板以外は精度が大事」という商品方針（素の的中 +43.0pt / 表示 +7.4pt）による。
#       **ROI を根拠に採用したのではない。**
#
#    ⚠️ 2026-08-15 の判断（`keirin_7c_one_point_swap`）と逆向きに見えるが矛盾ではない。
#       当時は **7C 全体の平均**で「総流しは表示的中が下がる」と読んだ。今回は
#       **1点まで縮む帯だけ**を取り出しており、母集団が違う。平均が部分集合の
#       符号を隠していた例（このリポジトリで繰り返し起きている型）。
#
#    ⚠️ 定数名と値は残してある。`legs_floor` は「この点数以下なら差し替える」の
#       閾値として今も使う（差し替え先が2点から総流しへ変わっただけ）。

# 🔴 **総流し帯から WT△ を外す**（2026-08-15・ユーザー判断「案E」）。
#
#   落差カットは **相手が横並びのレースでは何も削らない**（p3 に落差が無いため）。
#   その結果 4〜5点で買う「総流し帯」が残り、そこが 7C のガミの本体だった。
#   実測（本番 picks_history 全期間）: 三連複4点のガミ率 47.0% / 5点 50.1%。
#
#   ## 削れる相手は誰か（総流し帯 2,746R・月次凍結vintage・2025-01〜）
#
#     相手の属性   登場     的中率   ガミ率   的中時の配当中央
#     **WT△**    2,638    26.8%   90.2%     5,500円
#     ○            128    21.9%   82.1%     7,000円
#     無印        9,210    11.4%   34.0%    12,250円
#
#   ＝ △は「よく3着に来るが必ず安い」相手で、**当てても損になる的中**を作っている。
#   7B で「相手から△を外すとガミ率 42.4%→10.8%」が効いたのと同じ構造。
#
#   ## なぜ「p3 が高いときだけ」なのか
#
#   常に外す案が最も効く（実質的中 +3.2pt）が、素の的中が 65.0%→38.6% と 26.4pt 落ち、
#   「軸2車は3着内なのに買い目から外れる」体験が 726R 増える。ユーザー判断で
#   **発動を絞った案E**（△の3着内率が閾値以上のときだけ）を採用した。効果は約6割:
#
#     方針                     素の的中  実質的中  ガミ率   ROI   実質Δ掃引  実質Δ確認
#     総流しのまま                65.0%   28.0%  56.9%  80.7%       —       —
#     常に△を外す                38.6%   31.5%  18.5%  83.1%  +4.0pt  +3.2pt
#     **△のp3>=0.40のときだけ**  45.3%   30.2%  33.3%  82.3%  +2.8pt  +2.0pt
#
#   確認窓の95%CI（レース単位 paired bootstrap 2,000回）:
#   実質的中Δ [+1.0, +3.1]pt / ROIΔ [+0.2, +4.4]pt ＝**どちらも0を跨がない**。
#
#   ## 検証の作法（7A の相手削りが棄却された型を踏まないために）
#
#   7A では同型の相手削り6規則が **5規則で符号反転**して棄却された。原因は
#   「窓間のROI変動(26pt)が規則の効果(±3pt)を一桁上回る」こと。本件が成立するのは
#   **主指標を ROI ではなく実質的中（ガミ除く＝netkeirin の表示的中率）に置いた**
#   ためで、こちらは頻度統計なので裾の影響を受けない。裏取りも取ってある:
#     - 掃引窓(794R)・確認窓(1952R)で符号一致
#     - 月次は実質的中が 18/20ヶ月で改善（悪化は n=13 の月のみ）
#     - 払戻上位10本を除いても ROI 改善が残る（裾依存でない）
#
#   ⚠️ **削るのは1車まで**（実測でも削り後は3〜5点）。3点を下回るなら削らない。
#   ⚠️ **三連単側には掛けない**（点数を変えると効果が消えるのは検証済み）。
#   ⚠️ ライン条件（軸と同ライン除外など）も測ったが**印を上回らない**
#      （実質的中は同等でも ROI が +0.4pt しか動かない）。組み合わせも悪化。再提案しないこと。
#   ⚠️ 印が取れないレースは **fail-open（削らない）**。`wt_ana=None` が既定。
RANK_7C_ANA_CUT_MIN_LEGS = 4    # 総流し帯（4点以上）でだけ発動する
RANK_7C_ANA_CUT_P3_MIN = 0.40   # △の3着内率がこれ以上のときだけ削る
RANK_7C_ANA_CUT_FLOOR = 3       # 削って3点を下回るなら削らない

# 🔴 低配当パターンの除外（2026-08-07 追加・ユーザー発見）。
#   **「複勝率の3位と4位が大きく離れている（＝上位3車が抜けている）」かつ
#     「その上位3車が同一ライン」**のレースは見送る。
#   実例 豊橋5R(2026-08-07): 複勝率 82.5/62.6/59.0 → 27.2 と3-4位差31.8pt、
#   上位3車(7・4・2)が全員ライン1。結果 2-4-7 で三連複 2.0倍＝10,000円投資に対し
#   払戻4,000円。**ライン3車で決まると配当が付かない**。
#
#   評価窓での除外対象の実力（母集団の4.8%）:
#     的中 68.68%（全体58.08%より**高い**）／**的中の66.1%が2.0倍以下**／ROI 73.6%
#   ＝「よく当たるが儲からない」型を正確に切り出せている。
#
#   見送った場合（評価窓/確認窓）: 件数 23.48→22.36 / 22.47→21.56 件/日、
#   的中 58.08→57.55 / 59.42→59.07%、ROI 77.3→77.5 / 77.8→77.9%、
#   **低配当的中 2.10→1.59 / 2.08→1.66 件/日（−24%/−20%）**。両窓で符号一致。
#
#   ⚠️ 片方だけでは切らない。「3-4位差だけ」は7.6%・「同一ラインだけ」は29.4%が該当し、
#      後者は的中率を3.2pt も落とす。**両方揃ったときだけ**が最小の犠牲で効く。
#   ⚠️ ROI はほとんど動かない（+0.2pt）。これは収益改善ではなく
#      「当たったのに損をした」体験の比率を下げる施策（15.4%→12.4%）。
# 🔴 **軸1が抜けすぎたレースは買わない**（2026-08-18・ユーザー判断）。
#   「一定以上に軸の指数が抜けて高い場合は、どの目を買っても回収困難」。
#   実測（本番同等の再現・7,576R・593日）は**単調**で、的中は上がるのに
#   表示的中と回収が下がる＝**当たっても配当が付かない**帯が確かに存在する:
#
#     軸1の3着内率   件/日   素の的中  表示的中    ROI   的中時の三連複中央
#     0.70-0.80      0.44   41.5%  32.7%  84.4%      5.0倍
#     0.80-0.88      5.23   41.6%  32.3%  81.7%      5.2倍
#     0.88-0.93      3.39   42.2%  32.0%  79.1%      4.6倍
#     **>=0.93**     3.72   42.8%  29.4%  **74.7%**   4.2倍   ← 壁の下
#
#   回避したときの全体（両年で符号一致）:
#
#     閾値      残件/日   素の的中  表示的中    ROI   （25年 / 26年）
#     現行      12.78   42.1%  31.4%  79.1%   78.8 / 79.4
#     >=0.95    10.49   41.7%  32.0%  80.0%   79.3 / 81.0
#     **>=0.93** 9.06   41.8%  32.2%  80.9%   79.1 / 83.6
#     >=0.92     8.39   42.2%  32.5%  81.9%   80.2 / 84.5
#     >=0.90     7.10   41.8%  32.1%  81.5%   80.2 / 83.4
#
#   0.93 を採る理由: **回避対象がちょうど壁の下（74.7%）になる最大の閾値**で、
#   これより下げても ROI は 81〜82% で頭打ちになり件数だけを失う（0.92/0.90/0.88 は
#   ほぼ同値）。閾値に鋭い最適点は無いので、切る理由が説明できる位置を採る。
#
#   ⚠️ **ROI 改善は有意ではない**（+1.8pt [−2.7, +6.3]）。採用根拠は
#      「回避する帯が単体で壁の下」であることと、表示的中 +0.8pt であって、
#      全体 ROI の改善ではない。
#   ⚠️ **点数を削る対策ではない**（ユーザー指示）。予算枠方式では点数を減らすと
#      1点が厚くなるだけで、的中とガミが機械的に相殺されて表示的中は動かない
#      （実測: 3点30.2% / 4点31.2% / 5点31.8% とほぼ一定）。**レースごと避ける**
#      のが唯一効く形。
#   ⚠️ 看板も例外にしない（`lowpay_pattern` と同じ扱い）。看板の被覆は
#      入稿側の穴埋めが担う。例外にすると効果が半減する（80.9%→79.4%）。
RANK_7C_AXIS1_P3_MAX = 0.93

RANK_7C_LOWPAY_GAP34_MIN = 0.30

# 1レースの予算枠。点数で均等割りし 100円単位へ切り捨てる（7H1 と同じ方式）。
# 🔴 **固定額/点ではない。** 点数が可変なので、固定額にすると点数の多いレースほど
#    投資が増えて ROI の重み付けが歪む。予算枠なら全レースが等しく効く。
#    この方式では **ガミ ⟺ 的中オッズ < 点数**（戻り = (BUDGET/k) × odds）。
# ⚠️ 値をここに書き直さないこと（2026-08-08 是正）。以前は 10000/100 という
#    リテラルの再定義で、`RACE_BUDGET`/`STAKE_UNIT` と**同じ値を2箇所に手書き**
#    していた。一方 netkeirin 入稿側（`netkeirin_submit_wt.RANK_CONFIGS`）は
#    `RACE_BUDGET` を直接参照しているため、全ランク一律で予算を改定したときに
#    「入稿される金額」と「picks_history に記録される賭け金」が無言で食い違う。
#    同じ値の手書き二重管理はこのリポジトリが繰り返し踏んでいる事故の型。
RANK_7C_BUDGET = RACE_BUDGET
RANK_7C_UNIT = STAKE_UNIT


RANK_7S_NE = 7                  # 対象車数（7車ちょうど）
RANK_7S_STAKE = unit_stake(5)   # 2,000円/点（5点=10,000円/レース）

# 三連複が安くなりやすい（極端な人気決着になりやすい）レースの除外上限。
#
# 【2026-07-31改定】方針転換: 「まずは十分な的中率の上での安定したROI確保」
# （ユーザー方針）を目的に、月次凍結vintageモデルでのhonest全期間検証
# （2024-01-01〜2026-07-31・31ヶ月・配分はuniform固定・
#   scripts/exp_s7_cdf_regime_full_period.py）で再較正した。
#   現行(axis_sum<=1.3・mark3<=1併用): 576R・0.61件/日・的中34.0%・ROI78.5%・
#     月次ROI標準偏差43.7（月次0%回数1）
#   新設定(axis_sum<=1.5・mark3ゲート撤廃＝下記rank_7s_daily_select参照):
#     6,546R・6.94件/日・**的中41.0%**・**ROI79.3%**・
#     **月次ROI標準偏差17.3**（月次0%回数0）
# 的中率・ROIとも改善しつつ月次変動を約1/2.5に抑え、日次件数を約11倍
# （目標の5〜10件/日レンジ）に拡大できることを確認したため採用。
# mark3ゲート単体撤廃（axis_sum据え置き）はROI74.9%に悪化するため不採用
# （axis_sum<=1.5との組み合わせで初めて機能する）。
#
# 【旧経緯（2026-07-24導入時、汚染モデル時代の数値・参考情報として残置）】
# 買い目は5点流し（1点100円=500円）のため、三連複配当が500円(5倍)を下回ると
# 的中しても賭け金を割る、という着眼から導入。axis_sumとレース着地時の
# 三連複配当<500円の相関 AUC 0.64(train)/0.67(test)。当時の汚染モデルでの
# シミュレーションでROI131.3%→147.1%として1.3を採用したが、
# [[keirin_wt_foundational_audit_2026_07_29]]で当時のvintageモデルが
# 汚染されていたと判明したため、絶対値は参考にしないこと。
# 【2026-08-05】1.5 → 1.40 へ引き下げ（ユーザー承認済み）。7車専用の定数で、
# 9車(S9/9A)には元々導入していない（下記L689付近のコメント参照）ため影響しない。
#
# 目的は「7S の純度を上げる」こと。**全体の期待値を上げる変更ではない**。
#
# 掃引窓（2025-07〜2026-07・4窓）で 7S の ROI 86.0→92.1% と出たが、
# 掃引した窓の数字は多重比較で膨らむ。**掃引に一度も使っていない確認窓
# （2024-07〜2025-06・4窓、`scripts/exp_7s7a_threshold_confirm.py`）**で
# 閾値を固定したまま一度きり検証した結果:
#
# | 区分 | 件/日 | 的中 | ROI | 窓別ROI(c1 c2 c3 c4) |
# |---|---|---|---|---|
# | 現行 7S (<=1.50) | 6.69 | 44.2% | 82.3% | 75.6 79.5 88.7 85.4 |
# | 新 7S (<=1.40)   | 3.68 | 41.0% | **84.4%** | 76.7 78.4 89.1 93.3 |
# | 現行 7A          | 11.45 | 39.0% | 77.7% | 81.4 81.6 68.8 79.0 |
# | 新 7A            | 13.62 | 40.9% | 78.7% | 80.2 80.8 74.1 79.6 |
# | 現行 7S+7A       | 18.15 | 41.0% | 79.3% | 78.9 80.9 76.5 81.1 |
# | 新 7S+7A         | 17.30 | 41.0% | **79.8%** | 79.3 80.3 77.2 82.1 |
#
# 掃引窓の +6.1pt は確認窓で **+2.1pt** に縮んだ（多重比較ぶんが落ちた）が、
# **確認窓4つすべてで ROI>=75% かつ現行を上回った**ため採用。
#
# ⚠️ **7S+7A の合計では +0.5pt しか変わらない**。1.40〜1.50 の帯は消えるのではなく
#    大半が 7A へ移るため（n_fail が 0→1 になるだけ）。実際に除外されるのは
#    「axis_sum 1.40〜1.50 かつ entropy も不合格」の 0.85件/日のみ。
#    **7S だけを買う運用なら +2.1pt、7S+7A を買う運用ならほぼ無意味**。
# ⚠️ 変更後は 7S が 6.69→3.68件/日 とほぼ半減し、その分 7A が増える。
#
# 【✂️ 1.50 へ戻す案は 2026-08-18 に検証して不採用 — 再提案しない】
#
#   きっかけ: `ABOLISHED_PAPER_RANKS` に RANK_7A があるのを見て「受け皿が消えた」と
#   考えた。🔴 **これは誤読**。7A は廃止ではなく **2026-08-14 に RANK_7S へ統合**
#   （旧7S ∪ 旧7A ∪ 旧7SS・`backfill_7s_merged_rank_wt`）で、選別ロジックは動いている。
#
#   ただし「帯が捨てられている」自体は**本当だった**。7A は「2ゲートのうち
#   ちょうど1つ不合格」を拾うが、実際に生き残るのは **entropy 不合格の側**で、
#   `rank_7a_top2_gate`（動的・約1.432）が axis_sum 側をほぼ全部切る。
#   実測: 1.40〜1.50 の帯 2,658R と 7A の採用行 440R は **共通 0 件**。
#   1.50 にすると統合ランクは +34%（1,027→1,377R・同一6ヶ月）増える＝純増であって
#   ラベルの移動ではない。
#
#   🔴 **それでも不採用**。増えた分は既存プールと同じ質で改善しない:
#
#     | 閾値 | n | 的中 | 表示的中 | ROI |
#     |---|---|---|---|---|
#     | 1.40 | 1,027 | 40.3% | **33.2%** | **79.9%** |
#     | 1.50 | 1,377 | 41.5% | 33.0% | 79.3% |
#
#   ⚠️ **旧7S 単独で測ると「表示的中 +2.1pt・ROI +3.1pt」と出る。これは誤り。**
#      1.40 側のベースラインに 7A と 7SS が入らず、そちらが拾っていた質の高い
#      レースが勘定に入らないため。**必ず `backfill_7s_merged_rank_wt`（統合）で測る。**
#   ⚠️ picks_history との突き合わせも使えない（7S が 1.50 だった時代の行が残る
#      世代混在。`rule_version` 導入の直接の動機）。
RANK_7S_AXIS_SUM_MAX = 1.40
#
# 🔴 **ゲートの正規化が不統一（2026-08-21 実測・未修正）**
#
#   `rank_7s_field_entropy()` と `rank_7h2_honmei_share()` は**レース内合計で割って**
#   から判定するのに、**`axis_sum` は割っていない**（`rank_7s_select_axis` は
#   `top3_probs[axis1] + top3_probs[axis2]` をそのまま返す）。
#   `pred_top3_pct` の合計は 3.0 に正規化されておらず中央 2.976・5-95%tile
#   2.667〜3.253 とレースごとに ±10% 揺れるので、**同じ 1.40 でも実質的な厳しさが
#   レースによって違う**。
#
#   合計 3.0 へ揃えて判定し直すと、**現行ゲートの通過判定が 21.3% 入れ替わる**
#   （7S 3,254R 実測。順位は1つも変わらないので**的中は動かない。動くのは
#   レース選別だけ**）。
#
#   ⚠️ **直すなら閾値の掃引をやり直すこと。** 1.40 は正規化していない値の上で
#      決めた定数なので、正規化だけ入れると別のゲートになる。
#   ⚠️ 2026-08-21 に「厳しくする方向」を4軸（axis_sum 生 / axis_sum 正規 /
#      entropy / 波乱スコア）で掃引したが、**どれも採用に至らなかった**ので
