# ---- 3ヘッド軸選定の大敗ペナルティ重み（2026-08-04・7車立てのみ） ----------
# 軸1 = pred_win 最上位、軸2 = z(pred_prob) − w2·z(bad_prob) の最上位（軸1を除く）。
# w1（軸1側の大敗ペナルティ）は 0 で固定＝定数を置かない。軸1の外れは惜敗(4着)が
# 62% で大敗が少なく、ペナルティを掛けるほど1着率が落ちるため（w1=0.6 で −3.5pt）。
# 対して軸2の外れは6着以下の大敗が67%を占めるので、軸2にだけ掛ける。
#
# w2=0.3 の根拠（scripts/exp_three_head_axis.py・月次凍結せず窓ごとに再学習した
# honest walk-forward 4窓 2025-07〜2026-07・約4,300推奨）:
#   現行(win∩top3重なり) → w2=0.3 で 的中 38.9→41.4% / ROI 77.5→82.8% /
#   軸2の6着以下 17.2→14.1% / 軸2の3着内 57.4→60.1%
#   **4窓すべてで的中・ROIとも改善し符号反転なし**（85.9→88.9 / 80.4→81.4 /
#   69.3→79.1 / 74.5→81.8）。
# w2=0.6 も平均は近い(ROI 81.0%)が、w1=0.3 を併用する案は 2026-01〜04 窓で
# ROI が −0.9pt 反転する。4/4クリーンなのは w1=0.0 × w2=0.3 だけ。
#
# ⚠️ ROI は改善するが 100% には届かない（77.5→82.8%）。控除率75%の壁は破れておらず、
#    改善するのは的中率と軸品質であって黒字化ではない。
# ⚠️ **9車立てには適用しない**。同じ掃引を9車(4窓・約550推奨)で回すと、平均では
#    +2.0pt に見えるが窓別では 2026-01〜04 で 的中 −2.8pt・ROI −19.9pt と反転する。
#    窓あたり139推奨ではノイズに埋もれ判定不能。9B・S9/9A再較正と同じく、7車の
#    知見が9車へ移らなかった事例（scripts/exp_three_head_axis.py --n-entries 9）。
RANK_AXIS2_BAD_WEIGHT = 0.3

# 3ヘッド軸選定を live 本番へ入れた日（この日以降の7車 picks は3ヘッドで選ばれている）。
# `backfill_7*_rank_wt.py` / `rebuild_7*_walkforward_pg.py` は bad_probs を渡さないため
# **旧軸で再構築すると live の3ヘッド記録を上書きして消す**。この日以降を含む再構築は
# `src/wt_rebuild_common.py::rebuild_pg_atomic` が既定で拒否する。
# 過去を旧軸で塗り直すこと自体が目的なら --allow-legacy-axis を明示すること。
# 3ヘッドで honest に再構築できるようにするには月次 vintage の bad モデルが必要だが、
# `train-wt --target` は top3/win しか作れない（2026-08-04 時点の制約）。
THREE_HEAD_AXIS_SINCE = "2026-08-04"


def _race_zscore(probs: dict[int, float]) -> dict[int, float]:
    """レース内で z 化する。全車同値・1車のみなら 0（ゼロ除算しない）。"""
    if not probs:
        return {}
    vals = list(probs.values())
    mean = sum(vals) / len(vals)
    var = sum((v - mean) ** 2 for v in vals) / len(vals)
    if var <= 0:
        return {f: 0.0 for f in probs}
    sd = math.sqrt(var)
    return {f: (v - mean) / sd for f, v in probs.items()}


def rank_7s_field_entropy(top3_probs: dict[int, float]) -> float:
    """レース全体（出走7車）の指数エントロピー（占有率ベースの拮抗度）を返す。

    top3_probs: {frame_no: pred_prob}（rank_7s_select_axis と同じ入力）。
    値が低いほど予測確率が一部の車（主に軸2車）に集中している状態。
    オッズを一切使わないため、発走前・オッズ非公開の朝の時点でも計算可能。
    """
    vals = list(top3_probs.values())
    total = sum(vals)
    if total <= 0:
        return 0.0
    ent = 0.0
    for v in vals:
        s = max(v / total, 1e-9)
        ent -= s * math.log(s)
    return ent


# ═══════════════════════════════════════════════════════════════════════════
# 軸2の差し替え（◎○が別ライン × 代替が軸1と同ライン × 差が小さい）— 2026-08-23
# ═══════════════════════════════════════════════════════════════════════════
#
# 【ユーザー指摘】「二軸一致時に片方が着外になって外しているケースが問題。
#   ここは確実に当てる、当てられないなら片方の軸はそれ以外の選手にする」
#   「3着以下との差、ラインも考慮した条件分けが必要」
#
# 🔴 **一律に「◎○を軸2から外す」は逆効果**（測定済み）。◎○は実際に強く、
#    軸1∈{◎,○} の全レースで一律置換すると二軸的中 −5.42pt、
#    減らしたい「軸2のみ着外」がむしろ 30.40%→35.82% に増える。
#    信頼度モデルの十分位で切っても最下位10%で −1.17pt と、プラスに転じない。
#
# 🟢 **効くのは3条件がすべて揃うときだけ**（両窓で確認）:
#      ① 現行の二軸（◎○）が**別ライン**       … ライン戦で噛んでいない
#      ② 代替車が**軸1と同一ライン**           … 軸1を後ろから支える
#      ③ `p3[軸2] − p3[代替車] < 0.114`        … 置き換えの代償が小さい
#
#    二軸的中（＝5点総流しの的中）の実測:
#      探索 2026     575R  31.83% → 38.43%  (+6.61pt [+0.7,+12.2])
#      確認 2024-25 1,418R 33.00% → 38.36%  (+5.36pt [+1.9,+8.8])
#    該当率は両窓とも 16.9%。
#
# ⚠️ **ROI の数字を訂正**（2026-08-23 当日中）。導入時に載せた ROI は
#    **均等配分で計算していた**が、本番の 7S は `RANK_CONFIGS["7S"]` の
#    `tilt_stakes: True` で**ダッチング配分**（`tilted_stakes` → `landing_weights`
#    が予測オッズの `1/オッズ` を単独採用）。別の商品を測っていた。
#    本番の配分で測り直した値:
#
#      探索 2026     ROI 65.4% → 76.0%  (+10.6pt [-1.3,+22.2])  ガミ 2.7% → 2.7%
#      確認 2024-25  ROI 69.5% → 75.3%  (+5.7pt  [-1.4,+13.1])  ガミ 2.8% → 4.6%
#
#    🔴 **的中率は配分に依存しない**ので、採否の根拠にした +5.3〜6.6pt は
#       影響を受けない。ROI 差はどちらの計算でも有意でない（結論は不変）。
#    ⚠️ ただし**確認窓でガミ率が 2.8% → 4.6% に上がる**（差し替えで配当構造が
#       変わるため）。導入時には測っていなかった項目なので記録しておく。
#
# 🔴 **条件を1つでも外すと効果が消える**（探索窓・確認窓とも）:
#      「差小 ∧ 代替同ライン」だけ            → +1.69pt（有意でない）
#      「二軸別ライン ∧ 差小」だけ            → +1.55pt（有意でない）
#    さらに **現行の二軸が同ラインのときに置換すると −7.96pt**。
#    ライン戦として既に噛んでいるペアは崩してはいけない。
#
# 🔴 **代替車はモデルを使わず `p3` 順で選ぶ**。ペア同時確率モデルで選ぶ版と
#    比べて 探索 +6.17 vs +6.61 / 確認 +4.80 vs +5.36 と差が小さく、
#    **モデルの学習・配布を増やす価値が無い**（条件②で候補が既に絞られるため）。
RANK_AXIS2_SWAP_ENABLED = True
RANK_AXIS2_SWAP_GAP_MAX = 0.114   # 🔴 探索窓(2026)の中央値。確認窓で引き直していない


def rank_7s_swap_axis2_line(
    axis1: int, axis2: int, top3_probs: dict[int, float],
    line_of: dict[int, object] | None,
    wt_honmei: int | None, wt_taikou: int | None,
    gap_max: float = RANK_AXIS2_SWAP_GAP_MAX,
    enabled: bool = RANK_AXIS2_SWAP_ENABLED,
) -> int:
    """3条件がすべて成り立つときだけ軸2を差し替えて返す（それ以外は axis2 のまま）。

    line_of: {frame_no: line_group}。**None や欠損は差し替えない側へ倒す**
      （推奨を勝手に動かさない。ライン不明で差し替えると根拠が消える）。

    根拠と実測は本セクション冒頭のコメントを参照。

    >>> p3 = {1: .70, 2: .60, 3: .55, 4: .30}
    >>> lg = {1: "A", 2: "B", 3: "A", 4: "B"}
    >>> rank_7s_swap_axis2_line(1, 2, p3, lg, 1, 2)   # 3条件そろう → 3へ
    3
    >>> lg2 = {1: "A", 2: "A", 3: "A", 4: "B"}        # 二軸が同ライン → 崩さない
    >>> rank_7s_swap_axis2_line(1, 2, p3, lg2, 1, 2)
    2
    >>> p3b = {1: .70, 2: .60, 3: .30, 4: .20}        # 差が大きい → 据え置き
    >>> rank_7s_swap_axis2_line(1, 2, p3b, lg, 1, 2)
    2
    """
    if not enabled or not line_of:
        return axis2
    if wt_honmei is None or wt_taikou is None:
        return axis2
    # 対象は「二軸が◎○」のレースだけ（軸1も軸2も印の側にいる）
    if axis1 not in (wt_honmei, wt_taikou) or axis2 not in (wt_honmei, wt_taikou):
        return axis2
    la = line_of.get(axis1)
    if la is None:
        return axis2
    # ① 現行の二軸が同ラインなら崩さない（崩すと −7.96pt）
    if line_of.get(axis2) == la:
        return axis2
    # ② 候補 = 軸1と同ライン ∧ ◎○でない
    cand = [c for c, g in line_of.items()
            if c not in (axis1, wt_honmei, wt_taikou)
            and g is not None and g == la and c in top3_probs]
    if not cand:
        return axis2
    rep = max(cand, key=lambda c: (top3_probs[c], -c))
    # ③ 置き換えの代償が小さいこと
    if top3_probs.get(axis2, 0.0) - top3_probs[rep] >= gap_max:
        return axis2
    return rep


def rank_7s_select_axis(
    win_probs: dict[int, float], top3_probs: dict[int, float],
    bad_probs: dict[int, float] | None = None,
    bad_weight: float = RANK_AXIS2_BAD_WEIGHT,
) -> tuple[int, int, float] | None:
    """S7の軸2車とaxis_sum（波乱度指数の元）を選定する。

    win_probs / top3_probs: {frame_no: 確率(0-1 or pct、比較にのみ使うのでスケール不問)}
      レース内全車分。
    bad_probs: 大敗（6着以下）確率。**渡された場合のみ3ヘッド選定**に切り替わる。
      None なら従来の重なり方式を完全に維持する（9車立て・過去分バックフィル用）。

    軸選定（3ヘッド版・bad_probs あり）:
      軸1 = win_probs 最上位
      軸2 = z(top3_probs) − bad_weight × z(bad_probs) の最上位（軸1を除く）
      重なりを要求しないため、旧ロジックが None を返す「重なり0」でも軸が立つ。

    軸選定（従来版・bad_probs なし）:
      win_probs上位3 ∩ top3_probs上位3 の重なり車から、
      重なり>=2ならtop3_probs上位2、重なり==1ならその1車+残りのtop3_probs最上位。

    returns (axis1, axis2, axis_sum) or None（重なり0・データ不足で選定不能）。
    axis_sum は axis1/axis2 の top3_probs 合計（波乱度指数・低いほど波乱寄り）。
    **3ヘッド版でも axis_sum の定義は変えない**（RANK_7S_AXIS_SUM_MAX ゲートの
    意味を変えないため）。
    """
    if not win_probs or not top3_probs or len(win_probs) < 3 or len(top3_probs) < 3:
        return None

    if bad_probs:
        axis1 = max(win_probs, key=lambda f: win_probs[f])
        zp = _race_zscore(top3_probs)
        zb = _race_zscore(bad_probs)
        rest = [f for f in top3_probs if f != axis1 and f in zb]
        if not rest:
            return None
        axis2 = max(rest, key=lambda f: zp[f] - bad_weight * zb[f])
        return axis1, axis2, top3_probs[axis1] + top3_probs[axis2]

    win_top3 = {f for f, _ in sorted(win_probs.items(), key=lambda kv: -kv[1])[:3]}
    place_top3 = {f for f, _ in sorted(top3_probs.items(), key=lambda kv: -kv[1])[:3]}
    overlap = win_top3 & place_top3
    if not overlap:
        return None
    if len(overlap) >= 2:
        cands = sorted(overlap, key=lambda f: -top3_probs[f])
        axis1, axis2 = cands[0], cands[1]
    else:
        axis1 = next(iter(overlap))
        rest = sorted((f for f in top3_probs if f != axis1), key=lambda f: -top3_probs[f])
        if not rest:
            return None
        axis2 = rest[0]
    axis_sum = top3_probs[axis1] + top3_probs[axis2]
    return axis1, axis2, axis_sum


def rank_7s_wt_overlap_n(
    axis1: int, axis2: int, wt_honmei: int | None, wt_taikou: int | None,
) -> int | None:
    """S7の軸2車とWINTICKET公式予想の◎◯（honmei/taikou）との重なり数を返す。

    wt_honmei: prediction_mark==1（◎）の frame_no。
    wt_taikou: prediction_mark==2（◯）の frame_no。
    いずれか欠損時は None（重なり判定不能・rank_7s_daily_select では除外対象）。
    """
    if wt_honmei is None or wt_taikou is None:
        return None
    return len({axis1, axis2} & {wt_honmei, wt_taikou})


# 2026-07-27: 軸2車がWINTICKET公式印◎◯△（mark1/2/3）のうち2つと一致する場合、
# 市場人気と重なり払戻が下がりやすいという仮説を検証（exp_s4s9_3mark_overlap_wt.py・
# S7+S9現行ライブ採用条件と同一母集団・n=2,560）:
#   軸2車のうち2車が◎◯△のいずれかと一致: n=1,357 ROI182.9%
#   それ以外                          : n=1,203 ROI434.4%
# 払戻トップ5は全てこの「2車一致」に該当しない側（overlap3<=1）に集中しており、
# 「2車一致」側でも黒字(183%)ではあるが明確にROIが低い。ただし軸2車のうち
# **1車のみ**が◎◯△のいずれかと一致するのは既存のwt_overlap_n==1（S）の定義上
# 常に発生する（除外しない）。除外対象は軸2車**両方**が◎◯△のいずれかと一致する
# ケースのみ。既存のwt_overlap_n（◎◯=mark1/2のみで判定・完全一致=2を既に除外）
# とは独立な追加ゲート（mark3=△も加味）。
#
# 【2026-07-31改定】S7/7Aはこのゲートを撤廃した（下記rank_7s_daily_select/
# rank_7a_daily_select参照。当時の検証は汚染モデル時代のもので、クリーンな
# 月次vintageモデルでの再検証ではaxis_sum<=1.5との組み合わせにより
# mark3ゲート無しの方がROI・的中率とも上回った）。
# S9/9A（rank_9s_daily_select/rank_9a_daily_select）は9車立てでは軸選定の母集団が
# 異なりS7と同一の再検証を行っていないため、このゲートを引き続き使用する。
RANK_7S_MARK3_OVERLAP_MAX = 1


def rank_7s_wt_mark3_overlap_n(
    axis1: int, axis2: int,
    wt_honmei: int | None, wt_taikou: int | None, wt_ana: int | None,
) -> int | None:
    """S7/S9の軸2車とWINTICKET公式印◎◯△（mark1/2/3・honmei/taikou/ana）との
    重なり数を返す（rank_7s_wt_overlap_nの◎◯のみの判定に△を加えた拡張版）。

    wt_ana: prediction_mark==3（△）の frame_no。
    いずれか欠損時は None（判定不能・rank_7s_daily_select/rank_9s_daily_select では
    フェイルセーフとして除外対象扱いにする）。
    """
    if wt_honmei is None or wt_taikou is None or wt_ana is None:
        return None
    return len({axis1, axis2} & {wt_honmei, wt_taikou, wt_ana})


# S7のSS(重なり0)のうち、軸2車のいずれかが各グレード最上位クラス（S1/A1）だと
# 配当が下がりやすい傾向を確認（2026-07-23・honest全期間検証）。当初はSS内の
# 格上非該当サブセットを観察用サブランク"SS+"として分岐表示していたが、
# サンプル数が少なすぎる（全期間で数十件規模）という理由でユーザー判断により
# 2026-07-27に廃止・SSへ統合した（picks_history.gate_label='SS+'の既存行も
# 'SS'へ一括更新済み。買い目・投資額は元々SSと同一のため実害はない）。
#
# 2026-07-31: SS自体（7SS/9SS・重なり0）も廃止・Sへ統合した。導入初期
# （2024-01〜07）は月13〜27件出ていたが、モデルの軸選定がWT公式印に近づく
# 方向へ進化した結果、2024-09以降は月0〜4件（2年間で19件）まで激減し
# 実質的にほぼ発生しない条件になっていたため（ユーザー判断）。
# 既存picks_history.gate_label IN ('SS','SS+') 行も 'S' へ一括更新済み。
# 買い目・投資額は元々SS/SS+/Sで同一のため実害なし。
# axis1_class/axis2_classパラメータは廃止後もコール側の互換のため残置（未使用）。


def rank_7s_gate_label(
    wt_overlap_n: int | None,
    axis1_class: str | None = None, axis2_class: str | None = None,
) -> str | None:
    """S7の表示ランク(gate_label)を返す。

    - wt_overlap_n == 0 または 1: "S"（2026-07-31以前は重なり0を"SS"として
      分岐表示していたが、発生頻度が実質ゼロまで激減したため廃止・Sへ統合）。
    - それ以外（重なり2・None）: None（除外対象）
    """
    if wt_overlap_n in (0, 1):
        return "S"
    return None


def rank_7s_daily_select(candidates: list[dict]) -> list[dict]:
    """S7の選出（2026-07-31改定: mark3ゲートを撤廃・axis_sum<=1.5に緩和）。

    candidates: 候補レースのリスト。各要素は最低限
      {"axis_sum": float, "wt_overlap_n": int | None, "entropy": float} を持つ dict。

    選出ロジック（全て閾値ゲート。件数による打ち切りは行わない）:
      - axis_sum > RANK_7S_AXIS_SUM_MAX（三連複が5倍未満に安くなりやすい極端な人気決着
        想定レース）は除外（2026-07-24導入。2026-07-31に1.3→1.5へ緩和）
      - entropy > RANK_7S_ENTROPY_MAX（フィールド全体の予測確率が拡散＝軸2車に集中して
        いない）は除外（2026-07-26導入。低いentropy＝軸2車に予測確率が集中し
        残り5車が拮抗、という状態が三連複高配当の的中と強く相関することを
        2024-2026の8四半期walk-forwardで確認。詳細はRANK_7S_ENTROPY_MAX定義部参照）。
        entropyキー欠損時は float("inf")扱い＝必ず除外する（フェイルセーフ。
        2026-07-26に0.0デフォルトだった旧実装が「欠損=常に通過」というフェイル
        オープンな挙動になっており、デプロイ当日の旧形式生候補JSON経由で
        entropyゲートが実質無効化される事故を招いたため修正済み）
      - wt_overlap_n == 0（◎◯と全く重ならない）: 上記ゲート通過分は全件採用
      - wt_overlap_n == 1（片方だけ重なる）: 上記ゲート通過分を全件採用
        （2026-07-26以前は axis_sum昇順で日次/バッチ上限cap件のみ採用していたが、
        「capを解除した生プールでentropyゲートが機能するか」を検証した結果、
        cap無しでentropyゲート単体の方が同数条件のaxis_sum選定より優れることを
        確認したため、件数capそのものを廃止した）
      - wt_overlap_n == 2（◎◯と完全一致）・None（WTマーク欠損）: 除外
        （完全一致は honest全期間検証でROI75.7%の赤字区分と判明したため）

    【2026-07-31撤廃】wt_mark3_overlap_n によるゲートは廃止した。
    クリーンな月次vintageモデルでのhonest全期間再検証
    （scripts/exp_s7_cdf_regime_full_period.py・2024-01〜2026-07・31ヶ月）で、
    axis_sum<=1.5との組み合わせにより mark3ゲート無しの方が
    的中率41.0%(旧34.0%)・ROI79.3%(旧78.5%)・月次ROI標準偏差17.3(旧43.7)・
    1日平均6.94件(旧0.61件)と全指標で上回ることを確認したため。
    詳細は RANK_7S_AXIS_SUM_MAX / RANK_7S_MARK3_OVERLAP_MAX 定義部のコメント参照。
    ※この変更によりS7の母集団が広がったため、旧mark3ゲートに依存していた
    7Aの選出ロジック(rank_7a_daily_select)も2026-07-31に2ゲート化し、
    新S7との重複選出がないことを検算済み（重複0件）。

    日次件数の上限（RANK_7S_DAILY_CAP）は本関数では適用しない（朝夜どちらか一方の
    バッチだけでは日次合計が分からないため）。日次合計への適用は
    rank_7s_evening_reselect() を参照。

    returns 採用された候補のリスト（axis_sum昇順・表示用の並び順のみ）。
    """
    pool = [
        c for c in candidates
        if c["axis_sum"] <= RANK_7S_AXIS_SUM_MAX
        and c.get("entropy", float("inf")) <= RANK_7S_ENTROPY_MAX
        and c.get("wt_overlap_n") in (0, 1)
    ]
    return sorted(pool, key=lambda c: c["axis_sum"])


def rank_7s_evening_reselect(
    day_raw: list[dict], night_raw: list[dict], locked_keys: set[str] = frozenset(),
) -> list[dict]:
    """S7の朝夜統合選出（2026-07-26改定: entropyゲート通過後、日次合計を
    RANK_7S_DAILY_CAP件まで entropy昇順（＝最も自信がある順）でトリムする）。

    day_raw/night_raw: 朝/夜それぞれの生候補（選出前の全件、rank_7s_select_axis+
      rank_7s_wt_overlap_n+entropy計算を通した dict のリスト。各要素に "race_key" が必要）。
    locked_keys: 既に買い判定済み（picks_history に bet_amount>0 で記録済み）の
      race_key の集合。ゲート・トリムいずれでも除外しない（実購入は取り消せない
      ため）。ロック済み候補は rank_7s_daily_select() のゲート判定より前に分離する
      （2026-07-26修正: ロック済みでもゲート内で先に弾かれれば結果的に未保護に
      なる抜け穴があったため、ゲート適用前に確定で救済する設計に変更）。

    RANK_7S_DAILY_CAP は honest全期間(832日)で実際にゲート通過が最大9件/日だった
    ことから、通常運用ではほぼ発火しない安全網として設計されている
    （exp_s4_daily_cap_by_entropy.py参照）。

    returns 採用された候補のリスト。
    """
    # 同一 race_key が朝夜の両方に居たら夜側（新しい情報で評価し直した方）を採る。
    # 2026-08-04 の第2パスは「朝に◎◯が未公開だったレース」を再評価するため、
    # 同じ race_key が day_raw（overlap=None・ゲートで落ちる）と night_raw の両方に
    # 現れる。現状は day 側が必ずゲートで落ちるので実害は無いが、素朴な連結のままだと
    # ゲート条件が変わった途端に同じレースを2行採用してしまうため明示的に潰す。
    merged: dict[str, dict] = {}
    for c in day_raw + night_raw:
        merged[c.get("race_key")] = c
    all_raw = list(merged.values())
    locked = [c for c in all_raw if c.get("race_key") in locked_keys]
    gated = rank_7s_daily_select([c for c in all_raw if c.get("race_key") not in locked_keys])
    unlocked = sorted(gated, key=lambda c: c["entropy"])
    remaining_budget = max(0, RANK_7S_DAILY_CAP - len(locked))
    return locked + unlocked[:remaining_budget]


# ═══════════════════════════════════════════════════════════════════════════
# S9（S7の9車立て版・独立ランク）— 2026-07-26 導入
#
# 背景: 2026-08開催予定「ドリームレース」（S級・毎年8月・過去3回2023-2025年
# 全て9車立て）をターゲットに含めるため、7車専用だったS7のロジックを9車立てへ
# 拡張した。9車立ては全レースの8.0%（約6.5件/日・7車の85.5%に次ぐ規模）。
# ユーザー判断（Option B）により、7車のS7とは独立した別ランクとして実装
# （表示・集計を分離。ボリューム・買い目コスト(7点流し=700円 vs 5点=500円)が
# 異なるため）。
#
# 軸選定(rank_7s_select_axis)・フィールドentropy計算(rank_7s_field_entropy)・
# WT◎◯重なり判定(rank_7s_wt_overlap_n)・表示ランク(rank_7s_gate_label)はいずれも
# 車数非依存の汎用実装のためそのまま再利用する。
#
# 買い目 = 三連複 軸2車 + 残り7車のいずれか1車（7点・オッズ下限なし）
#
# 検証（2026-07-26・quarterly walk-forwardモデルのpred_prob使用・オッズ非依存・
# 9車軸選定候補5,632件・2024-01-01〜2026-07-25）: 2024Q1(n=406, wt_overlap∈{0,1})
# のentropy下位25%点(=1.9938)だけを閾値として固定し、2024Q2〜2026Qbの残り
# 9四半期へブラインド適用（真のwalk-forward・9四半期**全て**で方向一致・
# 例外なし）:
#   entropy<=1.9938: n=495 的中41.8% ROI279.2%（9四半期全て126.9〜675.1%で黒字）
#   entropy> 1.9938: n=1,287 的中29.1% ROI 72.4%（9四半期全て50.3〜100.7%の赤字帯）
# wt_overlap_n==2（完全一致）は7車同様66-91%で不採用。wt_overlap_n==0（軸2車が
# WT公式◎◯と全く重ならない）は小n(3-53/四半期)だが多くの四半期でROI200〜4683%と
# 極めて高い（7車のSS+/SS帯と同型のパターン）。
#
# axis_sum閾値（RANK_7S_AXIS_SUM_MAX相当）は9車では未較正のため導入していない
# （entropy単体で真のwalk-forward検証済み・複数の未較正閾値を積み増すことに
# よる過学習リスクを避けた。将来的な追加検証の余地あり）。
RANK_9S_NE = 9                   # 対象車数（9車ちょうど）
RANK_9S_STAKE = unit_stake(7)     # 1,400円/点（7点=9,800円/レース）
RANK_9S_ENTROPY_MAX = 1.9938


def rank_9s_daily_select(candidates: list[dict]) -> list[dict]:
    """S9の選出。S7と同じ閾値ゲート方式（axis_sum閾値は9車では未導入）。

    candidates: 候補レースのリスト。各要素は最低限
      {"wt_overlap_n": int | None, "entropy": float} を持つ dict。

    選出ロジック:
      - entropy > RANK_9S_ENTROPY_MAX は除外（詳細は上部コメント参照）。
        entropyキー欠損時は float("inf")扱い＝必ず除外（フェイルセーフ。
        S7での同種事故を踏まえた設計）
      - wt_overlap_n == 0（◎◯と全く重ならない）・1（片方だけ重なる）:
        上記ゲート通過分を全件採用（件数capなし。S9は元々低ボリュームのため
        S7のようなRANK_9S_DAILY_CAP安全網は現時点で不要と判断）
      - wt_overlap_n == 2（◎◯と完全一致）・None（WTマーク欠損）: 除外
      - wt_mark3_overlap_n（軸2車とWT公式印◎◯△=mark1/2/3との重なり数）が2は
        除外（2026-07-27導入・S7と共通のゲート。詳細はRANK_7S_MARK3_OVERLAP_MAX参照）

    returns 採用された候補のリスト（axis_sum昇順・表示用の並び順のみ）。
    """
    pool = [
        c for c in candidates
        if c.get("entropy", float("inf")) <= RANK_9S_ENTROPY_MAX
        and c.get("wt_overlap_n") in (0, 1)
        and c.get("wt_mark3_overlap_n", 2) <= RANK_7S_MARK3_OVERLAP_MAX
    ]
    return sorted(pool, key=lambda c: c["axis_sum"])


# ═══════════════════════════════════════════════════════════════════════════
# 7A/9A（S7/S9の「惜しい」境界ランク・ボリューム拡大用）— 2026-07-27 導入
#
# ユーザー要望: S7/S9(SS+/SS/S)は日次ボリュームが小さい（7車合計約1.2件/日・
# 9車約0.25件/日）。ROIはS7/S9ほど高くなくてよいので、的中率のあるゾーンを
# フィルタして推奨レースを増やしたい（三連複2軸のまま・低〜中配当帯を狙う）。
#
# 検証（exp_7a9a_boundary_wt.py / exp_7a9a_deep_dive.py / exp_7a9a_combo_check.py・
# quarterly walk-forward・honest全期間2024-01-01〜2026-07-25）:
#   まず wt_overlap==2（◎◯完全一致）側を含めた単純なaxis_sum区切りを検討したが、
#   全10四半期でROI70〜96%と一度も100%を安定して超えず、市場効率の壁で不採用と判断。
#   代わりに「S7の3ゲート（axis_sum<=1.3・entropy<=1.8329・mark3<=1）のうち
#   "ちょうど1つだけ"不合格の"惜しいレース"」を三連複2軸のまま評価したところ、
#   直近7四半期連続でROI100%超（101.7〜172.9%）・直近4四半期合算ROI150.3%
#   （n=778・約2.3〜4.0件/日）という頑健な結果を確認。wt_overlap==2は依然として
#   対象外（この条件でも常にROI<100%）。
#
# 設計:
#   母集団 = rank_7s_select_axis()/s9相当で軸選定成功 ∧ wt_overlap_n∈{0,1}（◎◯完全一致
#     と印欠損は既存同様に除外）。
#   7A: axis_sum<=RANK_7S_AXIS_SUM_MAX・entropy<=RANK_7S_ENTROPY_MAX
#       の2条件のうち、不合格がちょうど1個（0個=S7・2個とも不合格=対象外）。
#       【2026-07-31改定】旧来はmark3も含む3条件だったが、S7自体がmark3ゲートを
#       撤廃した（rank_7s_daily_select参照）ため、7Aも2条件に揃えた（mark3を条件に
#       残すと「mark3のみ不合格」の候補が新S7にも旧7Aにも該当し重複選出になる
#       ため）。
#   9A: 9車はaxis_sum閾値が未導入・S9側のmark3ゲートは変更していないため、
#       entropy<=RANK_9S_ENTROPY_MAX・mark3<=RANK_7S_MARK3_OVERLAP_MAX の2条件のうち、
#       不合格がちょうど1個（変更なし）。
#   S7/S9とは論理的に排他（全条件合格=S7/S9、ちょうど1条件のみ不合格=7A/9A）。
#   新7A(2条件)とのhonest全期間再検証で重複選出0件を確認済み
#   （scripts/exp_7a_2gate_redefinition_validation.py・2024-01〜2026-07）。
#   買い目 = 三連複 軸2車+残り流し（7車5点・9車7点。S7/S9と同一構造）。
#
# 【2026-07-31・7A 2ゲート化の honest全期間再検証】
#   旧7A(3ゲート・mark3含む): 4,691R・4.97件/日・的中42.8%・ROI81.4%・
#     月次ROI標準偏差22.0
#   新7A(2ゲート・mark3撤廃): 8,306R・8.81件/日・的中44.8%・ROI77.6%・
#     月次ROI標準偏差13.4
#   ROIは控除率75%を上回る水準を維持しつつ、的中率向上・変動縮小・
#   件数増（約1.8倍）を確認したため採用。
#
# 直近実力（旧数値・参考。2026-07-31の2ゲート化で7Aの実績は上記に更新）:
#   7A 約2.3〜4.0件/日 + S7 約1.15件/日 ≈ 7車合計 約3.5〜5件/日（旧設定時）
#   9A 約0.5〜1.7件/日 + S9 約0.25件/日 ≈ 9車合計 約0.75〜2件/日（変更なし）
# ═══════════════════════════════════════════════════════════════════════════

RANK_7A_STAKE = unit_stake(5)  # 2,000円/点（7車5点=10,000円/レース）
RANK_9A_STAKE = unit_stake(7)  # 1,400円/点（9車7点=9,800円/レース）

# ───────────────────────────────────────────────────────────────────────────
# 7A 低配当レース見送りゲート（2026-08-09 新設・STEP1C で確定）
#
# `axis_sum`（= 軸2車の pred_top3_pct 合計 = 仕様書の `top2_sum`）が高いレースは
# 本命集中＝低配当になりやすい。**下位 q20（高配当側20%）だけ買う**。
#
# STEP1C 実測（walk-forward の honest 確率・掃引〜2025-12末／確認2026年）:
#   7A  現行 ROI 83.5% → q20 90.6%（掃引） / 85.8% → 91.1%（確認・閾値は掃引窓で固定）
#   7C  どの閾値でも改善せず（掃引はむしろ −6.0pt）→ ゲート導入しない
#   7S  窓で符号反転（掃引 +8.8pt → 確認 −1.0pt）→ ゲート導入しない
#
# ⚠️ **90〜98% はまだ 100% 割れ**＝損が薄まるだけで勝ちではない。出走を約80%削る
#    （4.3→約0.9レース/日）売上とのトレードオフを承知の上での採用（ユーザー判断）。
#
# ⚠️ **閾値は固定値にしない。** モデルを差し替えると axis_sum の分布ごと動くため、
#    固定値だと選抜率が知らないうちに変わる（このリポジトリで繰り返している事故）。
#    直近母集団の分位点から毎回引き直す。
# ───────────────────────────────────────────────────────────────────────────

RANK_7A_TOP2_GATE_Q = 0.20
"""買う分位。下位 q20（＝高配当側20%）だけ購入する。"""

RANK_7A_TOP2_GATE_MIN_N = 40
"""分位点を信用する最小標本数。これ未満はフォールバック閾値を使う。

7A のプールは約3.4件/日なので 40 件 ≒ 12日。100件(≒30日)にすると導入直後の
1ヶ月がまるごとフォールバック運用になり、下の較正ズレを長く引きずる。
"""

RANK_7A_TOP2_GATE_FALLBACK = 1.432
"""履歴が足りないときの閾値。

🔴 **STEP1C が出した 1.424 をそのまま使ってはいけない。** あの値は walk-forward
   ヴィンテージモデルの pp3 から出した q20 で、**本番モデルが出す axis_sum とは
   分布が違う**。実測（本番モデルで 2026-06-20〜08-08 のプールを再生成・n=36）では
   1.424 は上位 16.7% しか通さず、q20 は 1.432 だった。
   ここは「STEP1C の数値」ではなく「**本番モデルのプール分布**」で較正すること。

⚠️ n=36 の暫定値。プールJSONが貯まれば `rank_7a_top2_threshold()` の動的分位が
   引き継ぐので、この定数が効くのは導入後 12 日ほどだけ。
"""

RANK_7A_TOP2_GATE_LOOKBACK_DAYS = 90
"""分位点を取る直近母集団の日数。"""


def rank_7a_top2_threshold(
    history: list[float],
    q: float = RANK_7A_TOP2_GATE_Q,
    min_n: int = RANK_7A_TOP2_GATE_MIN_N,
    fallback: float = RANK_7A_TOP2_GATE_FALLBACK,
) -> float:
    """直近母集団の axis_sum から q 分位のゲート閾値を返す。

    history: 直近の 7A 候補（または採用実績）の axis_sum の並び。順序は問わない。

    標本が min_n 未満なら fallback を返す。**空リストでも必ず有限値を返す**
    （閾値が None になると呼び出し側が「ゲート無効」と解釈して全件通してしまう）。
    """
    vals = sorted(v for v in history if v is not None)
    if len(vals) < min_n:
        return fallback
    idx = min(int(q * len(vals)), len(vals) - 1)
    return float(vals[idx])


def load_7a_pool_axis_sums(
    picks_dir, before_date: str, days: int = RANK_7A_TOP2_GATE_LOOKBACK_DAYS,
    suffixes: tuple[str, ...] = ("_s7a_pool.json", "_night_s7a_pool.json"),
) -> list[float]:
    """`_s7a_pool.json`（ゲート**前**のプール）から直近 days 日の axis_sum を集める。

    live（候補生成）と rebuild（過去分再構築）で**同じ母集団**を見るための共有実装。
    ここが2箇所に分かれると、同じ日付でも live と rebuild で閾値が変わって
    picks_history が毎朝書き換わる。

    ファイルが無い日は飛ばす。読めない日があっても呼び出し元を止めない。

    suffixes: 読むプールファイルの接尾辞。市場合意枠（overlap==2）は
      **別プール**（`_s7a_ma_pool.json`）で閾値を出す。同じプールに混ぜると
      分布がずれて**既存 7A の閾値まで動く**（`RANK_7A_MARKET_AGREE` のコメント参照）。
    """
    import json as _json
    from datetime import date as _date
    from datetime import timedelta as _timedelta
    from pathlib import Path as _Path

    try:
        base = _date.fromisoformat(before_date)
    except ValueError:
        return []
    out: list[float] = []
    for i in range(1, days + 1):
        d = (base - _timedelta(days=i)).isoformat()
        for suffix in suffixes:
            p = _Path(picks_dir) / f"wave_picks_wt_{d}{suffix}"
            if not p.exists():
                continue
            try:
                with open(p, encoding="utf-8") as f:
                    for c in _json.load(f):
                        if c.get("axis_sum") is not None:
                            out.append(float(c["axis_sum"]))
            except (OSError, ValueError):
                continue
    return out


def rank_7a_gate_chronological(
    pool: list[dict], seed_history: list[tuple[str, float]] | None = None
) -> list[dict]:
    """プールを**日付順に**ゲートへ通す（過去分再構築用）。

    その日の閾値は「**その日より前**の直近 RANK_7A_TOP2_GATE_LOOKBACK_DAYS 日の
    プール」から取る。live と同じ規則で、当日以降を覗かない（look-ahead しない）。

    seed_history: (race_date, axis_sum) の並び。窓をまたいで再構築するときに
      直前の窓のプールを引き渡すために使う。**呼び出し中に追記される**ので、
      複数窓を時系列順に処理すれば履歴が途切れない。

    ⚠️ ここで `rank_7a_top2_threshold` に渡す履歴が空だとフォールバック定数になる。
       窓の先頭だけフォールバックで走るのは避けられないが、seed_history を渡せば
       2窓目以降は連続する。
    """
    from datetime import date as _date
    from datetime import timedelta as _timedelta

    history: list[tuple[str, float]] = seed_history if seed_history is not None else []
    by_date: dict[str, list[dict]] = {}
    for c in pool:
        by_date.setdefault(c.get("race_date", ""), []).append(c)

    kept: list[dict] = []
    for d in sorted(by_date):
        try:
            cutoff = (_date.fromisoformat(d) - _timedelta(days=RANK_7A_TOP2_GATE_LOOKBACK_DAYS)
                      ).isoformat()
        except ValueError:
            cutoff = ""
        trailing = [v for (dd, v) in history if cutoff <= dd < d]
        thr = rank_7a_top2_threshold(trailing)
        keep, _ = rank_7a_top2_gate(by_date[d], thr)
        kept.extend(keep)
        history.extend((d, c["axis_sum"]) for c in by_date[d] if c.get("axis_sum") is not None)
    return kept


def rank_7a_top2_gate(candidates: list[dict], threshold: float) -> tuple[list[dict], list[dict]]:
    """7A 候補を低配当見送りゲートに掛け、(購入する候補, 見送る候補) を返す。

    見送り側には `skip_reason='7A_top2_gate'` と判定に使った閾値を書き込む
    （なぜ落ちたかが後から読めないと、件数が減ったときに原因を切り分けられない）。
    """
    keep: list[dict] = []
    skip: list[dict] = []
    for c in candidates:
        if c.get("axis_sum") is not None and c["axis_sum"] <= threshold:
            keep.append(c)
        else:
            c["skip_reason"] = "7A_top2_gate"
            c["top2_gate_threshold"] = round(threshold, 4)
            skip.append(c)
    return keep, skip


def rank_7a_daily_select(
    candidates: list[dict], top2_threshold: float | None = None
) -> list[dict]:
    """7Aの選出: S7の2ゲート(axis_sum/entropy)のうちちょうど1つだけ不合格の候補。

    top2_threshold を渡すと **低配当レース見送りゲート**（2026-08-09・STEP1C）を
    適用し、axis_sum がこの値以下の候補だけを返す。None なら従来どおり全件。
    閾値は `rank_7a_top2_threshold()` で直近母集団から動的に取ること。

    candidates: 各要素は最低限
      {"axis_sum": float, "entropy": float, "wt_overlap_n": int | None} を持つ dict。

    【2026-07-31改定】旧来はmark3も含む3ゲートだったが、S7自体がmark3ゲートを
    撤廃した（rank_7s_daily_select参照）ため2ゲートに揃えた。新S7との重複選出が
    ないことをhonest全期間で検算済み（本セクション冒頭コメント参照）。

    - wt_overlap_n ∈ {0,1} 必須（◎◯完全一致=2・マーク欠損=None は対象外、S7と同様）
    - **axis_sum だけが不合格**（entropy は合格）の候補のみ採用

    【2026-08-05改定】旧来は「不合格ちょうど1つ」だったため、
      A群 axis_sum だけ不合格（軸2車が堅い）  的中52-53% / 中央値0.78倍
      E群 entropy  だけ不合格（レースが荒れ）  的中30-32% / 中央値1.57倍
    という**性質が正反対の2群の混合**になっていた（同じラベルなのに当たり方も
    配当も一貫しない）。E群は 7SS（同一ライン条件付き）へ分離したため、
    7A は A群のみを指す。詳細は RANK_7SS_STAKE 定義部のコメント参照。

    returns 採用された候補のリスト（axis_sum昇順）。
    """
    pool = []
    for c in candidates:
        if c.get("wt_overlap_n") not in (0, 1):
            continue
        axis_ok = c["axis_sum"] <= RANK_7S_AXIS_SUM_MAX
        ent_ok = c.get("entropy", float("inf")) <= RANK_7S_ENTROPY_MAX
        if (not axis_ok) and ent_ok:
            pool.append(c)
    if top2_threshold is not None:
        pool, _ = rank_7a_top2_gate(pool, top2_threshold)
    return sorted(pool, key=lambda c: c["axis_sum"])


# ═══════════════════════════════════════════════════════════════════════════
# 7A の市場合意枠（`wt_overlap_n == 2`・2026-08-11 追加・ユーザー指示）
#
# 【背景】被覆マップ上、`overlap == 2`（モデルの軸2車が WT の ◎○ と完全一致）は
#   7B の枠で、その 7B は **順序一致 ∧ race_type=="準決勝"** まで絞り込まれている。
#   残り（一般・選抜・特選…や順序不一致）は**どのランクにも入らない空白**だった。
#   2026-08-10 の川崎4R/6R/7R がこれに当たり、ユーザーが手動で 7A として入稿した。
#
# 【何を足すか】`overlap == 2` かつ **7B が取らない**もののうち、
#   **7A と同じ形**（axis_sum だけ不合格・entropy は合格）だけを 7A へ足す。
#   買い方も 7A と同一（三連複 軸2車 + 相手5点総流し・傾斜配分）＝手動入稿と同じ形。
#
# 🔴 **既存 7A のプールとゲート閾値には混ぜない。**
#   7A の低配当見送りゲートは「直近プールの axis_sum q20」で閾値を決める。
#   `overlap == 2` は市場が完全合意した堅い群で axis_sum の分布がずれるため、
#   同じプールに入れると**既存 7A の閾値まで動いて選ばれるレースが変わる**。
#   別プール（`_s7a_ma_pool.json`）で独立に閾値を出し、候補リストだけを結合する。
#
# 🔴 **7B の定義と完全に排他にする。** netkeirin の優先順位は 7A > 7B なので、
#   ここで 7B のスライスを含めると **7A が 7B のレースを奪う**。7B は
#   ROI 82〜83% を3窓で保った唯一の切り口なので、絶対に食わせない。
#
# ⚠️ **この帯は既に測定されており、控除率の壁を越えない。**
#     overlap=2 全体        … 的中 56.3% / ROI 72.4% / 配当中央 4.0倍 / ガミ率 60.2%
#     空白3 全件(48.5件/日) … 確認窓 ROI 74.3% [71.6, 76.7]
#   （memory: keirin_7car_coverage_gaps_2026_08_05 / strategy_wt の 7B 定義部）
#   **ユーザーが実測を承知のうえで採用を指示**（2026-08-11）。的中体験を重視した
#   商品判断であり、ROI 改善を意図したものではない。畳むときは
#   `RANK_7A_MARKET_AGREE = False` の1行で止まる。
#
# 【件数】実測（2026-07-29〜08-10 の生候補13日分）:
#     7A の形 かつ overlap∈{0,1}（現行プール）     3.23件/日
#     7A の形 かつ overlap==2 で 7B 非該当（追加） 27.69件/日 ← ゲート前
#   ゲート（自プールの q20）通過後は 5〜6件/日 の想定。**ゲートを外すと28件/日**に
#   なり 7A の性格がこの帯に置き換わるので、広げるときは件数を必ず確認すること。
# ═══════════════════════════════════════════════════════════════════════════

#: 市場合意枠（overlap==2）を 7A に含めるか。False で従来どおり overlap∈{0,1} のみ。
RANK_7A_MARKET_AGREE = True

#: この日以降のレースにだけ適用する（YYYY-MM-DD）。
#
# 🔴 **過去を書き換えないため**の境界。7A の過去実績（ROI 80.1%）は
#    overlap∈{0,1} だけで積まれたもので、そこへ ROI 72〜74% の帯を遡って
#    混ぜると Web の 7A 実績が別物になる。
# 🔴 **live と rebuild の両方がこの境界を見る。** 毎朝 08:40 の
#    `reconcile_walkforward_tail.sh` は前日ぶんの `#7A` 行を**一旦全削除してから**
#    再構築するので、rebuild 側にこの枝が無いと **live が書いた行が毎晩消える**
#    （2026-08-06 に 7A/7B で実際に起きた rebuild×live 混在と同型）。
RANK_7A_MARKET_AGREE_FROM = "2026-08-11"


def rank_7a_race_date(c: dict) -> str:
    """候補の開催日を "YYYY-MM-DD" で返す。取れなければ空文字。

    live の生候補（`_s7_raw_candidates.json`）は `race_date` を持たず
    `race_key`（"20260810_34_04"）しか無い一方、rebuild 側は `race_date` を持つ。
    **両方で同じ判定をする**ためにここで吸収する（片方だけ日付が取れないと、
    live と rebuild で選ばれるレースが変わって毎晩 picks_history が書き換わる）。
    """
    d = c.get("race_date")
    if d:
        return str(d)
    rk = str(c.get("race_key") or "")
    head = rk.split("_")[0]
    if len(head) == 8 and head.isdigit():
        return f"{head[:4]}-{head[4:6]}-{head[6:]}"
    return ""


def rank_7a_market_agree_active(race_date: str | None) -> bool:
    """その日付で市場合意枠が有効か。日付不明なら**無効**（安全側）。"""
    if not RANK_7A_MARKET_AGREE or not race_date:
        return False
    return str(race_date) >= RANK_7A_MARKET_AGREE_FROM


def rank_7a_is_7b_slice(c: dict) -> bool:
    """7B が取るスライス（overlap==2 ∧ 順序一致 ∧ race_type が 7B 指定）か。

    🔴 `RANK_7B_RACE_TYPES` は**完全一致**で判定する（部分一致にすると
       "チャレンジ準決勝"/"ガールズ準決勝" という未検証の母集団が約30%混入する。
       7B 定義部のコメント参照）。
    """
    return (c.get("wt_overlap_n") == 2
            and not c.get("order_disagree")
            and c.get("race_type") in RANK_7B_RACE_TYPES)


def rank_7a_market_agree_pool(candidates: list[dict]) -> list[dict]:
    """市場合意枠（overlap==2 で 7B が取らない）のうち 7A と同じ形のものを返す。

    形の条件は `rank_7a_daily_select` と同一（axis_sum だけ不合格・entropy 合格）。
    ゲートは掛けない（呼び出し側が**自プールの**閾値で掛ける）。
    """
    pool = []
    for c in candidates:
        if not rank_7a_market_agree_active(rank_7a_race_date(c)):
            continue
        if c.get("wt_overlap_n") != 2 or rank_7a_is_7b_slice(c):
            continue
        axis_ok = c["axis_sum"] <= RANK_7S_AXIS_SUM_MAX
        ent_ok = c.get("entropy", float("inf")) <= RANK_7S_ENTROPY_MAX
        if (not axis_ok) and ent_ok:
            pool.append(c)
    return sorted(pool, key=lambda c: c["axis_sum"])


def rank_7ss_daily_select(candidates: list[dict]) -> list[dict]:
    """7SSの選出: entropy だけ不合格 ∧ 軸2車が同一ライン。

    candidates: 各要素は最低限
      {"axis_sum": float, "entropy": float, "wt_overlap_n": int | None,
       "same_line": bool} を持つ dict。

    - wt_overlap_n ∈ {0,1} 必須（7S/7Aと同様）
    - axis_sum は合格（<=RANK_7S_AXIS_SUM_MAX）かつ entropy が不合格
    - **軸1と軸2が同一ライン**（`same_line`）。判定は rank_7ss_same_line()。
      候補生成側で埋める。**未取得は False 側に倒す**（推奨を増やさない）

    returns 採用された候補のリスト（entropy昇順＝荒れが小さい順）。
    """
    pool = []
    for c in candidates:
        if c.get("wt_overlap_n") not in (0, 1):
            continue
        if c["axis_sum"] > RANK_7S_AXIS_SUM_MAX:
            continue
        if c.get("entropy", float("inf")) <= RANK_7S_ENTROPY_MAX:
            continue
        if not c.get("same_line"):
            continue
        pool.append(c)
    return sorted(pool, key=lambda c: c.get("entropy", 0.0))


# ═══════════════════════════════════════════════════════════════════════════
# RANK_7S への統合（2026-08-14・ユーザー判断）
#
# 7SS / 7S / 7A は**買い目構造が完全に同一**（三連複 軸2車+5点流し）で、違うのは
# ゲートの通り方だけだった。picks_history の全live記録（n=7,461・32ヶ月）では
#
#     7SS ROI 79.0% / 7S 79.7% / 7A 85.8%
#
# と**設計と逆順**（境界ランクの 7A が最良）で、差はいずれも有意でなく
# （7A −(7SS+7S) = +6.3pt・95%CI [-0.7, +13.5]）、設計どおりの順序になった月は
# 32ヶ月中7（偶然なら5.3）。払戻中央値・ガミ率・2万円超率まで一致しており、
# **商品としても3つは同じもの**だった。3つに分けて見せる根拠が無いので1本化する。
#
# 🔴 **選別は変えない**。3つは互いに排他:
#     7S  : axis_sum 合格 ∧ entropy 合格
#     7A  : axis_sum 不合格 ∧ entropy 合格
#     7SS : axis_sum 合格 ∧ entropy 不合格 ∧ 軸2車が同一ライン
#   したがって統合は**和集合＝ラベルの付け替え**で、買うレースは1件も増減しない。
#   ゲートの意味（どちらが落ちたか）は失われるが、それは ROI・的中率のどちらとも
#   相関していないことを上記で確認済み。
# ═══════════════════════════════════════════════════════════════════════════


def rank_7s_merged_daily_select(
    candidates: list[dict], top2_threshold: float | None = None,
) -> list[dict]:
    """統合後の 7S の選出＝旧 7S ∪ 7A ∪ 7SS。

    top2_threshold: 7A に掛ける低配当見送りゲート（STEP1C）。本番と同じ値を渡すこと。

    🔴 **3つの選別関数をそのまま呼ぶ**（条件を書き直さない）。書き直すと
       「片方だけ直る」を作れる。排他性はここで検算する。
    """
    picked = (rank_7s_daily_select(candidates)
              + rank_7a_daily_select(candidates, top2_threshold)
              + rank_7ss_daily_select(candidates))
    keys = [c.get("race_key") for c in picked if c.get("race_key") is not None]
    if len(keys) != len(set(keys)):
        dup = sorted({k for k in keys if keys.count(k) > 1})
        raise AssertionError(
            "7S/7A/7SS が同じレースを選んだ（排他のはず）: " + ", ".join(map(str, dup)))
    return sorted(picked, key=lambda c: c["axis_sum"])


def rank_9a_daily_select(candidates: list[dict]) -> list[dict]:
    """9Aの選出: S9の2ゲート(entropy/mark3)のうちちょうど1つだけ不合格の候補。

    rank_7a_daily_select() の9車版。9車はaxis_sum閾値が未導入（S9同様）のため、
    entropy<=RANK_9S_ENTROPY_MAX・mark3<=RANK_7S_MARK3_OVERLAP_MAX の2条件のうち
    不合格がちょうど1個の候補のみ採用する。
    """
    pool = []
    for c in candidates:
        if c.get("wt_overlap_n") not in (0, 1):
            continue
        mark3 = c.get("wt_mark3_overlap_n")
        if mark3 is None:
            continue
        ent_ok = c.get("entropy", float("inf")) <= RANK_9S_ENTROPY_MAX
        mark3_ok = mark3 <= RANK_7S_MARK3_OVERLAP_MAX
        n_fail = (not ent_ok) + (not mark3_ok)
        if n_fail == 1:
            pool.append(c)
    return sorted(pool, key=lambda c: c["axis_sum"])


# ═══════════════════════════════════════════════════════════════════════════
# 7B（◎◯一致だが順序・相手で市場と不一致・三連複3点）— 2026-08-03 導入
#
# 背景（ユーザー方針）:
#   「予想家としての売りは単純な市場との不一致を避けることに価値を見出される
#     ため、7S/7Aの方針は正しい。ただし ◎◯ が一致してもある程度の配当を
#     見込める・的中率が他よりも高い・相手を絞ることができる時は価値がある。」
#
# 7S/7A は wt_overlap_n==2（軸2車がWT公式印◎◯と完全一致）を全除外している。
# しかしモデルが公式印へ収束する方向に進化した結果、この完全一致が多数派に
# なり、対象レースが構造的に枯渇した（overlap∈{0,1}の比率:
# 2024-01 68.6% → 2025年以降 18〜23%。7S+7A の選出は 39件/日 → 12件/日）。
# 2026-08-02・08-03 は overlap∈{0,1} のレースを1本残らず採用しても6件・5件で、
# entropy/axis_sum をどれだけ緩めても1件も増えない状態だった。
#
# 【検証: honest 月次凍結vintage・2025-01〜2026-08・579日・36,791候補】
#   scripts/exp_7s7a_overlap2_conditional_value.py / _sweep.py / _disagreement.py
#
#   ① overlap2 は「的中率は高いが配当が消えている」:
#        現行7S+7A(K=5): 13.42件/日 的中36.9% ROI78.3% 的中中央値5.9倍 ガミ率41.2%
#        overlap2 (K=5): 50.01件/日 的中56.3% ROI72.4% 的中中央値4.0倍 ガミ率60.2%
#      的中率は+19.4pt だが、当たっても賭け金を割る（ガミ）率が6割。
#   ② entropy上限 × 相手集中度 × 買い目点数Kの120セルを掃引したが、
#      ROIは全セル 72〜76% で完全に平坦（控除率の壁）。「高ROIの隠れ帯」は無い。
#      的中率と配当は「予測確率の集中度」という同一軸の両端で、同時に立たない。
#   ③ ただし**相手側で市場と不一致にする**と配当が戻る:
#        overlap2・相手上位3点（△込み）: 的中47.0% ROI73.6% ガミ42.4% 中央値3.4倍 20倍超175本
#        overlap2・相手上位3点（△除外）: 的中27.3% ROI74.7% ガミ10.8% 中央値6.1倍 20倍超435本
#      さらに順序不一致（モデルのpred_win最上位 ≠ WT◎・overlap2の11.2%）を
#      重ねると ROI が現行7S/7Aと同水準まで戻る。これを 7B として採用する。
#
# 【7B の実績（honest・2025-01〜2026-08）】
#     5.58件/日・的中25.2%・ROI78.7%（現行7S+7A は 78.3%）
#     ガミ率8.1%（現行41.2%）・的中中央値6.8倍（現行5.9倍）
#     20倍超64本・最高116.6倍
#     年次 2025:78.6% / 2026:78.8%、四半期7期すべて68〜89%で崩れなし
#     月次ROI<60% は20ヶ月で0回・月次ROI標準偏差14.3（現行7Sは13.3）
#
# 【重要な位置づけ】
#   ROI は改善しない（どの案も控除率75%の壁の周辺から出ない）。
#   本ランクは「ROI同等のまま件数・見せ場・ガミ率を改善する」ための増枠であり、
#   収支改善策ではない。[[keirin_clean_baseline_market_efficiency_2026_07_30]]。
#
# 【設計】
#   母集団 = 7車立て ∧ rank_7s_select_axis 成功 ∧ wt_overlap_n == 2
#            （7S/7A とは wt_overlap_n で論理的に排他。重複選出は起こり得ない）
#   ゲート = 順序不一致のみ（entropy/axis_sum ゲートは掛けない）。
#            entropy<=1.8329 を追加すると 3.54件/日・ROI79.8% と一見良くなるが、
#            月次ROI標準偏差が 14.3→24.9 に悪化し ROI60%割れ月が0→3回に増える
#            ため不採用（件数も足りない）。
#   買い目 = 三連複 軸2車 + 相手（残り5車から WT△(ana) を除外し pred_prob 上位
#            RANK_7B_LEGS 車）＝ 3点。7S/7A の5点流しとは点数が異なる。
#   日次上限 = なし（honest 5.58件/日で暴走の懸念がないため。7S の
#              RANK_7S_DAILY_CAP のような安全網は設けていない）。
# ═══════════════════════════════════════════════════════════════════════════

RANK_7B_NE = 7      # 対象車数（7車ちょうど・7S/7Aと同じ）
RANK_7B_LEGS = 3     # 相手の購入点数（△除外後の pred_prob 上位K車）
RANK_7B_STAKE = unit_stake(RANK_7B_LEGS)  # 3,300円/点（3点=9,900円/レース）


def rank_7b_order_disagree(win_probs: dict[int, float], wt_honmei: int | None) -> bool | None:
    """7Bの順序不一致判定: モデルの単勝予測 pred_win 最上位が WT◎ でないか。

    win_probs:  {frame_no: pred_win}（rank_7s_select_axis と同じ入力）
    wt_honmei:  prediction_mark==1（◎）の frame_no

    軸2車が◎◯と完全一致していても、モデルが「◯の方が強い」と見ているなら
    完全なコンセンサスではない、という部分的不一致の検出。

    returns True=不一致（7B対象）/ False=一致 / None=判定不能（◎欠損・要除外）
    """
    if wt_honmei is None or not win_probs:
        return None
    return max(win_probs, key=lambda f: win_probs[f]) != wt_honmei


def rank_7b_select_legs(
    others: list[int], top3_probs: dict[int, float], wt_ana: int | None,
    k: int = RANK_7B_LEGS,
) -> list[int]:
    """7Bの相手選択: 残り5車から WT△(ana) を除外し pred_prob 上位k車を返す。

    others:     軸2車を除いた残り車（通常5車）
    top3_probs: {frame_no: pred_prob}
    wt_ana:     prediction_mark==3（△）の frame_no。None なら除外しない。

    △を切ることが配当を戻す本体（検証: 的中中央値3.4倍→6.1倍・ガミ率42.4%→10.8%・
    20倍超175本→435本）。的中率は下がる（47.0%→27.3%）が、これは
    「市場が推す相手を買わない」という7B設計の意図そのものである。
    """
    ranked = sorted(others, key=lambda x: -top3_probs.get(x, 0.0))
    if wt_ana is not None:
        ranked = [x for x in ranked if x != wt_ana]
    return ranked[:k]


# ═══════════════════════════════════════════════════════════════════════════
# 7B — 2026-08-05 に**中身を全面的に入れ替えた**（ユーザー判断）
#
# 【旧7B（2026-08-03〜2026-08-05）】overlap==2 ∧ **order不一致**。
#   測ったすべての窓で控除率75%の壁を越えず廃止した:
#   確認窓(2024-07〜2025-06) 71.1% / 掃引窓(2025-07〜2026-07) 75.3% / live全期間 75.9%。
#   絞り込みも全滅（朝の時点で△の強さを測る量はどれも確認窓を越えず、最良候補ですら
#   +8.2pt [−2.1, +19.1] と有意差なし）。memory: keirin_7b_filter_rejected_2026_08_05
#
# 【新7B（本定義）】overlap==2 ∧ **order一致** ∧ **race_type=="準決勝"**。
#   7車レースの被覆マップを作った結果、現行ランクがどこも触っていない空白が
#   構造上ちょうど3つあると判明し、そのうち唯一3窓を生き残ったのがこれ。
#
#   ⚠️ **旧7Bとは order_disagree の向きが真逆**（不一致→一致）。同じ「7B」の名前で
#      **別戦略**であり、picks_history の旧7B行と成績を合算してはいけない。
#
#   | 窓 | n | 件/日 | 的中 | ROI |
#   |---|---|---|---|---|
#   | 掃引窓 2025-07〜2026-07 | 2,258 | 5.94 | 29.8% | 82.8%（4窓すべて75%以上）|
#   | 確認窓 2024-07〜2025-06 | 1,727 | 4.73 | 30.1% | 83.0%（同上）|
#   | 未使用期間 2026-07-16〜08-04 | 115 | 5.75 | 32.2% | 81.7% |
#
#   採用根拠は「差」ではなく **水準が ±0.7pt に収まっていること**。同じ未使用20日で
#   7SS 48.4% / 7S 51.1% / 7A 115.4% と他ランクが激しく振れ、土台（空白3全件）自体も
#   74.3→68.4% に悪化した中で、この定義だけが水準を保った。確認窓のブートストラップで
#   土台との差 +8.7pt [+1.2, +16.3] 有意。裾依存も全ランク中最小（上位5本の配当が
#   回収に占める割合 5.2%・上位10本を除いても ROI 76.1%）。
#
# 【✂️ 含めないもの — いずれも実測で落とした】
#   - **決勝**: 掃引窓 87.1%（4窓合格）→ 確認窓 **66.7%** と完全反転。準決勝と束ねると
#     全体が有意でなくなる（+5.4pt [−0.6, +11.6]）
#   - **「準決勝」の部分一致**: `race_type` には `"チャレンジ準決勝"`(掃引窓 ROI 77.7%)・
#     `"ガールズ準決勝"` が別値で存在する。**検証は完全一致でしか行っていない**ので
#     `in` 判定にすると未検証の母集団が約30%混入し、掃引窓ですら 82.8→81.7% に薄まる。
#     **必ず完全一致で判定すること**
#   - **空白3全件**（48.5件/日）: 確認窓 74.3% [71.6, 76.7] で壁を越えるとは言えない
#
# memory: keirin_7car_coverage_gaps_2026_08_05
# ═══════════════════════════════════════════════════════════════════════════

# 対象レース種別（**完全一致**。部分一致にしてはいけない・上記コメント参照）。
RANK_7B_RACE_TYPES = ("準決勝",)


# 7B の停止スイッチ。2026-08-07 に一度 True（廃止）にしたが、同日中に
# **「7C の下に置き、重複は 7C・独自レースだけ 7B」**へユーザー判断が変わったため
# False（稼働）へ戻した。優先順位は `netkeirin_submit_wt.RANK_CONFIGS` の定義順が正本。
RANK_7B_STOPPED = False


def rank_7b_daily_select(candidates: list[dict]) -> list[dict]:
    """7Bの選出: ◎◯完全一致 ∧ 順序も一致（市場と完全合意）∧ 準決勝。

    candidates: rank_7s_* と同じ生候補 dict のリスト。最低限
      {"wt_overlap_n": int|None, "order_disagree": bool|None, "race_type": str|None}
      を持つこと。

    - `wt_overlap_n == 2` 必須（7SS/7S/7A＝overlap∈{0,1} とは論理的に排他＝純増）
    - `order_disagree is False` 必須（モデル1位 == WT◎ ＝市場と完全合意）。
      **`is not True` ではなく `is False` で書く**: overlap==2 は ◎◯ が両方存在しないと
      成立しないため `order_disagree is None`（◎欠損）とは構造的に両立しない
      （掃引窓 18,440 件すべてが False であることを実測確認済み）。将来 overlap の
      定義が変わって None が混じったときに黙って通さないためのフェイルセーフでもある。
    - `race_type` が RANK_7B_RACE_TYPES に**完全一致**すること

    returns 採用された候補のリスト（entropy昇順・表示用の並び順のみ）。

    🔴 **2026-08-07: 7C より下の優先順位で運用する（ユーザー判断）。**
       7C との比較で、両方に傾斜配分をかけた公平な条件では 7C が実質的中率で
       上回った（同一母集団 2,203R: 7B 31.6% / 7C 39.0%）。一方で 7B は 7C が
       拾わないレースを **3.14件/日** 持ち、ROI も 1.2pt 高い。
       → **重複するレースは 7C に譲り、7B 独自のレースだけを 7B として出す。**
       実現は `netkeirin_submit_wt.RANK_CONFIGS` の定義順（＝入稿の優先順位）で
       **7C より後ろに置く**ことによる。netkeirin は1レース1商品なので、
       先に来たランクがそのレースを取り、後続は自動的に降りる。

       ⚠️ **候補生成の側では重複を排除しない**（7C が他ランクと重ならないのと同じ）。
          picks_history には両方の行が残り、成績はランクごとに独立して集計される。
          入稿されるのは優先順位で勝った側だけ。
    """
    return [] if RANK_7B_STOPPED else rank_7b_select_pool(candidates)


def rank_7b_select_pool(candidates: list[dict]) -> list[dict]:
    """7B の選出ゲート本体（廃止中も**検査は生かしておく**）。

    `rank_7b_daily_select` から切り出したのは、廃止で到達不能になったコードを
    そのまま置くとテストが当てられず、再開したときに壊れているのに気づけないため。
    """
    pool = [
        c for c in candidates
        if c.get("wt_overlap_n") == 2
        and c.get("order_disagree") is False
        and c.get("race_type") in RANK_7B_RACE_TYPES
    ]
    return sorted(pool, key=lambda c: c.get("entropy", float("inf")))


# ═══════════════════════════════════════════════════════════════════════════
# A（◎一致×波乱×別ライン先頭・二連単）戦略 — 2026-07-17 全廃
#
# 正規プロトコル（学習〜2025-03-31・検証2025-04-01〜2026-03-31の1年）の再検証で
# 検証最良 88.5-94.2%・100%超なし→棄却（exp_ranks_valtest.py / exp_axis_redesign.py）。
# → 2026-07-17 に候補生成・judge・採点を全停止し、picks_history の #7A 行は
# picks_history_a_archive へ退避。定数は過去スクリプト（backfill_a_rank_wt.py 等）の
# 互換のため残置。
# ═══════════════════════════════════════════════════════════════════════════

A_EX_MIN_ODDS = 5.0        # 買い目の二連単オッズ下限（未満はカット）
A_EX_MAX_ODDS = 50.0       # 買い目の二連単オッズ上限（以上はカット）
A_STAKE = 100              # 円/点（ペーパー）


def is_senbatsu(race_type: str | None) -> bool:
    """「選抜」系レース種別か（選抜/チャレンジ選抜/ガールズ選抜等）。"""
    return bool(race_type) and "選抜" in str(race_type)


def line_score_features(
    line_points: list[tuple[int | None, float | None]],
) -> tuple[float | None, int | None, bool | None]:
    """出走全車の (line_group, race_point) からライン構造特徴を返す。

    returns (avg_gap, n_lines, all_solo)
      - avg_gap: ライン別 race_point 平均の 1位 − 2位（ライン2本未満は None）
      - n_lines: ライン本数（line_group の distinct 数）
      - all_solo: 全員単騎（=ライン本数が車数と一致）か
    line_group 欠損車が1台でもあれば (None, None, None)（判定はフォールバック側）。
    """
    if not line_points:
        return None, None, None
    groups: dict[int, list[float]] = {}
    for lg, rp in line_points:
        if lg is None or rp is None:
            return None, None, None
        groups.setdefault(int(lg), []).append(float(rp))
    n_lines = len(groups)
    all_solo = n_lines == len(line_points)
    if n_lines < 2:
        return None, n_lines, all_solo
    means = sorted((sum(v) / len(v) for v in groups.values()), reverse=True)
    return round(means[0] - means[1], 3), n_lines, all_solo


def ss_policy(
    race_type: str | None,
    avg_gap: float | None = None,
    n_lines: int | None = None,
    all_solo: bool | None = None,
) -> tuple[str | None, int]:
    """SS(7PLUS_R) の購入ポリシー判定（2026-07-16〜: 選抜カットのみ）。

    ※ 旧S1（7PLUS_R）は 2026-07-16 に全廃。本関数は過去日再採点・
      フォールバック経路の互換のため残置。

    returns (skip_reason, stake_per_pt)
      - skip_reason: "選抜" / None（None=購入可）
      - stake_per_pt: SS_STAKE（増額は廃止・常に100円/点）
    ライン特徴引数（avg_gap/n_lines/all_solo）は 4分戦カット・格差増額の削除に伴い
    未使用（呼び出し側互換のため残置）。
    """
    if is_senbatsu(race_type):
        return "選抜", 0
    return None, SS_STAKE


# ═══════════════════════════════════════════════════════════════════════════
# 7SS（entropy不合格 × 軸2車が同一ライン・2026-08-05 新設）
#
# ⚠️ **この 7SS は 2026-08-02 に全廃した旧 RANK_7SS（波乱軸選出・穴レース検知・
#    モデル非依存の別戦略）とは無関係の別物**。名前だけを引き継いだ。
#    旧実装は「順位が名前で伝わること」を優先するユーザー判断で破棄した
#    （commit `7048db5` 以前の git 履歴から復元可能）。picks_history に旧7SSの
#    行は0件（16,298行は2026-08-02に削除・CSVへ退避済み）なので成績は混ざらない。
#
# ## 定義
#
#     wt_overlap_n ∈ {0,1}
#     ∧ axis_sum <= RANK_7S_AXIS_SUM_MAX      （7S と同じ）
#     ∧ entropy  >  RANK_7S_ENTROPY_MAX       （＝レースが荒れている側）
#     ∧ **軸1と軸2が同一ライン**（wt_entries.line_group が一致）
#
# 買い目は 7S/7A と同一（三連複 軸2車＋残り5車流し・5点500円）。
#
# ## 経緯：7A が性質の違う2群の混合だった
#
# 2026-08-05 の分解で、7A（不合格ちょうど1つ）は正反対の2群の混合と判明した:
#   A群 axis_sum だけ不合格（＝軸2車が堅い）  的中52-53% / 低配当(中央値0.78倍)
#   E群 entropy  だけ不合格（＝レースが荒れ）  的中30-32% / 高配当(中央値1.57倍)
# 同じラベルで出しているため利用者から見て当たり方も配当も一貫しなかった。
#
# ## 同一ライン条件の根拠
#
# 7S/7A では**二軸に負の相関**（実測 −2.7〜−2.9pt。独立仮定より両方3着内率が低い）
# がある。7車で3枠を奪い合うためだが、**その正体の一部がライン関係**だった。
# 別ラインの2車は競合するが、同一ラインなら連動して残る（競輪はライン戦）。
#
# 確認窓（2024-07〜2025-06・掃引に一度も使っていない4窓）:
#
#   E群 基準       7.34件/日  的中30.2%  ROI 76.8%  (82.3 76.3 67.4 81.4)
#   E群 同一ライン  1.90件/日  的中41.2%  ROI 85.9%  (94.1 86.5 88.7 74.3)
#   E群 別ライン    5.44件/日  的中26.7%  ROI 75.0%  (79.6 73.6 61.7 85.1) ← 除外する層
#
# **的中率 +11.0pt・ROI +9.1pt**。除外される別ライン側は7Aの中で最も弱い。
#
# ⚠️ **c4窓が 74.3% で「4窓すべて75%以上」を 0.7pt 割る**（ユーザー承知の上で採用）。
#    構成全体（7SS+7S+7A）では 79.2/84.2/83.8/80.8 と4窓すべて合格する。
#
# ⚠️ **A群には適用しない**。確認窓で同一ライン80.4% vs 別ライン78.7%、基準80.8%を
#    下回り適用根拠がない（掃引窓では+10ptに見えたが確認窓で消えた）。
#
# ## 構成全体（確認窓・件数は目標10〜15件/日に対して 11.87）
#
#   7SS  1.90件/日  的中41.2%  ROI 85.9%   ← 最上位
#   7S   3.68件/日  的中41.0%  ROI 84.4%
#   7A   6.28件/日  的中53.2%  ROI 80.8%
#   合計 11.87件/日 的中47.5%  ROI 82.0%  (79.2 84.2 83.8 80.8) ✓
#
# ROI が 7SS > 7S > 7A と単調になり「S が特別に良く A から下がる」並びが成立する。
# ═══════════════════════════════════════════════════════════════════════════

RANK_7SS_STAKE = unit_stake(5)   # 2,000円/点（5点=10,000円/レース。7S/7Aと同一）


def rank_7ss_same_line(axis1: int, axis2: int,
                       line_groups: dict[int, object] | None) -> bool:
    """軸1と軸2が同一ラインかを判定する。

    line_groups: {frame_no: wt_entries.line_group}。単騎や未取得は None/空文字。
    **どちらかが不明なら False**（不明を同一ラインとみなして推奨を増やさない）。
    """
    if not line_groups:
        return False
    g1, g2 = line_groups.get(axis1), line_groups.get(axis2)
    if g1 is None or g2 is None:
        return False
    s1, s2 = str(g1).strip(), str(g2).strip()
    return bool(s1) and s1 == s2



# ═══════════════════════════════════════════════════════════════════════════
# RANK_7H1 — 穴推奨「本命バスト型」（2026-08-06 新設・7車立て専用）
#
# 【命名体系】穴推奨モデルは `{車数}H{連番}` を表示ラベルとし、内部rank は
#   "RANK_" + ラベル、suffix は "#" + ラベル とする（既存6ランクと同一規則）。
#   H = Hole（穴）。既存の S/A/B（的中率重視・予想ベース系）とは系統を分ける。
#     7H1 = 本命バスト型（本モジュール）
#     7H2 = 三着穴型（1・2着は堅く3着だけ荒れる。未実装・予約）
#
# 【選別】3条件すべてを満たすレースだけを対象にする。
#   (1) 7車ちょうど
#   (2) 軸1（モデル1着率 pred_win 最上位）== WINTICKET公式印 ◎    …「市場と合意した本命」
#   (3) 抜け度（モデル1着率の1位−2位差） >= RANK_7H1_GAP_MIN      …「確実に抜けている」
#   (4) バスト確率（本命が4着以下になる確率）が当日の上位 RANK_7H1_TOP_FRAC
#
#   実測（honest walk-forward 38,085R・memory keirin_highpay_payout_ceiling_2026_08_06）:
#     母集団(2)      38,085R / バスト基準率 19.50% / AUC 0.6848
#     +(3) >=20pt    21,669R / バスト率 13.69%
#     +(4) 上位10%    2,167R / **3.22件/日・実バスト率 28.66%（lift 2.09）**
#     月次一貫性: 23/23ヶ月で基準超え（平均 +12.14pt・最悪 +5.14pt）
#
# 【買い目】本命が4着以下という前提なので3着以内は必ず残り6車で埋まる。
#   さらに **本命が飛ぶときは番手も一緒に飛ぶ**（本命ライン番手の bust時 1着率7.79%・
#   3着内率33.27% で全役割中最低）ため、**本命ラインを丸ごと落とす**。
#
#     プール = 別ライン勢 + 単騎（本命ラインを除いた車）をモデル3着内率順に r1..
#     三連単 = 1着: 別ライン先頭(最強ライン)を固定
#              2着: プールの r1・r2
#              3着: 本命を除く全5車（総流し）          → 8点
#     三連複 = プール上位5車BOX（最大10点）
#
#   実測（選別2,086R・100円単位の実購入）:
#     的中 18.70%（三複17.11 / 三単5.90）/ ROI 99.1% / 平均払戻 49,778円 /
#     30万円+ 16件（月0.8回）/ 平均購入額 9,388円
#     窓別 ROI: 掃引窓 94.9%(n=1,344) / 確認窓 113.2%(n=681)
#     ⚠️ 三連単側は裾依存（上位3本が回収の15.9%）。**ROIは80〜110%のレンジで読む**。
#   ⚠️ 上記は導入時の探索パイプラインの数字。**本番 picks_history の実測は
#     これより明確に低い**（2026-08-08 時点・2024-04-01〜2026-08-07）:
#       n=2,425 / 的中 18.47% / **ROI 81.1%** / 30万+ **13件(0.54%)**
#     母集団が 2,086R→2,425R へ伸びた分と直近の下振れで説明がつくが、
#     **対外的に示す数字は picks_history 側を使うこと**。
#
# 【9車は不採用】9車ではバスト予測 AUC 0.5967（7車0.6848・n=3,018で信頼できる）、
#   ROI 36〜61% で壁を大きく割る。**抜け度条件は9車では逆効果**で7車と正反対だった。
#   「7車の知見が9車へ移らない」事例（3ヘッド軸・9B・S9/9A再較正と同型）。
#
# 【検証済みの否定結果（再提案しない）】
#   - 残り6車の力関係によるセグメント別の買い目出し分け（拮抗度/強い単騎/
#     別ライン先頭の有無/本命ライン残存数の4次元）。標本3倍・自由度削減でも
#     確認窓で「常に三連単」を超えない
#   - 選別を緩めて標本を増やす（上位10%→30%で三連単ROIが 95→79% へ両窓一致で劣化）
#   - 本命を買い目から完全に外す版（確認窓で反転。本命は飛ぶときも3着には残る）
#   - 番手のみ除外（3番手以降も弱いので本命ラインは丸ごと落とすのが正しい）
# ═══════════════════════════════════════════════════════════════════════════

RANK_7H1_NE = 7                    # 対象車数（7車ちょうど）
RANK_7H1_GAP_MIN = 0.20            # 抜け度（モデル1着率の1位−2位差）の下限
# バスト確率の採用閾値。**日ごとの相対順位ではなく全体の絶対閾値**を使う。
# 検証（honest walk-forward）が「抜け度>=20pt 母集団 21,673件の上位10%」＝
# 90%点 0.2666 で切っており、日次の相対順位で切り直すと切り捨てにより
# 系統的に少なくなる（実測 3.22件/日 → 1.6件/日）ため。
# 絶対閾値なら開催規模がそのまま件数に反映される
# （実測の日次件数: 中央3件・p25 2件・p75 4件・最大11件・0件の日が7%）。
# ⚠️ この値はモデルの較正に依存する。モデルを再学習したら
#    `scripts/check_7h1_threshold.py` 相当で分布を確認し、必要なら更新すること。
RANK_7H1_BUST_PROB_MIN = 0.2666
# ⚠️ **2券種時代（〜2026-08-15）の枠方式の定数**。三連単一本化で本番からは
#    参照されなくなった。`scripts/exp_7h1_stake_design.py`（当時の配分設計の
#    実験）との互換のためだけに残してある。新しいコードから読まないこと。
RANK_7H1_BUDGET_TF = 7500          # 【旧】三連単の予算枠（円/レース）
RANK_7H1_BUDGET_TRIO = 2500        # 【旧】三連複の予算枠（円/レース）
# ⚠️ 同じ値のリテラル再定義にしない（RANK_7C_BUDGET と同じ理由・2026-08-08）。
RANK_7H1_BUDGET_CAP = RACE_BUDGET  # 1レースの購入上限（円）
RANK_7H1_UNIT = STAKE_UNIT         # 最低賭け金単位（円）
RANK_7H1_TF_SECOND_N = 2           # 三連単の2着に使うプール上位の車数


def rank_7h1_pool(others: list[int], roles: dict[int, str]) -> list[int]:
    """本命ラインを落とした購入プール（別ライン勢＋単騎）を返す。

    others はモデル3着内率の降順で渡すこと（順序をそのまま引き継ぐ）。
    """
    from .preprocessing.favbust_features import FAV_LINE_ROLES
    return [f for f in others if roles.get(f) not in FAV_LINE_ROLES]


def rank_7h1_build_legs(others: list[int], roles: dict[int, str]) -> list[str]:
    """三連単の目（1着1車 × 2着2車 × 3着5車 ＝ 8点）を返す。組めなければ空。

    🔴 **2026-08-15 に三連単一本化**（ユーザー指示「三連複BOX分を全て三連単の
       買い目に振り直す」）。それ以前は `(三連複BOX, 三連単F)` の 2券種を返し、
       予算1万円を 三連単8点×900円 + 三連複2,800円 に割っていた。

       単価を上げても **ROI は動かない**（実測 500〜1,100円 で 80.7〜82.1% と平坦）。
       動くのは「ガミ率」と「高額払戻の頻度」だけで、この2つは真っ向から
       トレードオフになる。7H1 は**高配当狙いのランク**として作られており
       （的中率側は 7S/7C が担当）、的中を拾うための三連複は存在理由と逆を向く。
       詳細な実測表は `rank_7h1_stakes` の docstring に残してある。

    Args:
        others: 本命を除く6車を**モデル3着内率の降順**で並べたもの
        roles:  `favbust_features.roles_of()` の戻り値
    """
    from .preprocessing.favbust_features import ROLE_LEAD_TOP

    pool = rank_7h1_pool(others, roles)
    if len(pool) < 3:
        return []
    lead = next((f for f in others if roles.get(f) == ROLE_LEAD_TOP), None)
    if lead is None:
        # 別ラインの先頭が存在しない（全員単騎など）レースは対象外にする。
        # 検証では成立率96.3%で、残り3.7%は買い目が定義できない。
        return []
    rest = [f for f in pool if f != lead]
    return [f"{lead}-{a}-{c}" for a in rest[:RANK_7H1_TF_SECOND_N]
            for c in others if c not in (lead, a)]


def rank_7h1_unit(budget: int, n_legs: int) -> int:
    """枠内の100円単位・均等配分の1点あたり金額。100円未満なら0（買わない）。"""
    if n_legs <= 0:
        return 0
    u = (budget // n_legs) // RANK_7H1_UNIT * RANK_7H1_UNIT
    return u if u >= RANK_7H1_UNIT else 0


def rank_7h1_stakes(n_legs: int) -> tuple[int, int]:
    """(1点あたり賭け金, 合計購入額) を返す。全ランク共通の予算枠方式に従う。

    通常形は8点なので **1,200円/点 × 8 = 9,600円**。欠車で点数が減ったら
    その点数で引き直す（1レース1万円の枠は動かさない）。9H1・7T1 と同じ規則
    （`unit_stake`）で、切り捨てぶんは使い切らない。

    ## 三連単一本化（2026-08-15）

    それ以前は **三連単8点×900円 + 三連複BOXへ2,800円** の2券種で、記録側
    （この関数 → picks_history）と入稿側（`netkeirin_submit_wt`）が別々に
    金額を持っていた。ユーザー指示で三連複ぶんを三連単へ振り直した。

    単価を動かしても **ROI は動かない**。picks_history 2,425行で枠配分だけを
    振り替えた実測:

      三連単単価 | 三連単枠/三連複枠 |  ROI  | 実質的中(ガミ除く) |   30万+   | 最大払戻
      ----------|-----------------|-------|-----------------|-----------|---------
         500円   |  4,000 / 6,000  | 82.1% |      15.71%      | 4件(0.16%) |  81万
         700円   |  5,600 / 4,400  | 81.6% |      13.94%      | 6件(0.25%) |  99万
         900円   |  7,200 / 2,800  | 81.2% |      11.46%      |13件(0.54%) | 116万
       1,100円   |  8,800 / 1,200  | 80.7% |       6.85%      |18件(0.74%) | 134万

    ＝ 単価で動くのは **「ガミ率」と「高額払戻の頻度」だけ**で、両者は真っ向から
    トレードオフ。7H1 は高配当狙いのランク（的中率側は 7S/7C が担当）なので、
    的中を拾うための三連複は存在理由と逆を向いていた。

    ⚠️ 賭け金の規則を変えたら `scripts/rebuild_7h1_walkforward_pg.py` で過去分を
       再構築すること。Web に出る実績と実際に売る商品の性格が食い違う
       （2026-08-07〜08-08 に記録側900円・入稿側500円の二重管理で実際に起きた）。
    """
    u = unit_stake(n_legs)
    return u, u * max(n_legs, 0)


def rank_7h1_daily_select(candidates: list[dict]) -> list[dict]:
    """当日の候補から 7H1 を選出する。

    candidates の各要素に必要なキー:
      `n_entries`(=7) / `gap12`（抜け度） / `bust_prob`（バスト確率） /
      `legs_tf`（買い目。空なら除外）

    **選別は `RANK_7H1_BUST_PROB_MIN` の絶対閾値で行う**（日ごとの相対順位ではない）。
    理由は同定数のコメント参照。0件の日があるのは正常（実測で7%の日が0件）。

    ⚠️ 2026-08-15 の三連単一本化で `legs_trio` の条件を落としたが、**母集団は
       変わらない**。三連複は「プール>=3車」で組め、三連単はそれに加えて
       「別ラインの先頭が居る」ことを要求する＝三連単が組めるレースでは
       三連複も必ず組めたため、両方を要求していた旧条件と同値になる。
    """
    elig = [c for c in candidates
            if c.get("n_entries") == RANK_7H1_NE
            and c.get("gap12") is not None
            and float(c["gap12"]) >= RANK_7H1_GAP_MIN
            and c.get("bust_prob") is not None
            and float(c["bust_prob"]) >= RANK_7H1_BUST_PROB_MIN
            and c.get("legs_tf")]
    elig.sort(key=lambda c: -float(c["bust_prob"]))
    return elig


# ═══════════════════════════════════════════════════════════════════════════
# RANK_7H2 — 穴推奨「印なし2軸・高配当」（2026-08-10 新設・7車立て専用）
#
# 【7H1 との違い】7H1 は「モデルもWT◎も推す本命が飛ぶ」と読んだレースを選び、
#   その本命を買い目から落とす。7H2 は**本命の生死を予測しない**。
#   代わりに「**軸2車をWT公式印の付いていない車に限定する**」ことで、
#   軸2車というブランドを保ったまま配当帯そのものを移す。
#   母集団も選別条件も買い目も別物で、重なるのは 7H1 の 49.2% にとどまる。
#
# 【なぜ印なしか】`wt_entries.prediction_mark` は**オッズ無しで朝から確定する
#   人気の代理**（◎1/◯2/△3/×4 が各1車、残りが 0＝印なし）。
#   「モデルは評価しているが公式印が付いていない車」＝有力だが人気薄。
#   🔴 **モデル上位2車の2軸流し（＝既存ランクの形）では >=300倍 が
#      全十分位で 0.00回/100R**。高配当はまさに軸2車が飛んだときに出るので、
#      確信の上位2車では原理的に届かない。ここが本ランクの存在理由。
#
# 【選別】2条件のみ。**どちらもオッズを使わない**ので朝の入稿に間に合う。
#   (1) 7車ちょうど
#   (2) モデル3着内率の正規化エントロピー >= RANK_7H2_ENTROPY_MIN（＝荒れる読み）
#
# 【買い目】1レース RACE_BUDGET 円。
#   軸1（1着固定）= 印なし × モデル**1着率**最大   … 1着の順序を決めるのは単勝率
#   軸2           = 印なし × モデル**3着内率**最大 … m2/m3 との差は全閾値で ns
#   相手          = 残り5車（**総流し**。WT◎もここに入る）
#
#   三連複BOX（10点 × 予算/10 = 1点1,000円）
#       プール = 軸1・軸2 + 相手のうち**WT◎を除く**上位3車 の5車
#
#   🔴 **2026-08-18 に三連単を破棄した**（下記 RANK_7H2_TRIFECTA_ENABLED）。
#      以下の「倍購入」に関する記述は破棄前の設計根拠であり、**現行の買い方では
#      ない**。再開するなら予算配分から作り直すこと。
#   （破棄前）三連単フォーメーション（倍購入・10点 × RANK_7H2_TF_UNIT 円）
#       軸1 → 軸2 → 相手5車   （軸2を2着に置く5点）
#       軸1 → 相手5車 → 軸2   （軸2を3着に置く5点）
#
#   ⚠️ **三連単は倍購入・三連複は◎を外す**、が設計の要（2026-08-10 ユーザー指定・実測で裏づけ済み）:
#     - 倍購入(P1+P2) の **ROI は P1 単独・P2 単独と構造的に同じ**（72.3/72.0/72.2%）。
#       効くのは >=300倍 の頻度が 0.33/0.38 → **0.71回** と倍になること、
#       および片アーム依存の分散が消えること（前向き窓で P1 96.4% / P2 50.2% と割れた）。
#     - 三連複に◎を入れると生の的中は 20.75→26.84% と上がるが、増える分はほぼガミで
#       **実質的中は 9.25→9.00% と下がる**。netkeirin はガミを不的中として数えるので外す。
#     - 三連複を軸2頭ながし4点にすると 的中 6.19% / ROI 68.86% で BOX に劣る。
#
# 【実測】設計期間 2025-07-01〜2026-05-07（n=3,957・7車の上位20%・12.72件/日）
#   と、**設計時に存在しなかった前向き窓** 2026-05-08〜08-04（n=1,229）で一度きり評価:
#
#   | 窓 | 的中 | 実質的中 | ROI | >=300倍/100R | 30万円+ |
#   |---|---|---|---|---|---|
#   | 設計期間 | 20.75% | 4.07% | 72.16% | 0.71回 | 27件 |
#   | 前向き窓 | 22.62% | 3.42% | 74.03% | 0.65回 |  8件 |
#
#   前半/後半に割った確認窓でも H2−H0（印なし限定の効果）は
#   150倍+ / 300倍+ の両方で有意（前半 +0.86/+0.66・後半 +0.96/+0.56）。
#
# 【✂️ 検証して落としたもの — 再提案しない】
#   - **6車・9車への展開**: 6車は高エントロピー帯で的中0件。9車は paired bootstrap で
#     T>=100 が **−0.71回 [−1.34,−0.08] と有意にマイナス**（独立CIの比較では
#     成立に見えたが撤回した）。**高配当商品は7車専用**。
#   - **9車でのエントロピー絞り込み**: 7車と逆に働く（>=300倍 0.28→0.00回）。
#     504通りあって元々分散が大きく、追加の絞り込みは母数を枯らすだけ。
#   - **軸2を m2(2着率)/m3(3着率) にする**: 全閾値で ns。既存モデルだけで済む
#     3着内率(pp3)のままでよい（**連帯ヘッドは不要**）。
#   - **三連複プールの並びに m3 を使う**: pp3 並びと ROI 72.16 vs 72.14%・
#     30万+ 27件で同値。連帯ヘッドという新しいモデル依存を増やす価値がない。
#
# 【⚠️ ROI は評価軸にしない】的中が稀なため ROI の CI が壊滅的に広い
#   （77.88% [46.3, 116.5]）。**評価軸は >=300倍 の頻度**（CI が 0 を除外できる）。
#   `P(配当>=T) <= ROI/T` より頻度には算術的上限があり、レース選別では超えられない
#   （memory `keirin_highpay_payout_ceiling_2026_08_06`）。
# ═══════════════════════════════════════════════════════════════════════════

RANK_7H2_NE = 7                    # 対象車数（7車ちょうど）
# モデル3着内率の正規化エントロピーの下限。
# **日ごとの相対順位ではなく全体の絶対閾値**を使う（7H1 と同じ理由。
# 日次の相対順位で切り直すと切り捨てにより系統的に少なくなる）。
#
# 🔴 **この値はモデルの較正に依存する。** 検証（walk-forward の4ヘッド予測）で
#    設計期間 2025-07-01〜2026-05-07 の7車 19,782件の80%点は **1.8485** だったが、
#    **本番の経路（月次vintage `lgbm_wt_eval_mYYMM`）で測り直すと 1.8534**
#    （2026-05〜07・n=5,911）で、1.8485 のままだと該当率が 20.0%→22.3% になる。
#    **検証パイプラインの閾値をそのまま定数にすると壊れる**という既知の型
#    （memory `keirin_step3_dutch_7a_gate_impl_2026_08_09`）。本番経路の値を採る。
#
# ⚠️ 月ごとの振れは大きい（p80: 2026-05 1.8463 / 06 1.8420 / **07 1.8642**）。
#    7月のような分布が高い月は該当率が 29% まで上がる。**これは異常ではない**
#    ので、単月の件数だけを見て閾値をいじらないこと。
# ⚠️ モデルを再学習したら `scripts/check_7h2_threshold.py` で分布を確認し、
#    ずれていれば更新すること。
RANK_7H2_ENTROPY_MIN = 1.8534
RANK_7H2_LEGS_N = 5                # 相手（残り5車＝総流し）
# ◎（WT本命）の3着内率シェア＝ pred_top3(◎) / Σ pred_top3(全7車) の上限。
# **この値より大きいレースは対象外**にする（2026-08-10 追加）。
#
# 【why】7H2 が買う軸2車は印なし＝人気薄なので、**◎が本当に厚いレースでは
# 印なし勢が3着以内に入る余地がない**。実測でも◎シェアの5分位で的中率が
# 掃引窓 31.3→18.4% / 確認窓 32.9→14.6% / 前向き窓 35.3→15.8% と
# **3窓すべてで最上位帯が明確に悪い**。
#
# 【なぜ◎単独か】印の合算（◎○ / ◎○▲ / ◎○▲△）も測ったが、**足すほど効果が薄れる**:
#   最上位帯−最下位帯の的中率差（掃引/確認/前向き）
#     ◎のみ      12.9 / 18.3 / 19.5 pt   ← 最も鋭い
#     ◎○        12.2 / 13.4 / 15.6 pt
#     ◎○▲       8.6 /  4.5 / 12.9 pt
#     ◎○▲△      5.8 /  5.6 /  4.9 pt   ← ほぼ無意味
#   ▲△は「印は付いたが中位」の車で、7H2 の脅威にならないため分母を薄めるだけ。
#
# 【上位20%を切ったときの実測】設計期間 3,957→3,165R / 前向き窓 1,229→997R
#   的中率  24.16→26.10%（設計） / 27.10→29.69%（前向き）
#   ROI     72.10→80.10%（設計） / 77.43→77.93%（前向き）
#   100倍+   69→64件（設計・母数の減り20%より緩やか） / 21→15件（前向き）
# ⚠️ **30%以上は切らない**。前向き窓で ROI 77.9→75.3%・100倍+ 15→12件と
#    目減りが加速する。40%/50% で ROI が戻るのは標本が薄くなった揺れ。
#
# ⚠️ 切る帯は「当たらないが**当たれば高い**」帯でもある（捨てる帯の三連単的中の
#    配当中央値 107〜233倍）。的中率と高配当のトレードオフを 20% だけ買っている。
#
# 🔴 **本番経路（月次vintage）で較正した値**。検証パイプラインの 0.2452 を
#    そのまま使うと除外率が 17.3% にしかならない（RANK_7H2_ENTROPY_MIN と同じ罠）。
#    月ごとの p80 は 0.2423〜0.2442 と安定している。
#    再学習したら `scripts/check_7h2_threshold.py` で確認すること。
RANK_7H2_HONMEI_SHARE_MAX = 0.2430
RANK_7H2_TRIO_POOL_MAX = 5         # 三連複BOXに使うプール上限車数（→最大10点）
# 三連単の1点あたり（円）。**この値が 7H2 の賭け金の単一正本**で、記録側と
# 入稿側の両方がここから導出される（7H1 で二重管理の食い違いを起こした教訓）。
# 三連複の単価は残予算の均等割りなので、この値を変えると**両方**動く
# （10点ずつなので 700円 → 三連複 300円）。
#
# 【700円を選んだ根拠】単価で動くのは「実質的中率」と「高額払戻の大きさ」だけで、
# **ROI は完全に不動**（設計期間 3,957R で単価を振っても 72.10〜72.17%）:
#
#   三連単単価 | 三連単枠/三連複枠 |  ROI  | 実質的中 |  30万円+ | 三複のみ的中のガミ率
#   ----------|-----------------|-------|---------|---------|------------------
#      900円   |  9,000 / 1,000  | 72.14% |  3.66%  | 27件    | **96.9%**
#    **700円** |  7,000 / 3,000  | 72.10% |  9.43%  | 22件    | 69.7%
#      500円   |  5,000 / 5,000  | 72.17% | 13.44%  | 13件    | 約49%
#
# 🔴 **三連複のみの的中がガミになるか**は三連複の単価だけで決まる。
#    1レース10,000円なので、単独的中で投資を上回るには
#    「三連複オッズ >= 10,000 / 三連複単価」が要る:
#      100円 → **100倍以上**が必要 → 837件中811件(96.9%)がガミ
#      300円 →   33.3倍以上        → 583件(69.7%)がガミ
#    三連複のみ的中の配当は**中央20.7倍・平均30.5倍**なので、100円では
#    「当たっても netkeirin の表示上は不的中」がほぼ全件になる（2026-08-10 ユーザー指摘）。
#    ガミを完全に消すには 500円（=20倍で足りる）が要るが、そのとき三連単も
#    500円になり **30万円+ が 27→13件へ半減**する。700/300 はその折衷点。
#
# 的中体験をさらに優先したくなったら下げてよいが、**そのとき高額払戻は比例して縮む**。
# 🔴 **2026-08-18: 三連単を破棄し三連複のみの構成にした**（ユーザー判断）。
#
#   実績44件（2026-08-10〜14・enabled=false のペーパー）を点検して分かったこと:
#
#     構成      1レース10,000円 = 三連複5車BOX 10点(1点300円) + 三連単F 10点(1点700円)
#     三連複側  13的中(29.5%)だが**3,000円しか乗っていない**ので、
#               33.3倍以上でないと投資10,000円を回収できない。実際の配当は
#               4.9〜60.8倍（中央20倍）で、33倍を超えたのは3〜4件だけ
#     三連単側  **44件で1本も当たらず**、毎回7,000円が消えた
#     結果      ROI 20.9% / 表示的中 4.5%（44件中2件のみ払戻>投資）
#
#   ＝ **当たっても投資が返らない配分**になっていた。7H1 は同じ2券種構造を
#   2026-08-15 に三連単一本化して解消済みで、7H2 だけが取り残されていた。
#
#   三連複一本化の試算（同44件・10点×1,000円・損益分岐10倍）:
#     13的中中12件が10倍超 → ROI 69.5% / 表示的中 27.3%（20.9% / 4.5% から改善）
#
#   ✅ **2026-08-18: 再構築スクリプトを新設して確かめた**
#      （`scripts/backfill_7h2_rank_wt.py` / `rebuild_7h2_walkforward_pg.py`・
#        月次凍結 vintage の walk-forward）。試算 69.5% に対し実測はやや上:
#
#        2026-07 単月 451R … 的中 27.1% / 表示的中 21.7% / ROI 78.0%
#        2024-01 単月 434R … 的中 32.7% / 表示的中 19.4% / ROI 69.0%
#
#      旧構成（ROI 20.9% / 表示的中 4.5%）からの改善は本物。ただし
#      🔴 **ROI は控除率の壁（75%）の前後を行き来しており、この層に
#         エッジがあるという主張はできない**。7H2 の評価軸は依然として
#         「>=300倍 の頻度」であって ROI ではない（下記）。
#      ⚠️ 旧44行（2026-08-10〜14）は**買い方が違う別物**。再構築が上書きする。
#   ⚠️ 三連単側のロジックは残してある（再開は `RANK_7H2_TRIFECTA_ENABLED=True`）。
#      ただし**予算配分を直さずに戻すと同じ壊れ方をする**。
RANK_7H2_TRIFECTA_ENABLED = False

RANK_7H2_TF_UNIT = 700
# ⚠️ 同じ値のリテラル再定義にしない（RANK_7C_BUDGET・RANK_7H1 と同じ理由）。
RANK_7H2_BUDGET_CAP = RACE_BUDGET  # 1レースの購入上限（円）
RANK_7H2_UNIT = STAKE_UNIT         # 最低賭け金単位（円）
#: WT公式印「◎」の prediction_mark 値。
#: 🔴 **印が付かない車は 0 であって NaN ではない。**`isnan()` で判定すると
#:    印なし集合が常に空になり、規則が「制約なし」へ**黙って退化する**
#:    （2026-08-10 の検証で実際に踏み、H0/H1/H2 が全セル完全一致して気付いた）。
WT_MARK_HONMEI = 1
WT_MARK_NONE = 0


def rank_7h2_entropy(top3_probs: dict[int, float]) -> float:
    """モデル3着内率をレース内で正規化したエントロピー。

    値が大きいほど「どの車が3着以内に来るか読めない」＝荒れる読み。
    `exp_highpay_*` の検証と同じ式（正規化してからシャノンエントロピー）。
    """
    vals = [max(float(v), 0.0) for v in top3_probs.values()]
    total = sum(vals)
    if total <= 0:
        return 0.0
    return -sum((v / total) * math.log(max(v / total, 1e-9)) for v in vals)


def rank_7h2_honmei_share(top3_probs: dict[int, float],
                          marks: dict[int, float | int | None]) -> float | None:
    """◎（WT本命）の3着内率が、レース全体の3着内率に占める割合。

    ◎が居ない／確率が取れない場合は None（＝選別で落とす）。
    """
    hon = next((f for f, v in marks.items()
                if v is not None and int(v) == WT_MARK_HONMEI), None)
    total = sum(float(v) for v in top3_probs.values())
    if hon is None or hon not in top3_probs or total <= 0:
        return None
    return float(top3_probs[hon]) / total


def rank_7h2_unmarked(marks: dict[int, float | int | None]) -> list[int]:
    """WT公式印の付いていない車（prediction_mark == 0）。

    2車未満しか取れないレースは**全車を候補にフォールバック**する
    （検証と同じ挙動。印の欠測で買い目が組めなくなるのを防ぐ）。
    """
    um = [f for f, v in marks.items()
          if v is not None and int(v) == WT_MARK_NONE]
    return sorted(um) if len(um) >= 2 else sorted(marks)


def rank_7h2_axes(win_probs: dict[int, float], top3_probs: dict[int, float],
                  marks: dict[int, float | int | None],
                  ) -> tuple[int, int, list[int]] | None:
    """(軸1, 軸2, 相手) を返す。組めない場合は None。

    軸1 は**1着率**最大（1着の順序を決めるのは単勝率であって3着内率ではない）、
    軸2 は**3着内率**最大。どちらも印なし集合の中から選ぶ。
    相手は残りの車を3着内率の降順（7車立てなら5車＝総流しなので順序は
    三連単の点数に影響しないが、三連複プールの選抜に効く）。
    """
    um = [f for f in rank_7h2_unmarked(marks) if f in win_probs and f in top3_probs]
    if len(um) < 2:
        return None
    a1 = max(um, key=lambda f: win_probs[f])
    a2 = max((f for f in um if f != a1), key=lambda f: top3_probs[f])
    legs = sorted((f for f in top3_probs if f not in (a1, a2)),
                  key=lambda f: -top3_probs[f])[:RANK_7H2_LEGS_N]
    if not legs:
        return None
    return a1, a2, legs


def rank_7h2_build_legs(win_probs: dict[int, float], top3_probs: dict[int, float],
                        marks: dict[int, float | int | None],
                        ) -> tuple[list[frozenset], list[str]]:
    """(三連複の目, 三連単の目) を返す。組めない場合は空リスト。

    三連複は◎を除いたプール上位5車のBOX（最大10点）。

    🔴 **2026-08-18: 三連単を破棄し三連複のみにした**（ユーザー判断）。
       `RANK_7H2_TRIFECTA_ENABLED = False` のとき三連単は常に空を返す。
       停止の根拠は同定数の定義部。三連単側のロジックは残してある。
    """
    ax = rank_7h2_axes(win_probs, top3_probs, marks)
    if ax is None:
        return [], []
    a1, a2, legs = ax
    honmei = next((f for f, v in marks.items()
                   if v is not None and int(v) == WT_MARK_HONMEI), None)
    pool = ([a1, a2] + [f for f in legs if f != honmei])[:RANK_7H2_TRIO_POOL_MAX]
    trio = ([frozenset(c) for c in _combinations(pool, 3)] if len(pool) >= 3 else [])
    if not RANK_7H2_TRIFECTA_ENABLED:
        return trio, []
    tf = ([f"{a1}-{a2}-{c}" for c in legs]
          + [f"{a1}-{c}-{a2}" for c in legs])
    return trio, tf


def rank_7h2_stakes(n_trio: int, n_tf: int) -> tuple[int, int, int]:
    """(三連複の1点あたり, 三連単の1点あたり, 合計購入額) を返す。

    **合計は必ず RANK_7H2_BUDGET_CAP 以下**になる。三連単を単価固定で買い、
    残りを三連複へ均等割りする（7H1 と同じ方式）。
    """
    uf = RANK_7H2_TF_UNIT if n_tf > 0 else 0
    # 欠車などで点数が想定より多いと単価固定では枠を食い破る。
    # 三連複に最低 1点100円を残せるところまで 100円ずつ落とす。
    while uf and uf * n_tf + RANK_7H2_UNIT * max(n_trio, 0) > RANK_7H2_BUDGET_CAP:
        uf -= RANK_7H2_UNIT
    rem = max(0, RANK_7H2_BUDGET_CAP - uf * max(n_tf, 0))
    ut = (rem // n_trio) // RANK_7H2_UNIT * RANK_7H2_UNIT if n_trio > 0 else 0
    if ut < RANK_7H2_UNIT:
        ut = 0
    total = ut * n_trio + uf * n_tf
    if total > RANK_7H2_BUDGET_CAP:      # 到達しない想定だが不変条件として守る
        raise ValueError(f"7H2 の購入額が上限を超えました: {total}円")
    return ut, uf, total


def rank_7h2_daily_select(candidates: list[dict]) -> list[dict]:
    """当日の候補から 7H2 を選出する。

    candidates の各要素に必要なキー:
      `n_entries`(=7) / `entropy`（3着内率の正規化エントロピー） /
      `honmei_share`（◎の3着内率シェア） /
      `legs_trio`（買い目。空なら除外。`legs_tf` は 2026-08-18 以降 常に空）

    **選別は絶対閾値2つで行う**（日ごとの相対順位ではない）。
      (1) エントロピー >= RANK_7H2_ENTROPY_MIN      … 荒れる読み（全7車の約20%）
      (2) ◎の3着内率シェア <= RANK_7H2_HONMEI_SHARE_MAX … ◎が厚すぎない（上位20%を除外）
    件数は開催規模にそのまま比例する（実測 12.7 → **約10.2件/日**）。
    """
    elig = [c for c in candidates
            if c.get("n_entries") == RANK_7H2_NE
            and c.get("entropy") is not None
            and float(c["entropy"]) >= RANK_7H2_ENTROPY_MIN
            and c.get("honmei_share") is not None
            and float(c["honmei_share"]) <= RANK_7H2_HONMEI_SHARE_MAX
            # 🔴 2026-08-18 の三連複一本化で `legs_tf` の条件を落とした
            #    （7H1 が 2026-08-15 に三連単一本化したときと同じ扱い）。
            and c.get("legs_trio")]
    elig.sort(key=lambda c: -float(c["entropy"]))
    return elig


# ═══════════════════════════════════════════════════════════════════════════
# RANK_7C — ベースモデル「終日の二軸」（2026-08-07 新設・7車立て専用）
#
# 【why】既存6ランクは合計 13.1件/日 しか対象がなく、しかも二軸的中率は
#   7S 41.8% / 7SS 45.0% / 7A 52.6% / 7B 57.0%（加重 約52%）＝**的中体験が薄い**。
#   7S/7A は「軸2車の信頼が低い＝配当が高い」側を意図的に取るランクなので、
#   その**逆側（軸2車が堅い側）**を取るベースを1本置く。両者は構造的に補完関係。
#
# 【目的関数】**二軸的中率 = P(軸2車がともに3着内)**。
#   7車立ての三連複2軸総流し5点は3列目が総流しなので、その的中率と**数学的に同値**。
#   ROI は目標にしない（ユーザー判断: ガミは購入者の金額配分に委ねる）。
#
# 【選別】ただ1つの条件。**モデル3着内率の上位2車の合計 >= RANK_7C_P3_SUM_MIN**。
#   軸2車もその上位2車。オッズを一切使わないので朝8:00の入稿に間に合う。
#
# 【選別】2条件。どちらもオッズ不使用（朝8:00に確定する）。
#   (1) モデル3着内率の**上位2車の合計 >= RANK_7C_P3_SUM_MIN**
#   (2) 相手（下記の足切り後）が **RANK_7C_LEGS_MIN 点以上**
#
# 【買い目】三連複 軸2車（=上位2車）+ 相手（3着内率 >= RANK_7C_LEG_P3_MIN の車のみ）。
#   1レース RANK_7C_BUDGET 円を点数で均等割り（100円単位切捨て）。実測 4点63%/5点37%。
#
#   実測（honest walk-forward・p3 は月次凍結vintageの予測）:
#     | 窓 | 件/日 | 全レース比 | 二軸的中 | 的中/日 | ROI | 低配当的中(<=2倍) |
#     |---|---|---|---|---|---|---|
#     | 評価窓 2025-07〜2026-08 (400日) | 23.48 | 30.8% | **58.08%** | 13.64 | 77.3% | 2.10件/日 |
#     | 確認窓 2024-07〜2025-06 (365日) | 22.47 | 29.4% | **59.42%** | 13.35 | 77.8% | 2.08件/日 |
#   四半期別 的中 55.8〜62.0% / ROI 74.3〜79.0%。**0件の日は無い**
#   （日次件数 中央値24・最小9・最大39）。的中時平均配当 5.82倍。
#   設計は評価窓で行い、**確認窓でも件数・的中率・ROI・低配当率すべて再現した**。
#
# 【✂️ ガミ対策として検証して落としたもの — 再提案しない】
#   - **上位2車の合計に上限を付けて堅いレースを見送る**: ROI がほぼ動かず件数だけ失う
#     （上限なし 77.3/78.8% → 上限1.70 で 76.8/80.3% と**両窓で符号が逆**）。
#   - **上位3車の合計に上限**（連続量では最良の低配当予測子）: 件数を揃えると
#     低配当削減は18〜30%止まりで的中率も落ちる。**点数ゲート(2)に完敗**。
#   - **実質的中率（払戻>=投資）はどの合計帯でも 18〜24% で横ばい**。
#     合計が上がると的中率は 38.5→88.2% と伸びるのに実質的中は動かない＝
#     **増えた的中はほぼ全部ガミ**。これは控除率の壁そのもので買い目の形では超えない。
#     到達点は ROI 80〜82%（相手を1〜2点まで絞った場合・的中率は44〜52%へ低下）。
#   - **発走15分前の最終オッズで切れば低配当はほぼ全消し**にできるが、netkeirin は
#     8:00 入稿済みなので**商品からは外せない**。picks_history/Web の見送り記録に限る。
#
# 【✂️ 検証して落としたもの — 再提案しない】
#   - **オッズを選別/軸に使う**: 最終オッズなら三連複の市場確率上位5組で的中65.1%と
#     強いが、**朝オッズだと52.1%まで落ちて現行モデル(53.5%)を下回る**
#     （上位5組の一致 3.30/5点）。朝の板が薄く順位が確定していない。
#     運用要件（直前まで監視できない）とも合致するため恒久的に不採用。
#   - **「2位と3位の差」（＝2車が抜けている）**: 65.47%。差(gap)は「1・2位が3位から
#     離れている」だけで、その2車が絶対的に強いことを要求しないため 4.4pt 劣る。
#   - **「3位と4位の差」（＝3車が抜けている）**: 62.10%。3車拮抗は上位2車が突出して
#     いないということなので、二軸的中は**全体平均53.5%を下回る47.7%**。直感と逆。
#   - **上位2車の"積"**: 合計と実質同一（どの網羅率でも差0.1pt未満）。式が単純な合計を採る。
#   - **エントロピー / 上位3車合計 / 2位の高さ**: 68.6 / 67.6 / 68.2% でいずれも劣る。
#   - **条件分け**（同一ライン・分戦数・グレード・種別17区分・バンク長・競走得点の
#     ばらつき）: スコア5分位の**中**では差が残らない＝選別値が既に吸収している。
#     ユーザー方針「汎用条件で足りるなら条件分けしない」に合致。
#   - 🔴 **細切れ番組（最大ライン長<=2）での特別扱いは 2 案とも不採用**（2026-08-18）。
#     細切れは 7C の 17.1% を占め、picks_history 上では確かに弱く見える
#     （的中 32.5% vs 通常 41.3%・ROI 73.7 vs 76.9%）。だが:
#
#     (a) **見送り**: 件数 −17.1% に対し **表示的中 +0.1pt** / ROI +0.6pt のみ。
#         細切れは配当が高くガミが減るため、的中率の低下が表示的中で相殺される。
#         さらに細切れの **93% は 7C 単独**（7S は 1854件中 4件しか発火しない）ので、
#         落とすと商品が純減するだけ。
#     (b) **相手を3点に抑える**: 実装して walk-forward の A/B（同一レース・同一
#         vintage・6ヶ月 1,571R）を取った結果、**買い目が変わった 110R で
#         的中 50.0→40.0% / ROI 79.0→66.5%**（表示的中は +0.9pt のみ）。明確に悪化。
#
#     🔴 (b) を思いつかせた「細切れ×3点が最良（的中41.6%）」という
#        picks_history の表は **欠車との交絡**だった。あの 3点行は
#        「4点以上選定したが盤面/欠車で1点落ちた」レースであって
#        「3点を選んだ」レースではない。**点数別の集計から買い方を決めてはいけない。**
#   - **ペアモデル**（21ペアをLightGBMで直接スコア）: 二軸的中 +1.3pt は出る
#     （53.48→54.84% 全レース時、95%CI [+0.93,+1.76]）が、月次vintage学習・配布・
#     backfill が必要。**第2弾として保留**（本ランクの閾値を差し替えるだけで移行可能）。
#
# 【重複の扱い】7C の母集団は「軸選定に成功した全7車レース」で、既存ランクとは
#   **論理的に排他ではない**（7SS/7S/7A/7B が wt_overlap_n で排他なのとは違う）。
#   `picks_history.race_key` は `{レースキー}#{suffix}` 形式なので**同一レースに
#   複数ランクの行を持てる**（実データでも 7H1 と 7B が共存している）。したがって
#   **候補生成・記録の段階では重複を排除しない**（ユーザー判断: 重なりは気にしない）。
#   重複排除は **netkeirin 入稿でのみ**行う（1レース1商品という外部仕様のため）。
#   優先順位は `netkeirin_submit_wt.RANK_ORDER`（7H2 > 7T1 > 7T3 > 7S > 7B > 7C > 7H1 > 7M1）。
#   実測の重なりは 2.4〜3.2件/日で、入稿に残る 7C は 16.7件/日。
#
# memory: keirin_base_model_two_axis_2026_08_07
# ═══════════════════════════════════════════════════════════════════════════

RANK_7C_NE = 7        # 対象車数（7車ちょうど）


# ═══════════════════════════════════════════════════════════════════════════
# RANK_9C — 9車のベースモデル（2026-08-14 新設・9S/9A を置換）
#
# 【なぜ要るのか】7車には 7C（終日を対象にする的中体験の土台）があるが、
#   9車には対応するランクが無く、旧世代の 9S/9A のままだった。実測（2026年）:
#
#     9車・素の p3上位2車   二軸的中 40.7%（ランダム 8.3% の 4.89倍）
#     9A（実運用）          二軸的中 26.4%（       同         3.18倍）
#
#   🔴 **9A は「素直に上位2車を採る」より 14.3pt 低い**＝ゲートが逆効果だった。
#      モデル自体は9車のほうがよく効いている（正規化倍率は7車 3.70x より上）。
#
# 【7C の定数は使えない】車数が増えると上位2車の合計が構造的に下がる:
#
#     上位2車合計(中央)   7車 1.457 → 9車 1.326
#     7C の 1.44 を通る率 7車 53.7% → 9車 **21.2%**
#
#   したがって9車向けに掃引した（「検証由来の閾値をそのまま定数にすると壊れる」）。
#
#   🔴 **2026-08-21 訂正: ここには「`pred_top3_pct` はレース内合計が 3.0 に
#      正規化される」と書いてあったが事実と違う。正規化は一切していない。**
#      3着内率の合計は**定義上 3 になるはず**（3着までに3人入る）なので、
#      較正が合っていれば自然に 3 付近へ寄るだけで、レースごとにばらつく:
#
#        Σpred_top3（7車・7S 母集団 3,254R 実測）
#          中央 2.976 / 5%tile 2.667 / 95%tile 3.253
#
#      上の「上位2車合計が車数で下がる」という**観測そのものは正しい**ので、
#      9車向けに掃引し直した判断は変わらない。誤っていたのは機序の説明だけ。
#      ⚠️ ただし **`RANK_9C_P3_SUM_MIN`(1.30) も `RANK_7C_P3_SUM_MIN` 相当の
#      1.44 も、この誤解の上で「正規化された値」として掃引された絶対閾値**である。
#      合計が ±10% 揺れる以上、**同じ閾値でもレースによって実質的な厳しさが違う**。
#      正規化して掃引し直すと現行ゲートの判定は 21.3% 入れ替わる（下記 axis_sum 参照）。
#
# 【検証】掃引窓 2026-01〜06(1,138R) で選び、確認窓 2026-07〜08-14(280R) で確認。
#   walk-forward（月次vintage）なので model-vintage look-ahead は無い。
#
#     合計1.30/足切0.15  掃引 二軸49.6% → **確認 50.8%**（実質 44.0% → 48.5%）
#
#   🟢 二軸的中は5水準すべてで再現し、合計下限を上げるほど単調に伸びる関係も保たれた。
#   🔴 **ROI は再現しない**（掃引 83〜95% → 確認 59〜73%）。掃引窓の高 ROI は
#      三連複の裾（大きな配当1本）に引かれていただけ。**ROI で語る商品ではない**。
#
# 【9車固有の発見】
#   ⚠️ **相手の最低点数ゲートは9車では効かない**。7C の `LEGS_MIN=4`
#      （相手が少ない＝低配当を落とす）は、9車は相手が7車あるため
#      **3点と4点が同値**になり機能しない。したがって下限は3点に置くだけ。
#   ⚠️ 足切り 0.10 のほうが実質的中は高い(51.1%)が **ROI は 0.15 が高い**
#      (70.3% vs 61.5%)。9車は元々 ROI が薄いので 0.15 を採る（ユーザー判断）。
#   ⚠️ **7C の三連単切替（`RANK_7C_TRIFECTA_PW_MIN`）は入れない。**
#      9車では未検証。測っていないものを載せない。
# ═══════════════════════════════════════════════════════════════════════════

RANK_9C_NE = 9                     # 対象車数（9車ちょうど）
# モデル3着内率の上位2車の合計の下限。**9車向けに掃引して決めた絶対閾値**。
# 掃引: 1.20 二軸45.3% / **1.30 50.8%** / 1.40 58.2%（いずれも確認窓）。
# ⚠️ pred_top3 の較正に依存する。**モデルを再学習したら分布を確認して更新すること**。
RANK_9C_P3_SUM_MIN = 1.30
# ⚠️ **グレード別の引き上げ（RANK_9C_P3_SUM_MIN_BIG=1.40・PR#194）は 2026-08-17 に撤去した。**
#    あれは GII/GI で二軸が -13.5pt 落ちる問題をゲート側で手当てしたものだが、
#    原因は**モデルの較正**（上位グレードで p3 を +2.1pt 過大評価）だった。
#    `p3_calibration` を入れたので二重補正になる。較正後は同じ閾値 1.30 のまま
#    9車・上位グレードの通過が 43.2%→15.4%・通過分の二軸が 43.1%→54.5% になる。
# 相手の足切り。7C と同値だが**根拠は別**（9車で掃引した結果）。
RANK_9C_LEG_P3_MIN = 0.15
# 相手の最低点数。⚠️ 9車では**このゲートは実質効かない**（上記）。
# 買い目として成立する最低限として3点を置くだけ。
RANK_9C_LEGS_MIN = 3
RANK_9C_BUDGET = RACE_BUDGET
RANK_9C_UNIT = STAKE_UNIT


def rank_9c_daily_select(candidates: list[dict]) -> list[dict]:
    """9C の選出: 上位2車の3着内率合計が閾値以上 ∧ 相手が3点以上。

    軸と相手の**選び方は 7C と同じ**（`rank_7c_select_axis` /
    `rank_7c_select_legs` は車数に依存しない）。違うのは閾値だけ。

    ⚠️ 合計は**較正後の値**で見る（`p3_calibration`・2026-08-17）。候補が
       `p3_sum_top2_cal` を持たなければ生の `p3_sum_top2` へ落ちる（旧候補JSON互換）。

    ⚠️ 7C の「低配当パターン」除外は**9車では使わない**。あれは相手の点数が
       少ないことを低配当の指標に使う仕組みで、相手が7車ある9車では成立しない。

    ⚠️ **軸のライン組み替え（看板穴埋めの `_axes()`）はここへ持ち込まない。**
       ゲート通過分で測ると 的中 45.4→45.0% / ROI 85.2→82.2% と改善しない
       （2026-08-16・n=1,979・3指標とも有意差なし）。上位2車に確率が集中している
       帯では素の上位2車がそもそも正しく、入れ替えると確度を下げるため。

    returns 採用された候補（p3_sum_top2 の降順＝自信のある順）。
    """
    return sorted(
        (c for c in candidates
         if c.get("n_entries") == RANK_9C_NE
         and c.get("p3_sum_top2") is not None
         and float(_gate_p3_sum(c)) >= RANK_9C_P3_SUM_MIN
         and len(c.get("legs_9c") or []) >= RANK_9C_LEGS_MIN),
        key=lambda c: -float(c["p3_sum_top2"]),
    )


def _gate_p3_sum(c: dict) -> float:
    """ゲートが見る「上位2車の3着内率合計」。**較正後の値を優先する**。

    🔴 較正（`p3_calibration`）は決勝・上位グレードでの過大評価を潰すためのもので、
       **順位は変えない**ので軸・相手の選び方には影響しない。効くのはここだけ。
    ⚠️ `p3_sum_top2_cal` が無い候補（較正導入前に作られたJSON・古い再構築）は
       生の値へ落ちる。**黙って0にしない**（0にすると全レースがゲートに落ちる）。
    """
    v = c.get("p3_sum_top2_cal")
    if v is None:
        v = c.get("p3_sum_top2")
    return float(v) if v is not None else 0.0


def rank_7c_select_axis(top3_probs: dict[int, float]) -> tuple[int, int, float] | None:
    """7Cの軸2車を選ぶ: モデル3着内率の上位2車と、その合計を返す。

    top3_probs: {frame_no: pred_top3}（レース内全車分・スケール不問だが
      RANK_7C_P3_SUM_MIN は 0-1 スケール前提なので呼び出し側で揃えること）

    3ヘッド軸（rank_7s_select_axis）とは**別の選び方**である点に注意。
    全7車で測ると両者の二軸的中率はほぼ同じ（53.48% vs 53.53%）だが、
    7C は「上位2車の合計」で選別するランクなので、選別値と軸を同じ量から
    導くほうが定義として一貫する（軸だけ3ヘッドにしても的中率は変わらない）。

    returns (axis1, axis2, p3_sum) or None（車数不足）。
    axis1 が上位・axis2 が次点。同値のときは車番の小さい方を上位とする。
    """
    if not top3_probs or len(top3_probs) < 2:
        return None
    ranked = sorted(top3_probs, key=lambda f: (-top3_probs[f], f))
    a1, a2 = ranked[0], ranked[1]
    return a1, a2, top3_probs[a1] + top3_probs[a2]


def rank_7c_use_trifecta(
    win_probs: dict[int, float] | None, axis1: int,
    pw_min: float = RANK_7C_TRIFECTA_PW_MIN,
    enabled: bool = RANK_7C_TRIFECTA_ENABLED,
) -> bool:
    """7Cを三連単（1着=軸1 / 2着=軸2 / 3着=相手流し）へ切り替えるか。

    win_probs: {frame_no: pred_win}（0-1 スケール）。**不明なら False**
      （情報が無いことを理由に買い方を変えない＝検証済みの既定である三連複に倒す）。
    axis1:     7Cの軸1（`rank_7c_select_axis` の第1要素＝3着内率の最上位）。

    根拠と実測値は RANK_7C_TRIFECTA_PW_MIN の定義部を参照。
    ⚠️ 判定は**軸1の単勝率だけ**。2着との差は足さないこと（効果が無く該当も変わらない）。

    🔴 **2026-08-17 以降は `RANK_7C_TRIFECTA_ENABLED = False` で常に False を返す**
       （ユーザー判断・高額狙いは 7T1/7H1/9H1 が担うので 7C は的中側へ寄せる）。
       停止の根拠と実測は `RANK_7C_TRIFECTA_ENABLED` の定義部。
    """
    if not enabled:
        return False
    if not win_probs:
        return False
    return float(win_probs.get(axis1, 0.0)) >= pw_min


def rank_7c_drop_ana_leg(
    legs: list[int], top3_probs: dict[int, float], wt_ana: int | None,
) -> list[int]:
    """総流し帯（4点以上）から WT△ を1車外す。**条件を満たさなければ素通し**。

    発動条件（すべて満たしたときだけ）:
      - 買い目が `RANK_7C_ANA_CUT_MIN_LEGS`(4) 点以上＝落差カットが効かなかった帯
      - △が買い目に居る
      - △の3着内率が `RANK_7C_ANA_CUT_P3_MIN`(0.40) 以上
      - 外した残りが `RANK_7C_ANA_CUT_FLOOR`(3) 点以上

    🔴 **`wt_ana` が None なら何もしない**（fail-open）。印が取れない日に
       買い目が勝手に変わらないようにするため。根拠と実測は
       `RANK_7C_ANA_CUT_P3_MIN` の定義部。
    """
    if wt_ana is None or len(legs) < RANK_7C_ANA_CUT_MIN_LEGS:
        return legs
    if wt_ana not in legs:
        return legs
    if top3_probs.get(wt_ana, 0.0) < RANK_7C_ANA_CUT_P3_MIN:
        return legs
    kept = [x for x in legs if x != wt_ana]
    return kept if len(kept) >= RANK_7C_ANA_CUT_FLOOR else legs


def rank_7c_cut_legs_by_gap(
    legs: list[int], top3_probs: dict[int, float],
    gap_min: float = RANK_7C_TRIO_GAP_MIN,
    legs_floor: int = RANK_7C_TRIO_LEGS_FLOOR,
    wt_ana: int | None = None,
) -> list[int]:
    """3着内率の落差で相手を打ち切る。**差が無ければ削らない**。

    legs: `rank_7c_select_legs` の結果（3着内率の降順）
    returns 買う相手（先頭は必ず残る）

    先頭から隣を見ていき、`top3_probs` の差が gap_min 以上になったらそこで止める。
    「割り込む余地が消えた」と判断できるところだけを削るための規則で、
    一律の点数制限とは目的が違う（`RANK_7C_TRIO_GAP_MIN` の定義部を参照）。

    🔴 **削りすぎたときの差し替えもここで行う**（2026-08-15・ユーザー判断。
       実測表は `RANK_7C_TRIO_LEGS_FLOOR` の定義部）:

         1〜2点になった → **総流し（削らない）へ戻す**（2026-08-17〜）
         3点以上       → そのまま

       🔴 2026-08-15〜17 は「1点なら相手の2,3番手2点」へ差し替えていたが、
          **その2点買いだけを取り出すと的中22.9%** と精度が突出して低いことが
          分かったため総流しへ戻した。看板側は素の的中 +40.8pt・表示 +8.0pt・
          ROI +5.7pt と3指標すべてで改善する。実測表は
          `RANK_7C_TRIO_LEGS_FLOOR` の定義部。

       ⚠️ **呼び出し側で下限を掛ける形にしないこと。** 候補生成・発走前判定・
          再構築のどれか1つを忘れると、その経路だけが1点買いを出し続ける。
       ⚠️ `legs_floor=0` を渡すと素のカットだけを返す（検証用。
          `scripts/exp_7c_gap_cut_by_size.py` はこれを使う）。

    🔴 **落差が無くて削れなかった総流し帯（4点以上）は `wt_ana` で削る**
       （2026-08-15・案E）。落差カットと目的が違う——あちらは「割り込む余地が
       消えた相手」を落とし、こちらは「よく来るが必ず安い相手（△）」を落とす。
       `wt_ana=None`（既定）なら何もしない。根拠は `RANK_7C_ANA_CUT_P3_MIN` の定義部。
    """
    if not legs:
        return []
    out = [legs[0]]
    for prev, cur in zip(legs, legs[1:]):
        if top3_probs.get(prev, 0.0) - top3_probs.get(cur, 0.0) >= gap_min:
            break
        out.append(cur)
    if legs_floor <= 0 or len(out) > legs_floor:
        return rank_7c_drop_ana_leg(out, top3_probs, wt_ana)
    # 🔴 **削りすぎたら総流しへ戻す**（2026-08-17・ユーザー判断で 2,3番手2点 から変更）。
    #    詳細と実測は `RANK_7C_TRIO_LEGS_FLOOR` の定義部。
    return rank_7c_drop_ana_leg(list(legs), top3_probs, wt_ana)


# 🔴 **軸2が WT◯ と一致したら、◎◯以外の3着内率1位へ差し替える**（2026-08-19・ユーザー判断）
#
# 【なぜ】軸2車が ◎◯ と完全一致するのは **7C の 92.8%** ＝既定状態。そこで外れると
#   **88.7% が「片方だけ来た」**で、飛ぶのはほぼ ◯ 側（◎ が3着内 87.2% / ◯ 75.6%）。
#   ユーザー判断: 「片方は当たっているので改善の余地がある。**◎◯の予想を売って
#   外すのは印象が良くない**。軸2を WT◯ 以外から再選出する」。
#
# 【なぜ3着内率か】1着率・2着内率と比べた（`exp_7c_axis2_reselect_off_marks.py`）。
#   買い目は三連複・軸2頭ながしで、軸に求めるのは「3着以内に入ること」。
#   条件を強くするほど（3着内 → 2着内 → 1着）成績が落ちる:
#
#     | 軸2の選び方 | 二軸的中 | 素の的中 | 表示的中 | ROI | 倍率中央 |
#     |---|---|---|---|---|---|
#     | V0 現行（◯のまま） | 69.6% | 63.1% | 34.3% | 82.8% | 1.06 |
#     | V1 1着率1位 | 33.0% | 30.5% | 26.1% | 71.7% | 1.66 |
#     | **V2 3着内率1位** | **45.3%** | **43.0%** | **31.9%** | **83.3%** | **1.38** |
#
#   （2026-06-08〜08-18・朝の板を配分に使用・766R。全期間 p3のみ配分でも
#     V2 > V1 は同じ向き: 二軸 41.5% vs 31.6% / ROI 76.3% vs 72.4%）
#   ⚠️ **2着内率は比較できていない**。`wt_entries.pred_top2_pct` は 2026-08-12 に
#      追加された列で過去が空（充足 2026-08 で 36.3% / それ以前 0%）。
#      月次凍結 vintage（`lgbm_wt_top2_mYYMM`）を作ってバックフィル中（2026-08-19）。
#      揃ったら測り直すこと。理屈の上では「2着内は3着では足りないという余分な条件を
#      課す」ので 3着内率を上回る見込みは薄い。
#
# 🔴 **これは大きな取引である。** ROI はほぼ動かない（+0.5pt [−14.3,+17.2]）が、
#    **二軸的中 −24.3pt [−29.1,−19.6]・素の的中 −20.1pt・表示的中 −2.5pt** を払って
#    **倍率中央 1.06→1.38・10倍以上 0.00%→0.65%** を得る。
#    ＝「当たる回数を約1/3減らして、当たったときの配当を4割増やす」。
#    7C の目的関数は二軸的中率だったので、**7C の性格そのものが変わる**。
#    ユーザーが数字を見た上で採用を決めた（2026-08-19）。
#
# ⚠️ **◎ はほぼモデル軸1**（89.9%）なので、実質「軸2だけを印から離す」操作。
#    軸1 は触らない。
# ⚠️ ◎ か ◯ のどちらかが取れないレースでは**何もしない**（判定不能で軸を動かすと
#    根拠のない差し替えになる）。
#
# 【✂️ ラインを考慮して選ぶ案は 2026-08-19 に検証して不採用 — 再提案しない】
#
#   ユーザー指摘:「単純に3番手として進めていたが、ラインを考慮する必要がありそう」。
#   看板穴埋めでは「指数1位がライン先頭 → 軸2はその同ライン最上位（番手）」が
#   効いている（7車 ROI +2.5pt・的中を落とさない）ので筋は通る。測った結果:
#
#     | 軸2の選び方（◎◯を除く） | 二軸的中 | 表示的中 | ROI | 倍率中央 | 10倍+ |
#     |---|---|---|---|---|---|
#     | **3着内率1位（現行）** | **45.3%** | **31.9%** | **83.3%** | 1.38 | 0.65% |
#     | 軸1と同ラインの最上位 | 42.4% | 28.6% | 77.7% | 1.26 | 0.78% |
#     | 別ラインの先頭1位 | 32.0% | 25.8% | 79.6% | **1.77** | **1.17%** |
#     | 同ライン→別線先頭→指数 | 42.2% | 28.5% | 77.9% | 1.26 | 0.78% |
#
#   （2026-06-08〜08-18・朝の板を配分に使用・766R。全期間 p3配分 6,865R でも
#     順位は同じ: 現行 25.7% / 同ライン 22.7% / 別線先頭 23.7%）
#
#   🔴 **ライン考慮の3案はすべて現行に劣る。両窓で一致。**
#      看板穴埋めで番手が効いたのは「素の指数上位2車から組み替える」話で、
#      ここは「**◎◯を外した残りから選ぶ**」話。既に人気2車を外した母集団で
#      さらに番手へ寄せると、軸が弱くなりすぎる。
#
#   ✅ ただし「別ラインの先頭1位」は**配当だけなら最良**（倍率中央 1.77・
#      10倍以上 1.17%）。二軸的中 32.0% は 7C の水準ではないので本体には入れないが、
#      高配当ランクの種としては残る。
# 🔴 **落差がこれ以上なら差し替えない**（2026-08-21・ユーザー判断）。
#
# 差し替えは「軸2を ◎◯ から離す」操作なので、**離した先がどれだけ弱いか**で
# 損得が変わる。落差＝現軸2の3着内率 − 差し替え先の3着内率。
#
# 実測（2026-01〜・7車・7C ゲート通過・確定オッズ 5,806R・総流し5点で採点）:
#
#   | 落差 | n | 差し替えなし 二軸/配当中央/ROI | あり 二軸/配当中央/ROI |
#   |---|---|---|---|
#   | 〜10pt | 920 | 58.3% / 3.20 / 74.7% | 49.0% / 3.00 / 84.3% |
#   | 10-20 | 1,754 | 61.0% / 3.40 / 71.6% | 47.9% / 2.70 / 79.4% |
#   | 20-30 | 1,780 | 67.3% / 3.45 / 73.9% | 42.5% / 2.40 / 74.6% |
#   | **30-40** | 974 | 73.4% / 3.70 / **77.5%** | 38.2% / 2.50 / **52.2%** |
#   | **40pt〜** | 378 | 75.9% / 3.70 / **80.1%** | 36.2% / 2.70 / **70.2%** |
#
# 🔴 **落差が大きい帯では「配当の見返り」も消える**（配当中央が 3.70 → 2.50）。
#    差し替え後は弱い軸2を必ず含むので、当たるときも人気サイドの目になりやすく、
#    **的中率と配当を同時に失う**。採用時（2026-08-19）の「当たる回数を減らして
#    配当を取る」という取引が、この帯では成立していない。
#
# 掃引窓(2026-01〜04)と確認窓(2026-05〜08)で分けた ROI 差（あり − なし）:
#
#   | 落差 | 掃引 | 確認 | 判定 |
#   |---|---|---|---|
#   | 〜10pt | +3.0 | +22.5 | 差し替えが有利 |
#   | 10-20 | +13.5 | **−4.2** | 符号反転＝判定不能 |
#   | 20-30 | −3.3 | **+8.0** | 符号反転＝判定不能 |
#   | **30-40** | **−28.3** | **−18.7** | **両窓で有害** |
#   | **40pt〜** | **−11.2** | **−7.3** | **両窓で有害** |
#
# → **両窓で符号が一致して有害な 30pt 以上でのみ差し替えを止める**。
#   20pt 案は 20-30 帯が確認窓で符号反転するため採らない（該当が 54% と広く、
#   2026-08-19 の判断をほぼ覆すことにもなる）。
#
# ⚠️ 単位は `top3_probs` と同じ **0-1 スケール**（呼び出し側は `pred_prob` を渡す）。
# ⚠️ 止めた結果 軸が ◎◯ に戻って配当が安くなるレースは、
#    `stake_allocation.MIN_EXPECTED_PAYOUT_BY_RANK["7C"]`（1.5倍）が弾く。
#    **差し替えが軸2を弱くすることで想定払戻を押し上げ、本来この足切りに
#    掛かるはずのレースを通していた**（2026-08-21 西武園1R の実例）。
RANK_7C_RESELECT_CLIFF_MAX = 0.30


def rank_7c_reselect_axis2_off_marks(
    top3_probs: dict[int, float], axis1: int, axis2: int,
    wt_honmei: int | None, wt_taikou: int | None,
    cliff_max: float = RANK_7C_RESELECT_CLIFF_MAX,
) -> int:
    """軸2車が {◎, ◯} と完全一致するとき、軸2を ◎◯ 以外の3着内率1位へ差し替える。

    一致しない・印が取れない・候補が居ない場合は `axis2` をそのまま返す。
    軸1 は決して変えない（呼び出し側で使い回す）。

    🔴 **落差（現軸2 − 差し替え先）が `cliff_max` 以上なら差し替えない**
       （2026-08-21）。根拠は定数の定義部。
    """
    if wt_honmei is None or wt_taikou is None:
        return axis2
    if {axis1, axis2} != {wt_honmei, wt_taikou}:
        return axis2
    pool = [f for f in top3_probs if f not in (axis1, wt_honmei, wt_taikou)]
    if not pool:
        return axis2
    # 同率は車番の小さい方（再現性のため。`rank_7c_select_axis` と同じ作法）
    alt = max(pool, key=lambda f: (top3_probs[f], -f))
    # 🔴 落差が大きいレースは、差し替えると的中率も配当も失う。
    if top3_probs.get(axis2, 0.0) - top3_probs.get(alt, 0.0) >= cliff_max:
        return axis2
    return alt


def rank_7c_buy_plan(
    top3_probs: dict[int, float], win_probs: dict[int, float] | None,
    axis1: int, legs: list[int], wt_ana: int | None = None,
) -> tuple[str, list[int]] | None:
    """7Cの買い方を決める。`(bet_kind, 買う相手)` か、買わないなら None。

    top3_probs / win_probs: {frame_no: 確率}（0-1 スケール）
    axis1: `rank_7c_select_axis` の第1要素
    legs:  `rank_7c_select_legs` の結果（3着内率の降順・4〜5点）

    🔴 **ここが 7C の買い方の単一正本**。候補生成・発走前判定・入稿・Web が
       同じ関数を通すこと。片方だけ直すと「表示と入稿の食い違い」になる
       （このリポジトリが繰り返し踏んでいる事故）。

    根拠と実測値は `RANK_7C_TRIFECTA_PW_MIN` / `RANK_7C_TRIO_P3_SUM_MIN` の
    定義部を参照。
    """
    if not legs:
        return None
    if rank_7c_use_trifecta(win_probs, axis1):
        # 三連単は絞らない（相手全部・順序固定）。点数を変えると効果が消える。
        # 🔴 △削り（案E）も掛けない。三連複側だけの規則。
        return "trifecta", list(legs)
    p3_sum = sum(sorted(top3_probs.values(), reverse=True)[:2])
    # 🔴 **断然の1車がいるレースは三連複側のゲートを免除する**（2026-08-17）。
    #   `RANK_7C_TRIO_P3_SUM_MIN` は「軸2車の信頼が足りないレースを落とす」ための
    #   ゲートで、**三連単へ切り替わるレースには元々掛けていなかった**。
    #   2026-08-17 に切替を停止した結果、その母集団が三連複側へ流れてゲートに
    #   掛かるようになり、**副作用で 0.60件/日 が見送りになっていた**。
    #   落ちていたのは ROI 90.5% の帯（＝最も落としてはいけない側）。
    #
    #   免除の根拠: このゲートは「上位2車の3着内率合計」で信頼を測るが、
    #   単勝率0.70以上の1車がいるレースは**別の根拠で信頼できる**。
    #   実測（4.24件/日）: 免除なし 3.64件/日 ROI 74.9% → 免除あり 4.24件/日 77.1%。
    #   7C 全体では 12.89→13.49件/日・ROI 77.9→78.5%（表示的中は 30.7% で同じ）。
    if (p3_sum < RANK_7C_TRIO_P3_SUM_MIN
            and not rank_7c_use_trifecta(win_probs, axis1, enabled=True)):
        return None
    return "trio", rank_7c_cut_legs_by_gap(legs, top3_probs, wt_ana=wt_ana)


def rank_7c_is_lowpay_pattern(
    top3_probs: dict[int, float], line_groups: dict[int, object] | None,
    gap34_min: float = RANK_7C_LOWPAY_GAP34_MIN,
) -> bool:
    """7Cの低配当パターン判定: 上位3車が抜けている ∧ その3車が同一ライン。

    top3_probs:  {frame_no: pred_top3}（0-1 スケール・レース内全車）
    line_groups: {frame_no: wt_entries.line_group}。**不明なら False**
      （情報が無いことを理由に推奨を減らさない＝安全側は「買う」）。

    True なら見送る。根拠は RANK_7C_LOWPAY_GAP34_MIN 定義部のコメント参照。
    ⚠️ 片方だけの条件で切ってはいけない（的中率の犠牲が大きい）。
    """
    if not line_groups or len(top3_probs) < 4:
        return False
    ranked = sorted(top3_probs, key=lambda f: (-top3_probs[f], f))
    if top3_probs[ranked[2]] - top3_probs[ranked[3]] < gap34_min:
        return False
    gs = [line_groups.get(f) for f in ranked[:3]]
    if any(g is None for g in gs):
        return False
    ss = [str(g).strip() for g in gs]
    return bool(ss[0]) and ss[0] == ss[1] == ss[2]


def rank_7c_daily_select(candidates: list[dict]) -> list[dict]:
    """7Cの選出: 上位2車の3着内率合計が閾値以上 ∧ 相手が RANK_7C_LEGS_MIN 点以上
    ∧ 低配当パターン（`lowpay_pattern`）でないこと。

    candidates: rank_7s_* と同じ生候補 dict のリスト。最低限
      {"p3_sum_top2": float, "legs_7c": list[int]} を持つこと
      （`rank_7c_select_axis` / `rank_7c_select_legs` の結果を候補生成時に載せておく）。
      `lowpay_pattern` は `rank_7c_is_lowpay_pattern()` の結果。**欠けていたら
      False 扱い**（旧形式の候補JSONを読んでも落ちないようにするため）。

    **他ランクとの重複は排除しない**（上記セクションコメント参照）。
    日次件数の上限も設けない（実測 最大39件/日で暴走の懸念がないため）。

    returns 採用された候補のリスト（p3_sum_top2 の降順＝自信のある順）。
    """
    return sorted((c for c in candidates if rank_7c_accepts(c)),
                  key=lambda c: -float(c["p3_sum_top2"]))


def rank_7c_accepts(c: dict) -> bool:
    """候補1件を 7C が買うか。**7C の受理条件の単一正本**。

    🔴 `rank_7m1_daily_select` が「7C が見送ったレース」を拾うためにこの述語を
       共有する。条件をここ以外に写すと、7C の閾値を動かしたときに 7M1 側だけ
       古い条件のまま残り、**両ランクが同じレースを二重に買う**（あるいは
       どちらも買わない隙間ができる）。このリポジトリが繰り返し踏んでいる
       「同じ判定の二重管理」の型なので、必ずこの関数を経由すること。
    """
    if c.get("p3_sum_top2") is None:
        return False
    if _gate_p3_sum(c) < RANK_7C_P3_SUM_MIN:
        return False
    if len(c.get("legs_7c") or []) < RANK_7C_LEGS_MIN:
        return False
    # 🔴 買い方が決まらないレースは買わない（2026-08-09）。三連複側の
    #    追加ゲート `RANK_7C_TRIO_P3_SUM_MIN` はここで効く。
    #    ⚠️ 旧形式の候補JSON（`legs_7c_buy` を持たない）は落とさない。
    #      キーが無い＝判定不能であって「買わない」ではないため、
    #      当日リカバリで旧JSONを読んだときに商品が全滅するのを防ぐ。
    if "legs_7c_buy" in c and not c.get("legs_7c_buy"):
        return False
    if c.get("lowpay_pattern"):
        return False
    # 🔴 軸1が抜けすぎたレースは買わない（2026-08-18）。
    #    キーが無い旧形式の候補JSONは**落とさない**（判定不能であって
    #    「買わない」ではない。当日リカバリで旧JSONを読んでも全滅しない）。
    if (c.get("axis1_p3") is not None
            and float(c["axis1_p3"]) >= RANK_7C_AXIS1_P3_MAX):
        return False
    return True


def rank_7c_select_legs(
    others: list[int], top3_probs: dict[int, float],
    p3_min: float = RANK_7C_LEG_P3_MIN,
) -> list[int]:
    """7Cの相手選択: 3着内率が p3_min 以上の車だけを買う（点数可変）。

    others:     軸2車を除いた残り車（通常5車。欠車時は盤面に残った車だけを渡す）
    top3_probs: {frame_no: pred_top3}（0-1 スケール）

    「3着内に入れなそうな車を外す」ための足切り。返す点数が
    RANK_7C_LEGS_MIN 未満なら**そのレースは買わない**（判定は呼び出し側）。
    採用構成では実測 4点63% / 5点37%（平均4.37点）。

    ⚠️ ここで**最低1車を無理に残してはいけない**。「相手が少ししか残らない」
       こと自体が「配当が付かない」の指標なので、埋め合わせると効果が消える。
    ⚠️ 相対比（最強相手の◯%以上）やギャップ切りの方が ROI は高い（78〜82%）が、
       的中率が 43〜62% まで落ちる。**的中体験を優先するユーザー判断で絶対15%を採用**。

    returns 買う相手のリスト（pred_top3 の降順）。
    """
    ranked = sorted(others, key=lambda x: (-top3_probs.get(x, 0.0), x))
    return [x for x in ranked if top3_probs.get(x, 0.0) >= p3_min]


def rank_7c_unit_stake(n_legs: int, budget: int = RANK_7C_BUDGET,
                       unit: int = RANK_7C_UNIT) -> int:
    """7Cの1点あたり賭け金。全ランク共通の `unit_stake` へ委譲する。

    2026-08-07 に全ランクが予算枠方式へ統一されたため、7C 専用の実装ではなくなった。
    名前は既存の呼び出し元との互換のために残している。
    """
    return unit_stake(n_legs, budget, unit)


# ═══════════════════════════════════════════════════════════════════════════
# RANK_7M1 — 中間層「混戦 × 市場乖離」（2026-08-17 新設・7車立て専用）
#
# 【命名】`{車数}M{連番}`（M = Middle）。既存の系統は
#   C=ベース(的中重視) / S・B=予想ベース / H=穴(Hole) / T=三連単の高配当枠 で、
#   本ランクは**その中間の払戻帯**を担うので新しい系統文字を立てた。
#
# 【なぜ必要か】現行の商品は payout の分布が二極化していて、間が空いている
#   （2025-01〜2026-08 の picks_history 実測・1レース投資額に対する倍率）:
#
#     層       ランク        的中     払戻中央    ガミ率
#     ベース   7C/7S/9C   38〜47%   1.45〜1.57倍  20〜26%
#     ベース   7B           30.4%   2.29倍         4.5%
#     （空白）              —       3〜10倍        —
#     PR       7H1           4.7%   8.38倍         0%
#     PR       7T1           3.5%   21.9倍         0%
#
#   ユーザー方針「**払戻2倍未満は落車等を考えると見送るべき**」に照らすと、
#   ベース層は中央1.5倍台でその方針を満たしていない。本ランクは
#   **的中12% / 払戻中央4.9倍 / 2倍未満は的中の13%**の帯を埋める。
#
# 【定義】7C の信頼ゲートを**裏返した**母集団に、市場乖離の条件を重ねる:
#
#     上位2車の3着内率合計 < RANK_7C_P3_SUM_MIN   … 7C が取らない混戦
#     ∧ モデル上位2車 ≠ {WT◎, WT○}               … 公式印と評価が割れている
#     → 二軸 = モデル上位2車 / 相手 = 軸を除く5車の**下位3車**（全体では指数5〜7番手）
#       ＝ 相手の上位2枚（全体3・4番手）をあえて捨てる
#       さらにそのうち 3着内率 < RANK_7M1_LEG_P3_MIN の車を削る（最低2点）
#
#   閾値は 7C と**同じ定数を共有する**（`RANK_7M1_P3_SUM_MAX`）。別々に持つと
#   7C 側を動かしたときに隙間または重複が生まれる。
#
# 【検証】月次凍結 vintage の honest walk-forward（2025-01〜2026-08-16・6,275R）:
#
#     10.5件/日 / 的中 12.1% / ガミ 1.4% / 払戻 p25 2.83倍・中央 4.90倍・最大71倍
#     ROI 81.7% [74.7, 89.4]（2025 81.5% / 2026 82.0%）
#
#   🔴 **効いているのは「相手の削り方」ではなく「レース選定」**。同一レース上で
#      相手だけを動かすと ROI は 71.6〜74.6% でほぼ平坦（払戻中央だけが
#      1.16→17.6倍に動く）。
#
#      🔴 **2026-08-21 訂正: この掃引は「位置での入れ替え」しか見ていない。**
#         相手を **EV（予測オッズ × 3着内確率）順**に並べ替えると、3点据え置きのまま
#         「2倍以上で的中」が **+0.30 / +0.22 件/日（両窓とも有意）**・ROI も
#         +0.7〜2.0pt 改善する。**「相手をどう選んでも平坦」ではない。**
#         詳細は `rank_7m1_select_legs` の docstring。一方 印一致/不一致 で割ると同じ買い目で
#      +7〜+13pt の差が出て、**年で符号が一致する**（2025 +12.0pt / 2026 +11.3pt）:
#
#        相手=全部5点    不一致 77.6% / 一致 70.5%  → +7.1pt [+1.7,+12.8]
#        相手=下位3車3点 不一致 81.9% / 一致 70.2%  → +11.7pt [+2.8,+20.6]
#
#   ⚠️ **機序は「3着が人気薄から来る」ではない**（仮説と逆だったので残す）。
#      軸2車が3着内のとき3着目がモデル3番手である割合は
#      **印不一致のほうが高い**（41.1% vs 34.4%）。効いているのは着順分布ではなく
#      **軸2車自体が人気でないので全ての目が高く付く**こと。
#
# 🔴🔴 **ROI で採否を判断してはいけない層である。**
#   的中率が低く払戻の分散が大きいため、ROI を ±2.5pt に収めるには
#   **59,461R ＝ 約15.6年**かかる（ベース層は 11,500R ＝ 15.3ヶ月）。実際、
#   直近1ヶ月(331R)だけを見ると ROI 69.6%・対7S でも 59.1% vs 76.3% と
#   完敗に見えるが、全期間 2,068R の対戦では 80.8% vs 78.4% と逆転する。
#   **月次で見るのは 件数・的中率・払戻中央値の3つだけ**にすること
#   （的中率は月330Rで ±3.5pt と十分測れる）。
#
# 【入稿の優先順位】**最下位**（`netkeirin_submit_wt.RANK_ORDER` の末尾）。
#   同一レースで既存ランクと重なったら必ず譲る。全期間の直接対決の結果:
#
#     相手   競合R  両方的中  7M1のみ  相手のみ  的中率 7M1/相手   ROI 7M1/相手
#     7S     2,068     240       29      575    13.0% / 39.4%   80.8 / 78.4
#     7H1      592       0       71       31    12.0% /  5.2%   79.4 / 118.3
#     7B       169       0       21       46    12.4% / 27.2%   94.3 / 85.9
#     7T1       77       2       10        2    15.6% /  5.2%  107.5 / 115.7
#
#   🔴 7S とは**当たり方が部分集合**（7M1 の的中269件のうち240件＝89%は7Sも的中）。
#      7S を出せば済むので譲って正しい。
#
#   【✂️ 7M1 を 7S より上げる案は 2026-08-19 に測って不採用 — 再提案しない】
#     `scripts/exp_7s_vs_7m1_priority.py`。**堅い帯を取り込んだ後の現行定義**で
#     測り直した（2025-01-01〜2026-08-18・picks_history の本番記録）。
#     競合は **2,710R ＝ 7S の 84%**＝この優先順位が 7S 商品のほぼ全体を決める。
#
#       | 出すランク | 的中 | 表示的中 | ROI | 倍率中央 | 10倍+ | 的中中2倍未満 |
#       |---|---|---|---|---|---|---|
#       | 7S（現行） | **39.9%** | **32.0%** | 78.0% | 1.56 | 0.15% | 67.5% |
#       | 7M1        | 11.8% | 11.8% | 78.4% | **4.99** | **2.07%** | 8.1% |
#
#     🔴 **ROI は差が無い**（+0.4pt [−8.0, +9.6]・2025 +0.9 / 2026 −0.3 で符号反転）。
#        この層は ROI で決められない（本節冒頭の 15.6年 の話）。
#     🔴 **表示的中は 7S が +20.3pt [+18.5, +22.0]**（年別も一致）。netkeirin が
#        顧客に見せるのはガミを除いたこの数字なので、ここを20pt落とす選択は無い。
#     🔴 内訳: 両方的中 299 / **7Sのみ 781** / **7M1のみ 21** / 両方外れ 1,609。
#        7M1 の的中320件のうち **93% は7Sも当てている**。譲って失うのは
#        2,710R 中 21R（0.8%）だけで、逆に取ると 781R が「当たっていたのに外れ」になる。
#
#     ⚠️ **両方的中した299件は 299/299＝100% で 7M1 の払戻が上**（3点以下で配分が
#        厚く、相手が人気薄なので構造的にそうなる）。総払戻はほぼ同額
#        （7S 2,113万 vs 7M1 2,124万）。**個別のレースを見ると必ず 7M1 が良く見える**
#        ので、事例からこの優先順位を再検討してはいけない。
#        2026-08-19 大垣4R（7M1 78,210円 / 7S 21,330円）もこの299件の1つ。
#
#     ⚠️ 看板・大会クラスに絞ると ROI は 7M1 が +12.0pt に見えるが CI [−3.2, +29.0]
#        で有意でなく、それ以外の帯では −6.1pt。看板こそ目的関数が
#        **売上加重の的中率**なので、表示的中 −17.8pt の時点で採れない。
#
#     ✅ 譲っても 7M1 は競合しない 5,006R（5.9件/日・ROI 82.1%・倍率中央 5.71倍）を
#        持つ。**中間払戻帯を埋めるという役割は優先順位を上げなくても果たせている。**
#        7S 側も競合しない 508R は ROI 99.7% と別格で、住み分けは機能している。
#   🔴 7H1 とは**両方的中が0件＝完全に排他**だが ROI は年別でも一貫して 7H1 が上
#      （−24.1pt / −60.3pt）。ここも譲って正しい。
#   ✅ 譲った後に残る「誰も取らないレース」は 5.9件/日 で ROI 81.2%
#      （2025 79.8% / 2026 83.6%）＝**競合を避けても水準は落ちない**。
# ═══════════════════════════════════════════════════════════════════════════

RANK_7M1_NE = 7                              # 対象車数（7車ちょうど）
# 上位2車の3着内率合計の**上限**。7C の下限と同じ定数を共有し、両ランクが
# 隙間なく・重複なく分かれるようにする（別々の値を持たせないこと）。
RANK_7M1_P3_SUM_MAX = RANK_7C_P3_SUM_MIN
# 相手は「軸2車を除く5車」を3着内率の降順に並べた **3〜5番目**
# （＝レース全体では指数5〜7番手）。🔴 「モデル3〜5番手」ではない。
# 上位2枚（＝全体の3・4番手）を捨てるのが払戻帯を作る唯一の操作。
RANK_7M1_LEG_START = 2                       # 0-indexed（2 = 相手の3番目から）
# 🔴 **EV 順のときの点数（2026-08-24 に 3 → 4）。** 位置規則のフォールバックでも
#    使うが、そちらは `RANK_7M1_LEG_START` から数えるので下位4車になる。
#    根拠と実測は `RANK_7M1_MARK_DEMOTE` 定義部のセクションコメント。
RANK_7M1_LEGS = 4                            # 足切り前の基本点数
# 🔴 **足切りを掛ける「場所」が 7C と違う**（2026-08-17・ユーザー判断で追加）。
#   7C:   相手5車**全体から選抜する**規則（p3>=0.15 の車だけを買う）
#   7M1:  下位3車を採った**後で削るだけ**の規則
#   同じ 0.15 でも前者を 7M1 に適用すると、狙っている帯そのものが消えて母集団が
#   ほぼ空になる。**選抜には使わない／削るには使ってよい**。
#   値は 7C と同じ定数を共有する（新しいマジックナンバーを増やさないため。
#   「この値が最適」という検証結果があるわけではない）。
RANK_7M1_LEG_P3_MIN = RANK_7C_LEG_P3_MIN
# 足切り後の下限。下回ったら下位3車のうち**上位側**から戻して2点にする。
# 1点買いにしないのは 7C と同じ理由（`RANK_7C_TRIO_LEGS_FLOOR` のコメント参照）。
RANK_7M1_LEGS_MIN = 2
# 相手の並べ方。"position"（下位3車＋足切り）か "ev"（予測オッズ×3着内確率の降順）。
# 沿革: 2026-08-21 に "position" → "ev"、**2026-08-26 に "position" へ戻した**
#       （理由は下の「2026-08-26」節）。
# 🔴 **`rank_rule_version("7M1")` はこの定数を拾う。** 値を変えると版が変わり、
#    `picks_history.rule_version` で新旧の行が自動的に分かれる。
# 🔴 **この定数が唯一の切り替え点**（2026-08-26 に配線した）。以前は
#    `rank_7m1_select_legs(ev=...)` へ値を渡すかどうかが実際の分岐で、この定数は
#    版にしか効かない**飾りのスイッチ**だった。呼び出し元は live（`cli/main.py`）と
#    日次 tail 再構築（`backfill_7m1_rank_wt.py`）の2つあり、片方だけ直すと
#    毎朝の再構築で picks_history が別規則へ巻き戻る（7C が 2026-08-15 に踏んだ型）。
#    関数側で束ねたので、**戻すときも進めるときもここ1箇所**でよい。
# ⚠️ "ev" のときも、予測オッズが作れないレース（7車・9車以外＝実測3.7%）は
#    位置規則へ落ちる。
# ⚠️ "position" のとき ○1点集中（`RANK_7M1_MARU_CONC_*`）と ○/△の後回し
#    （`RANK_7M1_MARK_DEMOTE`）は**発火しない**（どちらも EV 経路の中にある）。
#    定数は "ev" へ戻すときのために残してあるだけで、休止中。
RANK_7M1_LEG_ORDER = "position"
# ═══════════════════════════════════════════════════════════════════════════
# 🔴 **相手の作り方の改定（2026-08-24・ユーザー提案）**
#
#   ハーネス: `scripts/exp_7m1_partner_count.py`（測定値はそこの docstring が正本）
#   memory:   keirin_7m1_partner_count_2026_08_24
#
#   ## ① ○(mark2) と △(mark4) は相手の**後ろへ回す**（`RANK_7M1_MARK_DEMOTE`）
#
#   7M1 のゲートは「モデル上位2車 ≠ {◎,○}」なので、◎は 87.5% が軸に入り
#   **○は 82.9% が相手からも落ちる**。二軸そろい 3,027R のうち 69.8% を相手で
#   外しており、その3着車は **○ 55.2% / △ 21.1% / 無印 12.9%**。
#   ＝ 体感の「二軸は来たのに相手で外す」は実在し、犯人は △ ではなく **○**。
#
#   🔴 **だからといって買い足すのは損**。「軸2＋その車」を1点買いしたときの
#      素ROI（model-free・38,825 の相手機会・2025/2026 とも同符号）:
#
#        印    機会      的中率   平均配当   素ROI(2025 / 2026)
#        ○    6,928   17.36%     397円   68.3% / 70.2%   ← 控除率の壁(74.85%)の下
#        △    6,477    8.62%     843円   73.7% / 70.9%   ← 壁の下
#        無印  22,951    4.37%   1,838円   76.8% / 86.3%
#
#      ○は「よく3着に来るが必ず安い」＝ **当てても損になる的中**を作る側。
#      7C の △カット（`RANK_7C_ANA_CUT_P3_MIN`）・7B の mark3 除外と同じ構造。
#
#   🔴 **ダッチングは負ける側へ金を厚く置く。** 賭け金は 1/予測オッズ に比例する
#      （`RANK_CONFIGS["7M1"]["tilt_stakes"] = True`）ので人気の相手ほど厚くなり、
#      実測で **現行は賭け金の 55.9% を ○/△ に投じていた**（点数比では 1.12/3 点）。
#      後ろへ回すと 37.3% まで下がる。
#
#   ⚠️ **除外ではなく後回し**。相手プールが痩せたレースでは結局買うことになるが、
#      それでよい（買わないと点数が作れない）。実測でも○△を完全に外す案は
#      2025 独立窓で的中 −6〜−9pt と明確に悪化した。
#
#   ## ② ○が人気を集めた1点に**集中**する（`RANK_7M1_MARU_CONC_*`）
#
#   引き金は **市場価格であってモデルの確率ではない**。十分位で見ると
#   モデルの同時確率 p は過信（p=0.50 の帯でも○の実際の3着率は 27〜29%）だが、
#   **予測オッズの含意確率は実測とほぼ一致する**（払戻率で割り戻して
#   最下位帯 0.149↔0.142/0.133・最上位帯 0.280↔0.291/0.272）。
#   実際、p を引き金にすると 2窓で的中が有意に悪化した。
#
#   🔴 **朝の入稿時点で引ける。** 引き金は `predict_board()` の予測オッズで、
#      入力は `wt_entries`（pred_*/競走得点/印/級班/脚質/ライン）＝板を見ない。
#      確定した実オッズ（`wt_odds`・6,250件）と突き合わせると
#      ○の三連複で **logMAE 0.1031 / ±2倍以内 96.5% / 引き金の一致率 89.8%**。
#      しかも**取り違えても損しない**——「予測◯だが実際×」は ○1点ROI 86.1% で
#      「予測◯かつ実際◯」83.4% より高く、逆に「予測×だが実際◯」は 68.4%。
#      ＝ **実オッズで引くほうがむしろ悪い**（良い帯を落として悪い帯を拾う）。
#
#   🔴 **下限 2.0倍は飾りではない。** 入稿側の `MIN_POINT_ODDS`(=2.0) は
#      「2倍未満の目が1つでもあるレースは出さない」なので、下限を置かずに
#      ○1点へ絞ると **発火の 27〜30% がレースごと落ちる**（○が 2.0倍未満）。
#      下限を置けば、その帯は集中せず通常の相手構成のまま売れる＝件数を失わない。
#
#   🔴 **2点ではなく1点。** 2点は的中率が最も高い（42%）が払戻中央が
#      1.84〜2.02 まで落ち、ユーザー方針「払戻2倍未満は見送るべき」の線に触れる。
#      **1点なら払戻比＝三連複オッズなのでガミが構造的に起こりえない**（実測 0.0%）。
#
#   ## 実測（本番ゲート込み・掃引2026-01〜04 / 確認2026-05〜08 / 独立2025）
#
#   2025 は学習終端 2024-12-31 の vintage オッズモデルを別途訓練して独立窓にした
#   （同一年内の前後分割は確認窓にならないため）。
#
#     腕                    件/日           的中%              2倍+/日        ガミ%        倍率中央
#     現行 EV上位3点     12.0/12.7/12.9  22.1/22.9/20.6  2.14/2.34/2.13  0.9/0.6/1.2  3.04/3.02/2.91
#     **改定後**         12.0/12.7/13.0  26.0/26.7/24.2  2.58/2.66/2.52  0.5/0.5/0.8  2.88/2.74/2.83
#
#     対現行 レース単位 paired bootstrap（掃引/確認/独立）:
#       的中率     [+1.97,+5.84] / [+1.82,+5.75] / [+2.51,+4.68]  🟢🟢🟢
#       的中件/日  [+0.250,+0.717] / [+0.241,+0.750] / [+0.340,+0.625]  🟢🟢🟢
#       2倍+/日    [+0.200,+0.658] / [+0.078,+0.543] / [+0.258,+0.534]  🟢🟢🟢
#
#   🔴🔴 **ROI で採ったのではない。** 3窓とも点推定はプラス(+3.2〜+6.3pt)だが
#      CI は全て0を跨ぐ。この層で ROI を ±2.5pt に収めるには約15.6年かかる
#      （`RANK_7M1_P3_SUM_MAX` の冒頭）。採用根拠は **的中率・的中件数・
#      2倍以上の的中件数・ガミ率**の4つで、いずれも3窓で一致している。
#
#   ## ❌ 同時に測って却下したもの（再提案しないこと）
#
#   - **○が強いレースの見送り**: 3窓とも的中件/日🔴・2倍+/日🔴 で ROI は動かない。
#     件数を 12.2→10.3 件/日 に落として得るものが無い。
#   - **「差が少なく逆転の可能性がある/展開が見込まれる」条件の追加**: ○の同時確率 ÷
#     他相手の最良 を 1.0〜2.0 で足しても的中も 2倍+/日 も動かない。
#     **市場価格が既にその情報を含んでいる。**
#   - **点数据え置き(3点)で○△を完全に外す**: 2026 だけなら ROI 88.5/94.1% と最良に
#     見えるが 2025 独立窓で的中🔴・2倍+/日🔴。**ROI で採ってはいけない**実例。
#   - **相手を単純に足す（○や△を必ず買う）**: ROI 77〜79% と現行以下。
#
#   ## ❌ 却下: 期待値の下限で見送る（2026-08-25・ユーザー要望／再提案しないこと）
#
#   > 和歌山10R は期待値 0.16 と低いのに推奨が出て外れた。一定の期待値が取れない
#   > 場合は見送る条件を検討してほしい。
#
#   ハーネス: `scripts/exp_7m1_ev_gate.py`（測定値はそこの docstring が正本）
#
#   🔴 **観察は正しい。** その日買った1点（○集中）の EV は 0.163 で、同じレースの
#      相手5車の中で**最下位**だった（他は 0.75 / 0.85 / 0.88）。
#      `rank_7m1_select_legs` は ○1点集中を **EV 順より先に**評価するので、
#      EV 最下位の点でも単独で買う。既存3ゲート（`MIN_POINT_ODDS` /
#      `expected_payout_floor` / `MIN_MEAN_PAYOUT`）は想定払戻 25,000円 で全て通る。
#
#   🔴🔴 **しかし下限を置くと必ず悪くなる。** 3窓（掃引 2026-01〜04 / 確認 05〜08 /
#      独立 2025）で測ると:
#
#      - 期待値の五分位と ROI は**単調でない**。確認窓・独立窓では
#        **最下位帯が最上位帯より良い**（独立 84.4% ↔ 76.9%）
#      - 和歌山10R が入る帯（EV 0.0〜0.3）は ○1点集中の中で
#        **3窓とも最良か2位**（ROI 91.5 / 86.8 / 90.7%）
#      - 見送り閾値 0.3〜0.7 のどこでも **的中件/日・2倍以上の的中件/日が
#        3窓とも有意に減り**（独立窓 CI95 は全閾値で0を跨がない）、ROI は動かない
#
#   🔴 **原因は確率側の較正**。買った点の実測的中率 6.9〜7.4% に対し、
#      本番 PL は最上位五分位で 0.271→実測 0.151（過信）、確認画面の独立近似は
#      0.103→0.173（過小）。**確率が壊れているので積である EV も順序を持てない。**
#      表示（0.24）と本番（0.16）が食い違うのも同じ理由で、片方へ揃えても直らない。
#
#   ⚠️ 市場価格には勾配があるが**向きが逆**——○の予測オッズ 2.0〜2.3倍（＝EV が
#      最も低くなる側）が3窓とも最良（的中 53.3/45.2/37.7% ・ROI 127.7/101.3/89.8%）。
#      「期待値が低いから切る」は、この最良の帯を切ることになる。
#
#   ⚠️ 既出の ❌「○が強いレースの見送り」と**同じ結論に別経路で到達**している。
#
#   ## 🔴 既存記述の訂正
#
#   `rank_7m1_select_legs` にあった「**点数を増やすと悪化する**（EV上位4/5 は
#   2倍+ が 1.51/1.36 へ低下）」は `scripts/exp_7m1_ev_legs.py` が**均等配分**
#   (`trio ÷ (100 × 点数)`) で採点した結果で、本番のダッチングとは別物。
#   ダッチングでは払戻 = 予算 ÷ Σ(1/オッズ)・ROI = Σp ÷ Σ(1/オッズ) となり、
#   **点を足して得な条件は「その点の EV が現在の ROI を上回ること」だけ**。
#   CLAUDE.md「実験スクリプトの定数から baseline を取ってはいけない」の3例目。
#
#   ## 🔴🔴 2026-08-26: **EV 順・○1点集中とも休止し位置規則へ戻した**（ユーザー判断）
#
#   ハーネス: `scripts/exp_7m1_axis2_shape.py`（測定値はそこの docstring が正本）
#   memory:   keirin_7m1_maru_conc_shape_gate_2026_08_26
#
#   > 玉野1R（`20260826_61_01`）は三連複 3=5=7 の1点 2.6倍・期待値 0.41 で外れた。
#   > 1点で2.6倍に投入するようなレースではない。タイトルの「中穴ねらい」も正しくない。
#   > レースとしては中穴（三連複 4,290円）が出ているので、位置規則が正しそう。
#
#   🔴 **見送りゲートでは解けない。** 「軸1は抜けたが二軸に絞れないレースを外す」を
#      形状（p3(軸2)−p3(○) ∧ pw(軸1)）・二軸そろい確率・○集中の帯幅の3通りで測ると、
#      3窓とも**的中件/日だけが減り ROI の CI は0を跨ぐ**。玉野1R は○集中母集団の
#      中央値（形状3量が下44〜68%点）で外れ値ですらない。EV 下限は前日に否定済み。
#
#   🔴 **文言と買い目が食い違っていたのが本体。** `race_shape.SHAPE_NOTES["7M1"]` は
#      6つの shape すべてで「相手を人気薄へずらした / 人気どころを外した / 指数下位の
#      3車に絞った」と書いており、これは**位置規則の説明**。○1点集中は逆に
#      **相手プールで最も人気の点を単独で買う**ので、タイトル「中穴ねらい」も本文も
#      事実と反する（玉野1R の相手 5番は公式○で予測 2.65倍＝5点中いちばん安い）。
#      `STAKE_NOTE_TILTED` の注記と同じ「無条件に書くと嘘になる」型。
#
#   🔴 **交換の内容**（同一母集団・同一軸・3窓とも同符号）。ROI は動かない:
#
#        買い方                  的中%       的中/日     ROI%    倍率中央   10倍+/的中
#        EV順+○集中(4点)    23.7〜26.1  3.00〜3.20  76〜87  2.81〜2.91  0.5〜1.3%
#        **位置規則(下位3車)** 11.1〜12.3  1.42〜1.59  75〜88  5.75〜6.10  16.5〜20.7%
#
#      7M1 の設立趣旨は「ベース層(1.5倍)と 7H1(8.4倍)の間＝**3〜10倍の空白**を埋める」
#      こと（`RANK_7M1_P3_SUM_MAX` 冒頭）。EV 順の中央 2.8〜2.9倍は 7B(2.29倍)の
#      すぐ上で、空白が再び空いていた。**的中頻度ではなく配当帯を採る**という選択。
#
#   ⚠️ **玉野1R は位置規則でも外れる。** 位置規則の相手は [2,1,6] で、実際の3着内は
#      {1,3,6} だが**軸2の7が5着**。軸2車が固定である以上どの相手でも取れない。
#      戻した理由は「その1件を当てられるから」ではなく**商品の帯と文言を一致させる**ため。
#
#   ⚠️ **`RANK_7M1_LEGS` は 4 のまま**。位置規則では `others` が最大5車・`start=2` なので
#      `ranked[2:2+n]` は n=3 でも n=4 でも同じ3車になる（＝挙動は変わらない）。
#      "ev" へ戻したときに 2026-08-24 の検証（4点）がそのまま効くよう 4 を残す。
# ═══════════════════════════════════════════════════════════════════════════
#: 相手の並びで**後ろへ回す**公式印（カンマ区切り・空文字なら後回ししない）。
#  🔴 文字列で持つのは `rank_rule_version` がスカラしか拾わないため。
#     タプルにすると定数を変えても版が変わらず、picks_history の世代が混ざる。
RANK_7M1_MARK_DEMOTE = "2,4"
#: ○1点へ集中する予測オッズの帯（両端を含む）。
#  🔴 下限は `stake_allocation.MIN_POINT_ODDS` と揃えること（下記コメント参照）。
RANK_7M1_MARU_CONC_ODDS_MIN = 2.0
RANK_7M1_MARU_CONC_ODDS_MAX = 3.1
# 🔴 **堅い帯の取り込み（2026-08-19・ユーザー要望「三連複で10倍以上を中心に狙う」）**
#
#   7M1 は当初「混戦帯（7C の裏返し）」だけを見ていたが、**7C が買わない堅い帯**にも
#   同じ性格の母集団が残っていた。取り込む条件は次の3つを全て満たすこと:
#
#     (a) 上位2車の合計 >= RANK_7M1_P3_SUM_MAX（＝堅い帯）
#     (b) **◎が軸2車に入り、○は入らない**（`wt_honmei_in_axis_7c` が True かつ
#         `wt_overlap_7c_n == 1`）
#     (c) `rank_7c_accepts()` が False（＝7C が見送るレース）
#
#   【なぜ (b) が「◎あり・○なし」なのか】2025-01〜2026-08-18・37,660R の実測で、
#   三連複 軸2車＋下位3車を買ったときの成績を軸と公式印の重なりで割ると:
#
#     | 軸の作り方              | 件/日 | 的中% | 10倍+的中% [95%CI]  | 的中中10倍+ | 配当中央 |
#     |------------------------|-------|-------|---------------------|------------|---------|
#     | ◎あり・2軸目＝○        | 49.8  | 18.2  | 7.64 [7.34, 7.94]   | 42.1%      |  8.5倍  |
#     | **◎あり・2軸目は○以外** | 12.0  | 11.7  | 7.95 [7.32, 8.57]   | **67.8%**  | 14.2倍  |
#     | 【差替】◎を外して上位2   | 63.3  |  5.0  | 4.16 [3.96, 4.36]   | 83.9%      | 25.9倍  |
#     | 【差替】◎○を外して上位2  | 63.3  |  3.6  | 3.07 [2.90, 3.25]   | 85.0%      | 27.8倍  |
#
#   🔴 **◎を軸から外してはいけない**。外すと10倍以上の的中頻度が**半減**する
#      （7.6〜8.0% → 3.1〜4.2%・CIが重ならない）。1本の配当中央は 8.5→25.9倍に
#      跳ねるが頻度の損失が上回り ROI は 54.8〜66.0% と壁の下へ落ちる。
#   🔴 **軸を差し替えるのではなくレースを選ぶこと。** ◎を外して2軸目を繰り上げる
#      設計は上表の【差替】と同じものになる。
#   ✅ 「◎あり・○なし」は 10倍以上の的中頻度を**落とさずに**（7.64→7.95%・
#      統計的に同じ）安い的中だけを落とす。減る 6.5pt は全て10倍未満。
#
#   【(c) が要る理由】堅い帯は 7C の縄張りで、入稿の優先順位は 7C > 7M1。
#   7C が買うレースを 7M1 が拾っても**入稿されない紙の推奨が増えるだけ**。
#   7C の受理条件そのもの（`rank_7c_accepts`）を共有して、隙間だけを取る。
#
#   実測（`scripts/exp_7m1_firm_band.py`・本番と同じ予算枠10,000円＋p3傾斜配分・
#   確定オッズ採点・(a)(b)(c) を全て満たすレースを三連複 軸2車＋下位3車で購入）:
#
#     | 年   | 件/日 | 的中% | 表示的中% | ROI%  | 配当中央 | 的中中10倍+ |
#     |------|-------|-------|-----------|-------|---------|------------|
#     | 2025 |  3.1  | 11.2  |   11.2    | 81.4  | 5.24倍  |   59.7%    |
#     | 2026 |  2.4  | 11.1  |   11.1    | 82.1  | 5.28倍  |   63.9%    |
#
#   **両年でほぼ完全に一致**し、現行 7M1（的中 11.3% / ROI 82.3% / 払戻中央 5.66倍）
#   と同一のプロファイル。ガミは実質ゼロ（的中率＝表示的中率）。
#
#   ⚠️ **ROI が上がるから入れるのではない**。n=1,148/549 では ROI の CI は
#      ±10pt 以上あり、既存 7M1（[69.9, 94.2]）と区別できない。採用根拠は
#      「同じ性格の商品を増やせること」と「的中の約6割が10倍以上」であって
#      回収率の改善ではない。
#   ⚠️ **内訳（7C が見送った理由別）で切り分けてはいけない。** 三連複ゲート /
#      相手不足 / 軸1抜けすぎ の各サブセグメントは n=82〜585 で、2026年の
#      「軸1抜けすぎ」は ROI 27.3%、2025年は 95.8% と年で符号が反転する。
#      合計で見ること（多重比較で必ず良いサブセグメントが見つかる）。
#   ⚠️ 実際に増える入稿は **1.7件/日 程度**。母集団 2.85件/日 のうち 15.5% は
#      7S/7B/7H1/7T1 が先に取る（優先順位で譲る）。
RANK_7M1_FIRM_BAND = True
#: 堅い帯を拾うために候補dictへ必ず載せるキー（`rank_7c_accepts` が見るもの）。
_FIRM_BAND_REQUIRED_KEYS = ("legs_7c", "legs_7c_buy", "lowpay_pattern", "axis1_p3")
RANK_7M1_BUDGET = RACE_BUDGET
RANK_7M1_UNIT = STAKE_UNIT


def rank_7m1_maru_concentrates(
    maru: int | None, odds: dict[int, float] | None,
    lo: float | None = None, hi: float | None = None,
) -> bool:
    """○1点へ集中するか（市場が○に人気を集めた帯かどうか）。

    maru: ○(mark2) の車番。相手プールに居なければ None
    odds: {相手車番: その点の**予測**三連複オッズ}
    lo/hi: 帯の下限・上限。None なら `RANK_7M1_MARU_CONC_ODDS_{MIN,MAX}`

    🔴 **既定値を `lo: float = RANK_7M1_MARU_CONC_ODDS_MIN` と書いてはいけない。**
       Python の既定引数は定義時に評価されるので、定数を書き換えても効かない
       スイッチになる（`rank_7m1_takes_firm_band` で実際に踏んだ型）。
    🔴 **判定できないときは False（集中しない）**。○が居ない・予測オッズが無い
       レースで集中すると、根拠なく1点買いになる。
    """
    lo = RANK_7M1_MARU_CONC_ODDS_MIN if lo is None else lo
    hi = RANK_7M1_MARU_CONC_ODDS_MAX if hi is None else hi
    if maru is None or not odds:
        return False
    o = odds.get(int(maru))
    return bool(o and lo <= float(o) <= hi)


def rank_7m1_demoted_marks() -> set[int]:
    """相手の並びで後ろへ回す公式印の集合（`RANK_7M1_MARK_DEMOTE` を解釈する）。"""
    raw = str(RANK_7M1_MARK_DEMOTE or "").strip()
    return {int(x) for x in raw.split(",") if x.strip()}


def rank_7m1_select_legs(
    others: list[int], top3_probs: dict[int, float],
    start: int = RANK_7M1_LEG_START, n: int = RANK_7M1_LEGS,
    p3_min: float = RANK_7M1_LEG_P3_MIN, min_legs: int = RANK_7M1_LEGS_MIN,
    ev: dict[int, float] | None = None,
    odds: dict[int, float] | None = None,
    marks: dict[int, int] | None = None,
    order: str | None = None,
) -> list[int]:
    """7M1の相手選択。`order` が "ev" なら EV 順の上位 n 点、"position" なら下位車。

    order: 並べ方。None なら `RANK_7M1_LEG_ORDER`（現行 "position"）。
      🔴 **既定値を `order: str = RANK_7M1_LEG_ORDER` と書いてはいけない。**
         Python の既定引数は定義時に評価されるので、定数を書き換えても効かない
         スイッチになる（`rank_7m1_maru_concentrates` で実際に踏んだ型）。
      🔴 "position" のとき `ev` / `odds` / `marks` は**無視する**。呼び出し元
         （live と日次 tail 再構築）はどちらも常に渡してくるので、ここで
         束ねないと2箇所を同時に直さない限り規則が割れる。

    odds:  {相手車番: その点の**予測**三連複オッズ}。○1点への集中判定に使う。
    marks: {車番: 公式印(1=◎/2=○/3=▲/4=△/0=無印)}。○の特定と、○/△を相手の
           後ろへ回すのに使う。**無ければ後回しも集中もしない**（fail-open で
           2026-08-24 以前と同じ挙動）。

    ⚠️ **以下の EV 経路は 2026-08-26 から休止中**（`RANK_7M1_LEG_ORDER = "position"`）。
       記述は "ev" へ戻すときのために残してある。休止の理由は
       `RANK_7M1_MARK_DEMOTE` 定義部の「2026-08-26」節。

    改定（2026-08-24・根拠は `RANK_7M1_MARK_DEMOTE` 定義部のセクションコメント）:

      1. `marks` と `odds` が揃い、○を含む点の予測オッズが
         `RANK_7M1_MARU_CONC_ODDS_MIN..MAX`（2.0〜3.1倍）なら **○1点だけ**を返す
      2. そうでなければ EV 降順。ただし **○(mark2)/△(mark4) は後ろへ回して**
         上位 n 点（既定4点）を採る

    🔴 **1 は 2 より先**。順序を入れ替えると、○が後ろへ回された結果
       「集中したいレースで○を買っていない」ことになる。
    🔴 **○1点は「1点買いを避ける」原則の唯一の例外**。1点なら払戻比が
       三連複オッズそのものになり、ガミが構造的に起こりえないので許される
       （通常の少点数化は `RANK_7C_TRIO_LEGS_FLOOR` のとおり避ける）。

    ev: {相手車番: 予測オッズ × 3着内確率}（`odds_prediction.trio_ev_for_legs`）。
        **買う候補すべてに値があるときだけ**使う。1台でも欠けたら従来規則へ落ちる
        （EV順と指数順が混ざると並びの意味が壊れる）。

    🔴 **EV 順では足切り（`p3_min`）を掛けない。** 足切りは「下位3車を位置で採る」
       規則の副作用を均すためのもので、EV は既にオッズ×確率で釣り合いを取っている。
       ここで p3 の低い車を削ると、EV が狙う「市場が安く付けているのに来る」相手を
       落として元の低配当側へ寄る。**検証もこの形（EV上位3・足切り無し）で行った**
       ので、足切りを足すと検証と別物になる。

    【EV 順の検証】honest 窓（オッズモデル train_end 2025-12-31 / 評価 2026・
    掃引 01〜04 と確認 05〜08 / 同一レース・同一軸・**3点据え置き**）。
    🔴 **この表は均等配分で採点されている**（下の訂正を先に読むこと）:

        腕            2倍+/日 掃引・確認   ガミなし/日   払戻中央   ROI
        現行(下位3)     1.27 / 1.48        1.50 / 1.74    4.6倍   83.8 / 85.6
        **EV上位3**    **1.57 / 1.71**    2.48 / 2.67    2.2倍   84.5 / 87.6
        オッズ上位3     1.18 / 1.48        1.23 / 1.59    5.6倍   81.4 / 85.3
        確率上位3       1.70 / 1.69        3.25 / 3.29   1.73倍   81.5 / 81.5

      レース単位ペア bootstrap（件/日）:
        EV3 − 現行3  2倍+ **+0.30 [+0.10,+0.50]** / **+0.22 [+0.02,+0.45]** 🟢両窓有意

    🔴 **対照2本が必要だった**。オッズだけでは現行より悪く、確率だけでは払戻中央が
       1.73倍＝**半分が2倍未満**に落ちる（7M1 が避けるために作られた帯）。
       **積でないと払戻帯が保てない。**
    🔴🔴 **2026-08-24 訂正: 「点数を増やすと悪化する（EV上位4/5 は 2倍+ が
       1.51/1.36 へ低下）／EV 順なら3点が最適」は撤回した。** 上の検証ハーネス
       `scripts/exp_7m1_ev_legs.py` は払戻比を `trio ÷ (100 × 点数)` ＝**均等配分**
       で採点しているが、本番の 7M1 は `RANK_CONFIGS["7M1"]["tilt_stakes"] = True`
       ＝ **1/予測オッズのダッチング**。均等配分では「ガミ境界 = オッズ < 点数」に
       なるので増点は必ず不利に出るが、ダッチングでは

           払戻 = 予算 ÷ Σ(1/オッズ)   （どの点で当たっても同額）
           ROI  = Σp ÷ Σ(1/オッズ)

       となり、**点を足して得な条件は「その点の EV が現在の ROI を上回ること」だけ**。
       本番配分で測り直すと 4点が3窓すべてで的中 +6.9〜+9.7pt・2倍+/日も改善する。
       いま `RANK_7M1_LEGS = 4` なのはこのため。詳細は `RANK_7M1_MARK_DEMOTE` 定義部。
       （CLAUDE.md「実験スクリプトの定数から baseline を取ってはいけない」の3例目）
    ⚠️ 本検証は honest モデル。本番は `train_end` が新しいので**検証より良く出うる**。
    ✅ **EV 順そのものは撤回していない。** ダッチングで測り直しても位置規則
       （p3 下位3点）より的中 +8〜12pt・2倍+/日も両窓 🟢 で優る。

    memory: keirin_7m1_ev_legs_2026_08_21 / keirin_7m1_partner_count_2026_08_24

    --- 以下は `ev` が無いときの従来規則 ---

    下位3車を採り、3着内率が `p3_min` 未満の車を削る。

    others:     軸2車を除いた残り車（通常5車。欠車時は盤面に残った車だけを渡す）
    top3_probs: {frame_no: pred_top3}（0-1 スケール）

    🔴 **順序が本質**。まず `start` 番目から `n` 点（＝下位3車）を採り、
       **そのあとで**足切りする。先に足切りしてから下位を採ると 7C と同じ規則になり、
       7M1 が狙う帯（人気薄の3着）が丸ごと消える。

    ⚠️ 足切りで `min_legs` を下回ったら、下位3車のうち**上位側**から戻して
       `min_legs` 点にする。**上位2枚（全体3・4番手）まで戻してはいけない**——
       そこは 7C/7S が既に取っている低配当の目で、この層の存在意義が消える。

    ⚠️ **足切りの効果は ROI ではない**（本番の予算枠＋傾斜配分で実測 −0.0pt
       [−2.4, +2.1]）。予算枠方式なので点数を減らしても投資は 10,000円 のままで、
       しかも傾斜は p3 比例＝削る目は元々一番薄い。実際に動くのは
       **的中率 12.1→11.3% と引き換えに払戻中央 5.38→5.66倍・2倍未満 7.7→7.0%**
       だけ。「ROI が上がるから」と説明してはいけない。

    returns 買う相手のリスト（pred_top3 の降順）。
    """
    order = RANK_7M1_LEG_ORDER if order is None else order
    if order == "ev" and ev is not None and all(f in ev for f in others):
        maru = None
        if marks:
            maru = next((f for f in others if marks.get(f) == 2), None)
        # ① 市場が○に人気を集めた帯なら○1点へ集中する
        if rank_7m1_maru_concentrates(maru, odds):
            return [int(maru)]
        # ② EV 順（上位 n 点）。○/△は後ろへ回す。
        #    足切りも min_legs の戻しも掛けない（上記）。
        demote = rank_7m1_demoted_marks() if marks else set()
        return sorted(
            others,
            key=lambda x: (1 if (marks or {}).get(x) in demote else 0, -ev[x], x),
        )[:n]
    ranked = sorted(others, key=lambda x: (-top3_probs.get(x, 0.0), x))
    base = ranked[start:start + n]
    kept = [x for x in base if top3_probs.get(x, 0.0) >= p3_min]
    if len(kept) >= min_legs:
        return kept
    return base[:min_legs]


def rank_7m1_daily_select(candidates: list[dict]) -> list[dict]:
    """7M1の選出: 公式印と不一致 ∧ 相手が最低点数そろう ∧ 次のどちらか。

      - **混戦帯**（上位2車の合計 < `RANK_7M1_P3_SUM_MAX`）… 従来からの母集団
      - **堅い帯のうち 7C が見送るレース** … `rank_7m1_takes_firm_band`
        （2026-08-19 追加。◎が軸に入り○が入らないレースだけ）

    candidates: 7車の生候補 dict のリスト（`rank_7c_*` と同じもの）。最低限
      {"p3_sum_top2": float, "wt_overlap_7c_n": int, "legs_7m1": list[int]}
      を持つこと。`legs_7m1` は**1点でもよい**（○集中・上記の🔴）。堅い帯を拾うには加えて `wt_honmei_in_axis_7c` と
      7C の受理判定に要るキー（`legs_7c` / `legs_7c_buy` / `lowpay_pattern` /
      `axis1_p3`）が要る。**無ければ堅い帯は拾わない（fail-closed）**。

    ⚠️ 合計は**較正後の値**で見る（`_gate_p3_sum`）。7C と同じ関数を通すことで、
       較正を入れ替えても両ランクの境界がずれない。

    🔴 `wt_overlap_7c_n` が None（＝公式印が取れていない）レースは**買わない**。
       他ランクは情報欠損を fail-open（買う）にしているが、本ランクは
       「印と割れていること」自体がエッジの本体なので、確認できない以上は
       降りるのが正しい。fail-open にすると印の取得が壊れた日に
       母集団が3倍に膨らんで別物になる。

    **他ランクとの重複は排除しない**（picks_history には行が入る）。
    入稿側の優先順位（`RANK_ORDER` の末尾）だけで1レース1商品に絞る。

    returns 採用された候補（p3_sum_top2 の降順）。
    """
    out = []
    for c in candidates:
        if c.get("n_entries", RANK_7M1_NE) != RANK_7M1_NE:
            continue
        if c.get("p3_sum_top2") is None:
            continue
        overlap = c.get("wt_overlap_7c_n")
        if overlap is None or int(overlap) >= 2:
            continue
        # 🔴 **1点は許す**（2026-08-24）。○1点への集中（`rank_7m1_select_legs` の
        #    ①）は意図した1点買いなので、ここで `RANK_7M1_LEGS_MIN`(=2) を
        #    要求すると**集中したいレースが丸ごと母集団から落ちる**。
        #    下限2点は「位置規則で足切りしすぎたときの戻し先」であって、
        #    選出のゲートではない（`rank_7m1_select_legs` の min_legs が担う）。
        if not (c.get("legs_7m1") or []):
            continue
        if _gate_p3_sum(c) < RANK_7M1_P3_SUM_MAX:
            out.append(c)                      # 混戦帯（従来からの母集団）
        elif rank_7m1_takes_firm_band(c):
            out.append(c)                      # 堅い帯のうち 7C が見送る隙間
    return sorted(out, key=lambda c: -float(c["p3_sum_top2"]))


def rank_7m1_takes_firm_band(c: dict, enabled: bool | None = None) -> bool:
    """堅い帯（7C の縄張り）の候補を 7M1 が拾うか。

    条件は3つとも必須（根拠は `RANK_7M1_FIRM_BAND` 定義部のセクションコメント）:
      (b) ◎が軸2車に入り、○は入らない
      (c) 7C が買わないレース（`rank_7c_accepts` を共有）

    🔴 **`wt_honmei_in_axis_7c` が無い候補は False を返す（fail-closed）。**
       較正導入前の候補JSONや古い再構築には無いキーで、そこを fail-open に
       すると「◎が軸に居ない＝配当は付くが的中頻度が半減する側」まで
       買ってしまう。他ランクは情報欠損を fail-open にしているが、
       本判定は 7M1 の印ゲートと同じく**確認できないなら降りる**のが正しい。
    """
    # 🔴 既定値を `enabled: bool = RANK_7M1_FIRM_BAND` と書いてはいけない。
    #    Python の既定引数は**定義時に評価される**ので、定数を書き換えても
    #    切り替わらない「効かないスイッチ」になる（実際にそれで
    #    ON/OFF 比較が両方 ON のまま走り、増分0件と誤読した）。
    if not (RANK_7M1_FIRM_BAND if enabled is None else enabled):
        return False
    # 🔴 7C の受理判定に要るキーが1つでも欠けていたら拾わない（fail-closed）。
    #    `rank_7c_accepts` は旧候補JSON向けに一部を fail-open（＝買う側）で
    #    扱うので、キーを渡し忘れた呼び出し元では「7Cは買わない」と誤判定され、
    #    **7C が実際に買うレースまで 7M1 が拾ってしまう**（実測で母集団が19%膨らむ）。
    #    ここで明示的に要求しておけば、配線し忘れた経路は静かに増えるのではなく
    #    静かに0件になる——どちらも静かだが、後者は商品を二重に売らない。
    if any(k not in c for k in _FIRM_BAND_REQUIRED_KEYS):
        return False
    if int(c.get("wt_overlap_7c_n") or 0) != 1:
        return False
    if c.get("wt_honmei_in_axis_7c") is not True:
        return False
    return not rank_7c_accepts(c)


def rank_7m1_unit_stake(n_legs: int, budget: int = RANK_7M1_BUDGET,
                        unit: int = RANK_7M1_UNIT) -> int:
    """7M1の1点あたり賭け金。全ランク共通の `unit_stake` へ委譲する。"""
    return unit_stake(n_legs, budget, unit)


# ═══════════════════════════════════════════════════════════════════════════
# RANK_9H1 — 穴推奨「9車・高配当狙い」（2026-08-08 新設・9車立て専用）
#
# 【命名】穴推奨は `{車数}H{連番}` 体系（H = Hole）。7H1（7車・本命バスト型）に続く
#   2本目で、**車数が違うので連番は 1 から**（7H2 は不採用のため欠番ではない）。
#
# 【なぜ9車か】決着した三連単オッズの分布が7車と構造的に違う（2024-01〜実測）:
#
#     車数   中央     >=300倍   >=500倍   >=1000倍
#     7車   35.7倍     9.31%     5.15%     1.91%
#     9車   77.4倍    20.50%    13.40%     6.38%
#
#   さらに帯を丸ごと買った素のROIも9車が高い（500-1000倍 67.5% vs 60.9%）。
#   **高配当を狙う母集団としては9車が構造的に有利**なのに、7H1 は7車専用
#   （9車ではバスト予測 AUC 0.5967 で不成立）なので、ここが空いていた。
#
# 【選別】レース単位の「波乱スコア」（`lgbm_upset_screen`）が閾値以上のレース。
#   スコアは **6/7/9車を統合して学習**する（9車だけでは標本が足りず効果が
#   検出できない）。特徴は出走表と番組表だけ＝**オッズ非依存で朝に確定する**。
#
#   実測（walk-forward・9車 3,435R・>=300倍帯の ratio = 実測÷市場含意）:
#     全件         ratio 0.887（帯ROI 66.5%）
#     上位20%      ratio 1.027（帯ROI 77.0%）  Δ +0.131 95%CI [+0.028, +0.230]
#     月次一貫性   27/30（90%）
#   9車単独学習だと Δ +0.090 [+0.001, +0.181]・月次 24/32 まで落ちる。
#
# 【買い目】1着 = モデル3着内率の**5位**の1車で固定
#           2着 = モデル3着内率の上位2車
#           3着 = モデル3着内率の上位4車              → 6点・1,600円/点
#
#   人気薄を1着に固定すると **ROI は変わらないまま払戻分布が右へ伸びる**
#   （1着に置く車の順位が下がるほど的中時配当の中央値が上がる）。
#   帯内の目選びはモデルがランダムに負けると確定済みなので、**順位で固定する
#   この形が、オッズを使わずに高配当帯へ寄せる唯一の手段**になる。
#
# 【実績】honest walk-forward・1レース10,000円・最終オッズ採点:
#
#     年          対象R  購入        的中      回収率   収支         除・上1本  月次100%超
#     2024         255  2,448,000   5(2.0%)  194.5%  +2,313,280   31.3%     2/12
#     2025         301  2,889,600   8(2.7%)  142.3%  +1,222,080   56.6%     2/12
#     2026(1-8月)  174  1,670,400   4(2.3%)  129.6%    +493,760   49.2%     2/8
#     3年計        730  7,008,000  17(2.3%)  157.5%  +4,029,120  100.5%     6/32
#
#   30万円超は3年で7件（うち100万円超3件）。**3年とも回収率100%超**。
#
# ⚠️ **期待値がプラスの戦略ではない。分散が極端に大きい戦略である。**
#   3年通算でも**上位2本を除くと回収率 65.2%**（控除率75%以下）で、各年の黒字は
#   毎年1〜2本が作っている。月次で100%を超えたのは 32ヶ月中6ヶ月（19%）だけ。
#   **真の期待値は 65〜100% のレンジで読むこと。** 商品として出すなら
#   「月の8割は外れ、年1〜2本で収支が決まる」性格をそのまま開示する。
#
# 【検証済みの否定結果（再提案しない）】
#   - 1着を7位固定・相手を上位3×4（9点）にする版: 2024 44.6% / 2025 47.2% /
#     2026 174.7% と年ごとの振れが大きく、3年のうち2年が回収率50%未満
#   - 「人気決着しにくいレース」(B) の除外を重ねる: B の予測自体は当たる
#     （AUC 0.594 で波乱予測 0.534 より高い）が、**B の層は ratio が 1.01〜1.15 と
#     市場より高く出る**＝人気決着は市場が過小評価しており、当てても妙味にならない。
#     A の選別に重ねても +0.01 程度しか足さない
#   - オッズを使う構成（「30倍以上で最も安い1点」）に本選別を重ねる:
#     30万+ が 2.44%→2.47% とほぼ動かない。**レース選別はオッズ情報の代替**なので、
#     オッズで帯を固定した時点で選別の役目は既に果たされている
#
# memory: keirin_9car_upset_bets_2026_08_08 / keirin_pooled_upset_screen_2026_08_08
# ═══════════════════════════════════════════════════════════════════════════

RANK_9H1_NE = 9                # 対象車数（9車ちょうど）
RANK_9H1_LEAD_RANK = 5         # 1着固定に使うモデル3着内率の順位
RANK_9H1_SECOND_N = 2          # 2着に使うモデル3着内率の上位車数
RANK_9H1_THIRD_N = 4           # 3着に使うモデル3着内率の上位車数

# 波乱スコアの採用閾値。**日ごとの相対順位ではなく絶対閾値**を使う（7H1 と同じ理由:
# 日次の相対順位で切り直すと切り捨てにより件数が系統的に減る）。
# 値は**9車母集団のスコア上位20%点**。検証時の walk-forward モデルでは 0.2962
# （決定期の取り方によらず安定: 2024年末まで 0.2962 / 2025年末まで 0.2991）だったが、
# **本番モデル（全期間学習）は較正が違い p80 = 0.3132** になる。同じ 0.2962 を
# 使うと該当率が 20%→26.9% へ膨らむため、本番モデルの値を採る。
#
# 🔴 **この値はモデルごとに違う。** 過去分を vintage モデルで再構築するときは
#    `rank_9h1_daily_select(..., score_min=<その vintage の p80>)` を渡すこと
#    （本番の絶対値をそのまま当てると件数が数割ずれる）。
# ⚠️ 再学習したら `scripts/train_upset_screen.py` が最後に出す9車スコア分布を見て
#    ここを p80 へ引き直す（放置すると推奨件数が振れる）。
RANK_9H1_SCORE_MIN = 0.3132


def rank_9h1_build_legs(top3_probs: dict[int, float]) -> list[str]:
    """9H1 の買い目（三連単フォーメーション6点）を返す。組めなければ空。

    Args:
        top3_probs: {車番: モデル3着内率}。**出走車ぶん全部**渡すこと。

    1着は「モデル3着内率 `RANK_9H1_LEAD_RANK` 位」の1車で固定する。人気薄を
    1着に置くと ROI は変わらないまま払戻分布が右へ伸びる（既確認）。
    """
    order = [f for f, _ in sorted(top3_probs.items(), key=lambda kv: -kv[1])]
    if len(order) < RANK_9H1_LEAD_RANK or len(order) < RANK_9H1_THIRD_N + 1:
        return []
    lead = order[RANK_9H1_LEAD_RANK - 1]
    rest = [f for f in order if f != lead]
    return [f"{lead}-{a}-{b}"
            for a in rest[:RANK_9H1_SECOND_N]
            for b in rest[:RANK_9H1_THIRD_N] if b != a]


def rank_9h1_stakes(n_legs: int) -> tuple[int, int]:
    """(1点あたり賭け金, 合計購入額) を返す。全ランク共通の予算枠方式に従う。

    通常形は6点なので 1,600円/点 × 6 = 9,600円。欠車で点数が減ったら
    その点数で引き直す（1レース1万円の枠は動かさない）。
    """
    u = unit_stake(n_legs)
    return u, u * max(n_legs, 0)


def rank_9h1_daily_select(candidates: list[dict],
                          score_min: float = RANK_9H1_SCORE_MIN) -> list[dict]:
    """当日の候補から 9H1 を選出する。

    candidates の各要素に必要なキー:
      `n_entries`(=9) / `upset_score`（波乱スコア） / `legs`（買い目・空なら除外）

    **選別は絶対閾値で行う**（日ごとの相対順位ではない）。0件の日があるのは正常
    （実測の件数は 21〜25件/月＝1日あたり1件前後）。

    `score_min` は既定で本番モデルの較正値。**過去分を vintage モデルで再構築する
    ときは、その vintage の9車スコア p80 を明示的に渡すこと**（モデルごとに較正が
    違うので、本番の絶対値を当てると件数が数割ずれる）。
    """
    elig = [c for c in candidates
            if c.get("n_entries") == RANK_9H1_NE
            and c.get("upset_score") is not None
            and float(c["upset_score"]) >= score_min
            and c.get("legs")]
    elig.sort(key=lambda c: -float(c["upset_score"]))
    return elig


# ═══════════════════════════════════════════════════════════════════════════
# RANK_7T1 — 三連単・高配当枠（2026-08-13 新設・7車立て専用）
#
# 【ねらい】1レース1万円の購入で **15万円以上の払戻**を適度な頻度で出す。
#   的中体験は既存の三連複ランク（7C/7S/7A…）が担うので、**この枠は的中率の
#   最大化を目的にしない**（実測 3.7%）。
#   ⚠️ ただし「的中しなくてよい」ではない。目標額を 20万→15万 にしたのは
#      **20万到達を落とさずに的中頻度を上げられた**からで、同じ一撃力なら
#      当たる回数は多いほうがよい（`RANK_7T1_TARGET_PAYOUT` の掃引表）。
#
# 【前身】RANK_7H3（2026-08-12 新設・入稿実績0のまま廃止）。あちらは
#   「軸積 >= 0.70」という**確率の絶対閾値**で母集団を切っていたため、
#   設計に使った確率（`wt_entries` の backfill 値）と本番コードパスの確率が
#   食い違った瞬間に母集団が1.4倍になり崩壊した
#   （`docs/rank_7h3_design.md` に経緯を残してある）。
#   🔴 **本ランクは確率を相対順位でしか使わない**（順序対の argmax・点は Σp 上位k）。
#      閾値は確率ではなく**予測オッズ側**に置く。walk-forward 予測へ差し替えた
#      honest 検証で、指数1位の一致が 89.1% しかなくても結果がほぼ動かないことを
#      確認済み（20万超 1.75% vs backfill 1.81%）。
#
# 【買うもの】軸1を1着・軸2を2着に固定し、3着へ相手を流す三連単。
#
#     1着列 = [a1] / 2着列 = [a2] / 3着列 = 相手（1〜5車）
#     → 展開すると (a1, a2, c) が相手ごとに1点 ＝ 相手数そのもの
#
# 【点数と足切りを「目的」から導く（本ランクの中核）】
#   1レース `RANK_7T1_BUDGET` 円を N 点で等分するなら
#
#       払戻 >= T  ⟺  当たった点のオッズ >= T ÷ (1点あたりの賭け金)
#
#   したがって**その値に届かない点は目的に一切寄与せず、賭け金を薄めるだけ**。
#   ⚠️ 「1点あたりの賭け金」は `BUDGET/N` ではなく **`rank_7t1_min_stake(N)`**
#      （最低単位へ丸めた後の最小額）。10,000円を3点なら 3,333 ではなく 3,300 円
#      が最小なので、`T×N/BUDGET` で切ると**最小の点だけ目標に届かない**。
#   点数 N と足切り閾値 `T×N/BUDGET` を自己整合させ、
#   「その条件を満たす点を Σ(Plackett-Luce 確率) 最大で N 点選ぶ」ときの
#   目的値が最大になる N を採る（`rank_7t1_select`）。
#   実測の採用点数（全7車）は 1点39% / 2点35% / 3点16% / 4点7% / 5点4%
#   （平均2.02点）。決勝系×別ラインなら 27/35/22/10/5%（平均2.31点）。
#
#   🔴 **固定の足切り倍率を置いてはいけない。** 前身の検証では 50倍固定だったが、
#      軸が強いレースだけが「50倍に届かない」壁を課され、成績が落ちて見えていた。
#      閾値を目的から導き直したらその現象ごと消えた（`memory` の
#      keirin_tf_highpay_handoff_2026_08_13 に掃引結果）。
#
# 【選別】3条件すべて。
#   (1) 7車ちょうど
#   (2) **決勝系レース**（決勝・準決勝・特選・選抜）— 前身 7H3 とは母集団が真逆
#       🔴 **「看板」ではない**。看板判定は準決勝を除外するが、7T1 は準決勝を含む
#          （検証をその定義で行った。準決勝は母集団の33%で成績は本体と同等）
#   (3) 3着内率の**上位2車が別ライン**（同一ラインの隣接でない）
#
#   決勝系レース×別ラインで **13.4本/日**（現行の入稿量とほぼ同じ）。
#   ⚠️ このセルの ROI は目標15万で 100.8% [82,122] と払戻率(74.85%)を上回るが、
#      **月別 ROI が 62〜140% と振れる**（n≈410/月）。母集団を切り替えて探した
#      セルの1つなので **「妙味が高いセル」と主張してはいけない**。
#      採る理由はブランド（決勝系レースに推奨を出す方針）と本数であって edge ではない。
#
# 【実測（honest walk-forward・7車13,749R・216日・2026-01-01〜08-04・目標15万）】
#   決勝系レース×別ライン: 13.4本/日 / 平均2.31点 / 的中 4.49% /
#   ROI 100.8% [82,122] / 的中時中央 189,667円 /
#   **15万超 3.04%＝2.5日に1回 / 20万超 2.10%＝3.5日に1回**
#   全7車: 平均2.02点 / 的中 3.65% / ROI 77.9% / edge 1.041 /
#   月別 ROI 66〜88%・月別15万超 2.02〜2.76%。破綻月なし。
#
#   🔴 **edge を作っているのではない。** 全7車の edge は 0.996＝ほぼ払戻率ちょうど。
#      `P(払戻>=T) <= ROI × BUDGET / T` の恒等式の中で、**同じ期待値を狙った額の
#      近くに寄せ直しているだけ**。控除率の壁は越えていない。
#
# 【検証済みの否定結果（再提案しない）】
#   - 軸の強さ（軸積・軸1の単勝率）でレースを足切りする：前身の固定足切りが
#     生んでいた見かけの効果で、自己整合にすると**符号が反転**する（5/7ヶ月）
#   - 3着に流す相手から最下位帯を落とす：点としては弱い（edge 0.756）が、
#     戦略にすると目的が動かない（10万超 2.01→2.00%・p=0.97）。2車落とすと悪化
#   - 荒れ指標（軸積・top3合計・エントロピー）でのレース選定：全滅
#   - 軸を指数1位固定にする：目的が落ちる（3.32→3.05%）。2位を軸1に選ぶ自由が要る
# ═══════════════════════════════════════════════════════════════════════════

RANK_7T1_NE = 7                     # 対象車数（7車ちょうど）
RANK_7T1_BUDGET = RACE_BUDGET       # 1レースの予算枠（円）
RANK_7T1_UNIT = STAKE_UNIT          # 最低賭け金単位（円）
# 目標払戻（円）。**この枠の設計値そのもの**で、点数も足切りもここから導かれる。
#
# 🔴 **2026-08-15 に 20万 → 15万へ変更した。** 理由は「20万を諦めた」ではなく、
#    **20万に届く頻度を落とさずに的中頻度だけ上げられる**ことが分かったため。
#    同一レース対比較（honest walk-forward・決勝系×別ライン n=2,898・
#    ブートストラップ95%CI）:
#
#      指標        15万     20万     差
#      的中率      4.49%    3.14%   +1.35pt [+0.62,+2.10]  有意
#      10万以上    3.97%    3.00%   +0.97pt [+0.24,+1.66]  有意
#      20万以上    2.10%    2.07%   +0.03pt [-0.48,+0.55]  差なし
#      30万以上    0.90%    1.21%   -0.31pt [-0.69,+0.07]  ns
#
#    的中率は 7/7 ヶ月で、20万到達も 5/7 ヶ月で 15万側が上。**優越関係**であって
#    閾値スイープの勝ちではない（＝T を細かく動かして良い数字を拾ったのではない）。
#    ⚠️ ただし T=20万 を決めたのと**同じ7ヶ月窓**での再評価なので、選択バイアスは
#       完全には抜けていない。前向きの実績で確認すること。
#
# ⚠️ **目標額は「買うか買わないか」を決めていない。** k=1 まで下げれば足切りは必ず
#    1点通るので、10万〜30万のどれでも**買えないレースは0件**（全7車13,749Rで実測）。
#    目標額が決めるのは**何点に割るか**だけ。したがって本数（13.4本/日）も
#    1日の投下額も変わらず、変わるのは点数分布と1点あたりの賭け金。
#    本数を動かしたいときは母集団（決勝系×別ライン）side を触ること。
#
# 掃引（honest・決勝系×別ライン・13.4本/日）:
#   10万 → 平均2.82点・的中5.35%・20万超 0.93%（8.0日に1回）
#   **15万 → 平均2.31点・的中4.49%・20万超 2.10%（3.5日に1回）（採用）**
#   20万 → 平均1.98点・的中3.14%・20万超 2.07%（3.6日に1回）
#   30万 → 平均1.64点・的中2.76%・20万超 2.28%（3.3日に1回）
# 10万は的中こそ最多だが20万到達が 1/2 以下に落ちる（＝一撃の枠でなくなる）。
# 30万は20万到達がわずかに上だが的中が 2.76% まで落ち、1点買いが54%を占める。
RANK_7T1_TARGET_PAYOUT = 150_000
# 軸1（1着に置く車）の候補を3着内率の上位何車に限るか。
# ⚠️ **これは足切りではなく説明可能性の制約**。外しても最適な軸1は指数1〜2位に
#    99% 集まる（10万超 3.30% vs 3.32%）ので、実質コストゼロで
#    「二軸探偵が指数上位2車から軸を選ぶ」というブランドを機械的に保証できる。
#    ただし 1（指数1位固定）まで絞ると目的が落ちる（3.32→3.05%）。
RANK_7T1_AXIS1_TOP_N = 2
RANK_7T1_KMAX = 5                   # 3着に流せる最大点数（7車なら残り5車）


#: 7T1 の対象レース種別（2026-08-24 に**決勝のみ**へ絞った・完全一致）。
#  🔴 **`marquee.MARQUEE_KEYWORDS` への依存を切った。** 以前は看板判定の正本を
#     束縛していたので、「7T1 を絞ろう」としてキーワードを触ると看板判定まで
#     動く構造だった。7T1 は自分の定数を持つ。
RANK_7T1_RACE_TYPES: tuple[str, ...] = ("決勝", "チャレンジ決勝")


def rank_7t1_is_target_race_type(race_type: str | None) -> bool:
    """7T1 の対象レース種別か（**決勝のみ・完全一致**）。

    🔴 **2026-08-24 に「決勝系（決勝/準決勝/特選/選抜）」から絞った。**
       日次上限5は ROI を1ミリも改善していなかった（件数を 1/3 に削って
       ROI は 81.8% で同じ＝ev による選別は無価値）一方、**種別で絞ると質が上がる**:

         上限なし（母集団まるごと）      13.60件/日  的中 3.68%  ROI  81.8%
         旧: 決勝系×別ライン×上限5        4.96件/日  的中 3.51%  ROI  81.8%
         決勝+準決勝×別ライン             7.03件/日  的中 4.18%  ROI  93.0%
         **決勝のみ×別ライン（現行）**    2.20件/日  的中 4.99%  ROI 106.3%

    🔴 **部分一致にしないこと**（「決勝」は準決勝に当たる）。
    🔴 **別ライン制約（`rank_7t1_is_cross_line`）は必ず併用する。**
       決勝×同ラインで 7T1 の買い方をすると ROI 64.7%（別ラインは 106.3%）。
       同ラインは `RANK_7T3` が優先順位の結果として拾う。
    ⚠️ 分析スクリプト（`scripts/exp_*`）がこの関数を「決勝系」の意味で使っている
       ものがあり、定義変更でそれらの母集団も決勝のみへ変わる。広い意味が要る
       場合は `marquee.MARQUEE_KEYWORDS` を直接使うこと。

    設計と実測: `docs/rank_7t3_design.md` §5
    """
    return str(race_type or "") in RANK_7T1_RACE_TYPES


def rank_7t1_is_cross_line(top3_probs: dict[int, float],
                           line_group: dict[int, object],
                           line_pos: dict[int, object]) -> bool:
    """3着内率の上位2車が**別ライン**か（同一ラインの隣接でない）。

    🔴 判定に使うのは「3着内率の上位2車」であって、`rank_7t1_select` が選んだ
       軸ではない。母集団の定義は軸選定より前に決まる（検証もその順序で行った）。

    ライン情報が欠けている車が混じる場合は「同一ライン隣接とは言えない」ので
    別ライン扱い（＝対象に含める）。欠損で静かに母集団が減るのを避ける。
    """
    order = [f for f, _ in sorted(top3_probs.items(), key=lambda kv: (-kv[1], kv[0]))]
    if len(order) < 2:
        return False
    a1, a2 = order[0], order[1]
    g1, g2 = line_group.get(a1), line_group.get(a2)
    if g1 is None or g2 is None or g1 != g2:
        return True
    p1, p2 = line_pos.get(a1), line_pos.get(a2)
    if p1 is None or p2 is None:
        return True
    return abs(int(p1) - int(p2)) != 1


def rank_7t1_pl_prob(win_probs: dict[int, float], leg: str) -> float | None:
    """Plackett-Luce による「その着順で決まる」確率。1着率が欠けたら None。

    P(x,y,z) = p(x) × p(y)/(1-p(x)) × p(z)/(1-p(x)-p(y))
    """
    if not win_probs:
        return None
    total = sum(v for v in win_probs.values() if v)
    if total <= 0:
        return None
    p = {k: float(v) / total for k, v in win_probs.items() if v is not None}
    out, used = 1.0, []
    for part in leg.split("-"):
        try:
            car = int(part)
        except ValueError:
            return None
        if car not in p:
            return None
        den = 1.0 - sum(p[u] for u in used)
        if den <= 1e-9:
            return None
        out *= p[car] / den
        used.append(car)
    return out


def rank_7t1_min_stake(k: int, budget: int = RANK_7T1_BUDGET,
                       unit: int = RANK_7T1_UNIT) -> int:
    """k 点を均等に買うとき、**実際に配られる最小の賭け金**（円）。

    `rank_7t1_stakes`（= `allocate_budget`）は最低単位へ丸めて端数を1点に寄せる
    ので、割り切れないときの最小額は理想の等分より小さい
    （10,000円/3点 → 3,300 / 3,300 / 3,400）。足切りはこの最小額から逆算する。
    """
    if k <= 0:
        return 0
    return (budget // (k * unit)) * unit


def _rank_7t1_min_odds(k: int, target_payout: int, budget: int,
                       unit: int) -> float | None:
    """k 点買うとき、全点が target_payout に届くために必要な最低オッズ。"""
    stake = rank_7t1_min_stake(k, budget, unit)
    if stake <= 0:
        return None
    return target_payout / stake


def rank_7t1_select(top3_probs: dict[int, float],
                    win_probs: dict[int, float],
                    pred_odds: dict[tuple[int, int, int], float],
                    target_payout: int = RANK_7T1_TARGET_PAYOUT,
                    budget: int = RANK_7T1_BUDGET,
                    unit: int = RANK_7T1_UNIT,
                    kmax: int = RANK_7T1_KMAX,
                    axis1_top_n: int = RANK_7T1_AXIS1_TOP_N,
                    ) -> tuple[int, int, list[str]] | None:
    """軸2車と買い目を**目的（払戻 >= target_payout の確率）の直接最大化**で決める。

    `pred_odds` は全順列の予測オッズ（`src/odds_prediction_tf.predict_board` の
    戻り値）。返すのは (軸1, 軸2, 買い目文字列のリスト)。組めなければ None。

    🔴 **予測オッズは板として整合させたものを渡すこと**（`predict_board` は
       レース内で再スケール済み）。生の回帰値を渡すと Σ(1/オッズ) が
       払戻率の制約から外れ、足切り閾値がそのままずれる。
    """
    order = [f for f, _ in sorted(top3_probs.items(), key=lambda kv: (-kv[1], kv[0]))]
    if len(order) < 3 or not win_probs or not pred_odds:
        return None
    allow = set(order[:axis1_top_n]) if axis1_top_n else set(order)

    best: tuple[float, int, int, list[str]] | None = None
    for a1 in order:
        if a1 not in allow:
            continue
        for a2 in order:
            if a2 == a1:
                continue
            legs = [f"{a1}-{a2}-{c}" for c in order if c not in (a1, a2)]
            scored: list[tuple[float, float, str]] = []   # (PL確率, 予測オッズ, 買い目)
            for leg in legs:
                pl = rank_7t1_pl_prob(win_probs, leg)
                odds = pred_odds.get(tuple(int(x) for x in leg.split("-")))
                if pl is None or pl <= 0 or odds is None or odds <= 0:
                    continue
                scored.append((pl, float(odds), leg))
            if not scored:
                continue
            scored.sort(key=lambda t: -t[0])
            for k in range(1, min(kmax, len(scored)) + 1):
                # 点数 k のときに払戻が target_payout に届く最低オッズ。
                # 🔴 `target_payout * k / budget`（＝理想の等分）で計算してはいけない。
                #    `rank_7t1_stakes` は最低単位に丸めるので、割り切れないときの
                #    最小の点は理想値より小さい（10,000円/3点 なら 3,300円であって
                #    3,333円ではない）。**実際に配られる最小額**から逆算する。
                bar = _rank_7t1_min_odds(k, target_payout, budget, unit)
                if bar is None:
                    break
                feas = [t for t in scored if t[1] >= bar]
                if len(feas) < k:
                    break     # k を増やすほど bar は上がるので、以降も満たせない
                obj = sum(t[0] for t in feas[:k])
                if best is None or obj > best[0]:
                    best = (obj, a1, a2, [t[2] for t in feas[:k]])
    if best is None:
        return None
    return best[1], best[2], best[3]


def rank_7t1_stakes(legs: list[str], budget: int = RANK_7T1_BUDGET,
                    unit: int = RANK_7T1_UNIT) -> dict[str, int]:
    """買い目ごとの賭け金。**均等**（1点あたり budget/点数）。

    🔴 確率で重み付けしてはいけない。点数と足切りは「全点が等額のとき払戻が
       target_payout に届く」ことを前提に決めてある（`rank_7t1_select`）。
       重み付けすると軽い点が目標に届かなくなり、選別の前提が崩れる。
    """
    from .stake_allocation import allocate_budget

    if not legs:
        return {}
    return allocate_budget({leg: 1.0 for leg in legs}, budget=budget, unit=unit)


# 🔴 **1日の上限本数**（2026-08-18・ユーザー判断「1日5レース程度・期待値のある上位5」）。
#   7T1 は 13.7件/日 と最も多く、8月の入稿全588件の**40%**を占めていた。
#   的中は設計どおり4.3%なので、商品構成に占める比率がそのまま
#   netkeirin の表示的中率を押し下げる（寄与は 0.40 × 3.4% ＝ 1.4pt だけ）。
#
#   ⚠️ **これは成績の問題ではない**。7T1 単体は honest walk-forward
#      （3,120R・2026-01〜08）で ROI 91.4% と壁の上にある。絞るのは
#      「高配当枠が商品全体に占める比率」を戻すための**構成の判断**。
#
#   ⚠️ 点数別の削減は測ったうえで**採らなかった**。1点 ROI 104.2%/的中5.0%、
#      2点 102.7%/4.7%、3点 78.1%/4.0%、5点 36.2%/1.0% で、1点が最良。
#      「1点は当てにくい」という印象は誤りで、点数が増えるほど必要オッズの
#      足切りが上がり的中率が下がる（1点15倍 → 5点75倍）。
#   🔴 **2026-08-24 に撤廃した（5 → 0）。** 上記の判断は「商品構成に占める比率を
#      戻す」ためのもので、**ROI は1ミリも改善していなかった**——件数を 13.60 →
#      4.96件/日 と 1/3 に削って ROI は 81.8% で同じ（CI [73,91] ↔ [66,98]）。
#      ＝ **ev による選別は無価値**だった。代わりに母集団を「決勝のみ×別ライン」
#      へ絞ることで 2.20件/日・ROI 106.3% にした（`rank_7t1_is_target_race_type`）。
#      比率の問題は母集団が薄くなったこと自体で解決している。
#   ⚠️ 0 は「上限なし」。`rank_7t1_daily_select` は falsy を上限なしとして扱う。
RANK_7T1_DAILY_CAP = 0


def rank_7t1_expected_value(candidate: dict, win_probs: dict[int, float] | None = None
                            ) -> float | None:
    """1レースの期待回収倍率（Σ 的中確率×予測オッズ×賭け金 ÷ 投資額）。

    候補が `ev` を持っていればそれを返す（候補生成時に確定させるのが正）。
    無ければ `pred_odds` / `stakes` / win_probs から組み立てる。

    🔴 **予測オッズで計算する**。確定オッズは朝には無い。したがってこの値は
       「予測が当たっている前提での期待値」であって、実現値ではない。
    ⚠️ 実測では的中133件のうち目標15万円へ届いたのは66.2%（1点は61.0%）。
       予測オッズは高めに出る傾向があるので、**この期待値も高めに出ている**。
    """
    v = candidate.get("ev")
    if v is not None:
        return float(v)
    odds = candidate.get("pred_odds") or {}
    stakes = candidate.get("stakes") or {}
    if not odds or not stakes or not win_probs:
        return None
    total = sum(stakes.values())
    if total <= 0:
        return None
    ev = 0.0
    for leg, stake in stakes.items():
        o = odds.get(leg)
        p = rank_7t1_pl_prob(win_probs, leg)
        if o is None or p is None:
            continue
        ev += float(p) * float(o) * float(stake)
    return ev / total


def rank_7t1_daily_select(candidates: list[dict],
                          daily_cap: int = RANK_7T1_DAILY_CAP) -> list[dict]:
    """当日の候補から 7T1 を選出する。

    candidates の各要素に必要なキー:
      `n_entries`(=7) / `race_type` / `is_cross_line` / `legs`（空なら除外）
      `ev`（期待回収倍率。上限で切るときの順位づけに使う）

    母集団の条件（**決勝** × 上位2車が別ライン）を満たしたものを採る。

    ⚠️ **日次上限は既定で無効**（`RANK_7T1_DAILY_CAP = 0`・2026-08-24）。
       機構は残してあるので `daily_cap` を明示すれば効く（検証用）。
       撤廃した理由は定数の定義部：件数を 1/3 に削って ROI が同じ＝
       ev による選別は無価値だった。

    🔴 **`ev` を持たない候補は落とさない**。旧形式の候補JSONを読んだときに
       商品が全滅するのを防ぐ（`legs_7c_buy` と同じ扱い）。ただし順位づけでは
       最下位に置くので、上限を**明示したとき**は結果的に外れる。
    ⚠️ 上限を掛けるのはここ1箇所だけ。`build_7t1_candidates.py` は日次1回しか
       走らないので、朝夜で枠を取り合う問題は起きない（7S とは事情が違う）。
    🔴 ただし**バックフィルは同じ関数を月単位で呼ぶ**ので、上限は必ず
       `race_date` ごとに掛けること（一括で掛けると月5本になる）。
    """
    elig = [c for c in candidates
            if c.get("n_entries") == RANK_7T1_NE
            and rank_7t1_is_target_race_type(c.get("race_type"))
            and bool(c.get("is_cross_line"))
            and c.get("legs")]
    if daily_cap:
        # 🔴 **必ず日付ごとに切る**。本関数は日次の候補生成（1日分）だけでなく
        #    過去分バックフィル（`build_7t1_candidates.build` を**月単位**で呼ぶ）
        #    からも通る。全体へ一括で上限を掛けると、その月ぜんぶで5本しか
        #    残らない（＝再構築が本番と別物になる）。
        by_day: dict[str, list[dict]] = {}
        for c in elig:
            by_day.setdefault(str(c.get("race_date") or ""), []).append(c)
        kept: list[dict] = []
        for day in by_day.values():
            day.sort(key=lambda c: (
                -(float(c["ev"]) if c.get("ev") is not None else -1.0),
                str(c.get("race_key"))))
            kept += day[:daily_cap]
        elig = kept
    # 発走順。表示・入稿の都合だけで決めてよい。
    elig.sort(key=lambda c: (str(c.get("start_time") or ""), str(c.get("race_key"))))
    return elig


# ═══════════════════════════════════════════════════════════════════════════
# RANK_7T3 — 三連単「決勝の中配当枠」（2026-08-24 新設）
#
# 設計書: `docs/rank_7t3_design.md`（この節は要点だけ。数字の出所は向こう）
#
# 【なぜ要るのか】ユーザー要望「1日3〜5レース狙い、週2〜3ヒット」。
#   🔴 **万車券（100倍以上）で週2〜3ヒットは算数的に不可能**。
#      週2.5ヒット ÷（3.5R/日 × 7日）＝ 必要な的中率 約10%。100倍以上を5点
#      買ったときの的中は構造的に 2.2%（各目の公正確率 0.75/160 ≈ 0.47%）。
#   オッズ帯を動かしても ROI はどの帯でも 73〜76% で一定（的中率と配当が
#   交換されるだけ）。**「週2〜3ヒット」に対応するのは 30倍以上の帯**。
#
#   ⚠️ したがって **商品説明で万車券を謳わないこと**。的中278件の払戻内訳は
#      〜3千円 30.9% / 3〜5千円 38.1% / 5千〜1万円 26.3% /
#      **1万円以上 4.7%（年6件）** / 3万円超 **0件**。
#
# 【定義】
#     n_entries == 7
#     ∧ race_type ∈ RANK_7T3_RACE_TYPES        # **完全一致**
#     ∧ 予測オッズ RANK_7T3_MIN_ODDS 倍以上の目が1点以上ある
#     → 位置別合成 PL の確率上位 RANK_7T3_LEGS 点
#
# 【実測】探索 2024-07〜2025-12(1,997R) / 確認 2026-01〜2026-08-04(783R):
#
#     窓     件/日  的中     ROI    CI        払戻中央
#     探索    3.6   9.51%   90.7%  [76,107]  79,080円
#     確認    3.6  11.24%   94.2%  [73,118]  72,300円
#     通算    3.6  10.00%   91.7%  [80,104]  77,000円   （対照＝全レース 75.2%）
#
#   四半期7窓で 5/7 が対照超え・5/7 が壁(74.85%)超え（**2窓は壁割れ**）。
#   月次ライブ（2026-04〜08・vintage m2604〜m2608）は 5/5ヶ月で対照超え・
#   通算 ROI 111.9%。
#   🔴 **黒字と断定しないこと。** 111.9% は的中60件・CI[81,146]。
#
# 【掘って空振りだった選別源（再検証不要・設計書 §7）】
#   Σp（AUC 0.5172・較正も崩壊）/ 源泉 LightGBM（AUC 0.5304）/
#   **場・バンク**（探索↔確認の順位相関 −0.065〜+0.047 ＝ ノイズ）/ 堅いレース優先。
#   🟢 効いたのは **race_type だけ**（順位相関 的中 +0.395 / ROI +0.408）。
#
# 【優先順位】`7H2 > 9H1 > 7T1 > 7T3 > 7S > 9C > 7B > 7C > 7H1 > 7M1`
#   （2026-08-24 ユーザー判断）。7T1 を 7T3 の**上**に置くのが必須。
#   決勝では ROI が 7S より 22〜31pt 高い一方、7T1/7T3 は合計 3.6件/日 と薄いので、
#   下に置くと 7S に取られてほぼ出ない（実測 7T1 は決勝の16%しか取れていない）。
#   受け入れたトレード: 7S の**表示的中 −0.22pt**・ROI 不変（決勝は 7S 母集団の5.7%）。
#   🔴 「決勝で 7S の的中は 44.5%」をそのまま比較に使わないこと。それはガミ込みの
#      生の的中率で、netkeirin が見せるのはガミを除いた **26.12%**。
# ═══════════════════════════════════════════════════════════════════════════

RANK_7T3_NE = 7                     # 対象車数（7車ちょうど）
RANK_7T3_BUDGET = RACE_BUDGET       # 1レースの予算枠（円）
RANK_7T3_UNIT = STAKE_UNIT          # 最低賭け金単位（円）
#: 対象レース種別。🔴 **完全一致で判定する**（`rank_7t3_is_target_race_type`）。
#  `marquee.MARQUEE_KEYWORDS` を使ってはいけない——あれは 決勝/特選/選抜/特秀 の
#  **部分一致**で準決勝・特選・選抜まで拾う。特選・選抜は単独 ROI 71.9% ＝壁の下。
RANK_7T3_RACE_TYPES: tuple[str, ...] = ("決勝", "チャレンジ決勝")
#: 買う目の予測オッズの下限（倍）。「週2〜3ヒット」に対応する帯。
#  ⚠️ 予測30倍以上でも**確定では17%が下振れ**する。的中の内訳を語るときは
#     予測ではなく確定オッズで数えること。
RANK_7T3_MIN_ODDS = 30.0
#: 買い目の点数。予算を等分するので 1点 = 2,000円。
RANK_7T3_LEGS = 5
#: 位置別合成の重み（1着=勝率 / 2着=相乗平均 / 3着=3着内率）。
#  🔴 `odds_prediction_tf.pl_ordered` は **`pw` 単独**なので流用しないこと。
#     確認窓の top1 的中は 単独 5.99% ↔ 合成 **10.07%**。
RANK_7T3_BLEND_W: tuple[float, float, float] = (1.0, 0.5, 0.0)


def rank_7t3_is_target_race_type(race_type: str | None) -> bool:
    """7T3 の対象レース種別か（**完全一致**）。

    🔴 部分一致にしないこと。「決勝」で部分一致すると準決勝を拾い、
       `marquee.MARQUEE_KEYWORDS` を使うと特選・選抜まで入る（単独 ROI 71.9%
       ＝控除率の壁の下）。検証は完全一致の定義で行った。
    """
    return str(race_type or "") in RANK_7T3_RACE_TYPES


def rank_7t3_blend_probs(
    cars: Sequence[int], win_probs: Mapping[int, float],
    top3_probs: Mapping[int, float],
    w: tuple[float, float, float] = RANK_7T3_BLEND_W,
) -> dict[tuple[int, int, int], float]:
    """三連単・全順列の確率。**位置別合成 Plackett-Luce**。

    1着は勝率(`pw`)、3着は3着内率(`p3`)、2着はその相乗平均を強度に使う:

        a = normalize(pw), b = normalize(p3)
        s_i = normalize(a**w_i * b**(1-w_i))        （w = (1, 0.5, 0)）
        P(x,y,z) = s0[x] × s1[y]/(1-s1[x]) × s2[z]/(1-s2[x]-s2[y])

    🔴 **`pw` 単独の PL（`odds_prediction_tf.pl_ordered`）とは別物**。
       三連単の買い目確率を1着率だけで作るのが元の穴で、位置別に合成すると
       確認窓の top1 的中が **5.99% → 10.07%** になる。
    ⚠️ 最後にレース内で正規化する（検証実装 `scripts/exp_7t3/tfprob.py` と同じ）。
    """
    cs = [int(c) for c in cars]
    if len(cs) < 3:
        return {}
    a = [max(float(win_probs.get(c, 0.0)), 1e-9) for c in cs]
    b = [max(float(top3_probs.get(c, 0.0)), 1e-9) for c in cs]
    sa, sb = sum(a), sum(b)
    a = [x / sa for x in a]
    b = [x / sb for x in b]
    strengths: list[list[float]] = []
    for wi in w:
        s = [ai ** wi * bi ** (1.0 - wi) for ai, bi in zip(a, b)]
        tot = sum(s)
        strengths.append([x / tot for x in s] if tot > 0 else s)
    idx = {c: i for i, c in enumerate(cs)}
    out: dict[tuple[int, int, int], float] = {}
    for x, y, z in _permutations(cs, 3):
        ix, iy, iz = idx[x], idx[y], idx[z]
        d1 = 1.0 - strengths[1][ix]
        d2 = 1.0 - strengths[2][ix] - strengths[2][iy]
        if d1 <= 0 or d2 <= 0:
            continue
        out[(x, y, z)] = (strengths[0][ix]
                          * (strengths[1][iy] / d1)
                          * (strengths[2][iz] / d2))
    tot = sum(out.values())
    return {k: v / tot for k, v in out.items()} if tot > 0 else {}


def rank_7t3_select(
    top3_probs: dict[int, float], win_probs: dict[int, float],
    pred_odds: dict[tuple[int, int, int], float],
    min_odds: float = RANK_7T3_MIN_ODDS, n_legs: int = RANK_7T3_LEGS,
) -> list[str]:
    """7T3 の買い目（`"1-2-3"` 形式の文字列）。組めなければ空リスト。

    予測オッズが `min_odds` 倍以上の目に限定し、**位置別合成 PL の確率の降順**で
    `n_legs` 点を採る。

    🔴 **EV順（確率 × 予測オッズ）にしてはいけない。** 100〜300倍帯では EV 順が
       優れるが、30倍帯では確率順のほうが素直。EV 順は探索窓で予測オッズモデルが
       in-sample なので過大評価される。
    🔴 `pred_odds` は板として整合させたもの（`odds_prediction_tf.predict_board`）を
       渡すこと。生の回帰値だと Σ(1/オッズ) が払戻率の制約から外れ、
       30倍という足切りがそのままずれる。
    """
    if not top3_probs or not win_probs or not pred_odds:
        return []
    cars = sorted(set(top3_probs) & set(win_probs))
    probs = rank_7t3_blend_probs(cars, win_probs, top3_probs)
    if not probs:
        return []
    band: list[tuple[float, tuple[int, int, int]]] = []
    for combo, odds in pred_odds.items():
        if not odds or float(odds) < min_odds:
            continue                       # 帯の外（安すぎる目）
        p = probs.get(combo)
        if p is None:
            continue                       # 盤面に無い車が混ざった目
        band.append((float(p), combo))
    if not band:
        return []
    # 確率の降順。同率は車番順で決定的にする（レースごとに揺れないため）。
    band.sort(key=lambda t: (-t[0], t[1]))
    return ["-".join(str(x) for x in combo) for _, combo in band[:n_legs]]


def rank_7t3_axes(legs: list[str]) -> tuple[int | None, int | None]:
    """7T3 の表示用 ◎○（2026-08-24 ユーザー判断）。買い目が空なら (None, None)。

        ◎ = 買い目5点の**1着に最も多く現れる車**
        ○ = ◎を除いて、**1着または2着に最も多く現れる車**

    🔴 **これは「軸」ではない。** 7T3 は軸を固定せず、予測オッズ30倍以上の帯から
       確率上位の決着順を採るだけ。実測（2026年の決勝200R）で
       5点すべてに共通して含まれる車は **1車が 50.5%**（2車は 49.0%）＝
       半数のレースに「二軸」と呼べる2車は存在しない。
       したがって**見解本文では「二軸」と明言しない**（7T3 だけ【二軸】節を
       持たない・`update_netkeirin_templates._body_no_axis`）。
       印を付けるのは **二軸探偵としてのブランドの一貫性**と
       **netkeirin が ◎○ を要求する**ためで、買い目の構造の主張ではない。

    ⚠️ 同数のときは **`legs` の並び順が早いほう**を採る。`rank_7t3_select` は
       確率の降順で返すので、これは「確率の高い買い目に出てくるほう」を意味する。
       車番昇順で切ると確率を無視した恣意的な選び方になる。
    """
    if not legs:
        return None, None
    cars = [[int(x) for x in leg.split("-")] for leg in legs]
    first_seen: dict[int, int] = {}
    for i, trio in enumerate(cars):
        for c in trio:
            first_seen.setdefault(c, i)
    n1: dict[int, int] = {}
    for trio in cars:
        n1[trio[0]] = n1.get(trio[0], 0) + 1
    honmei = min(n1, key=lambda c: (-n1[c], first_seen[c]))
    n12: dict[int, int] = {}
    for trio in cars:
        for c in trio[:2]:
            if c != honmei:
                n12[c] = n12.get(c, 0) + 1
    if not n12:
        return honmei, None
    taikou = min(n12, key=lambda c: (-n12[c], first_seen[c]))
    return honmei, taikou


def rank_7t3_stakes(legs: list[str], budget: int = RANK_7T3_BUDGET,
                    unit: int = RANK_7T3_UNIT) -> dict[str, int]:
    """買い目ごとの賭け金。**均等**（5点なら 2,000円/点）。

    🔴 確率で重み付けしないこと。30倍という足切りは「全点が等額」を前提に
       決めてある（`rank_7t3_select`）。重み付けすると軽い点が帯の意味を失う。
    """
    from .stake_allocation import allocate_budget

    if not legs:
        return {}
    return allocate_budget({leg: 1.0 for leg in legs}, budget=budget, unit=unit)


def rank_7t3_daily_select(candidates: list[dict]) -> list[dict]:
    """当日の候補から 7T3 を選出する。

    candidates の各要素に必要なキー:
      `n_entries`(=7) / `race_type` / `legs`（空なら除外）

    🔴 **ライン条件を持たない**（設計書 §8）。別/同ラインの判定は「p3上位2車」の
       取り方に敏感で、軸2を p3 の3番手に替えると **44.5%** のレースで反転する。
       判定ロジックを2箇所に持つと、モデルの微小な更新で商品が入れ替わる。
       入稿の優先順位で **7T1 の直後**に置けば、7T1 が取った別ラインは自動で降り、
       7T3 は同ラインだけを拾う。**判定の正本は 7T1 側の1箇所だけになる。**
       こうしておけば判定が揺れても必ずどちらか一方が出る（穴も二重入稿もない）。

    🔴 **日次上限は掛けない。** 決勝のみで 3.6件/日（優先順位で 7T1 に譲った後は
       1.4件/日）と元から薄い。7T1 の上限5は ROI を1ミリも改善していなかった
       （件数 1/3 で ROI 同じ）ので、同じ轍を踏まない。
    """
    elig = [c for c in candidates
            if c.get("n_entries") == RANK_7T3_NE
            and rank_7t3_is_target_race_type(c.get("race_type"))
            and c.get("legs")]
    # 発走順。表示・入稿の都合だけで決めてよい。
    elig.sort(key=lambda c: (str(c.get("start_time") or ""), str(c.get("race_key"))))
    return elig


# ═══════════════════════════════════════════════════════════════════════════
# 集計対象ランクの単一正本（2026-07-31 新設・是正タスク B-6 + C-1）
#
# 背景: 「集計対象ランクのハードコードされたリスト」が
#   - scripts/notify_results_wt.py::_query_stats のIN句（月次/年次サマリー）
#   - scripts/notify_results_wt.py::_PAPER_SUFFIXES（picks_history上書き保護）
#   - scripts/save_model_eval.py::PAPER_RANKS（model_evaluation保存）
#   - scripts/live_report_wt.py::RANKS/RANK_LABELS（live実測レポート）
# の計4箇所で独立に保守されており、内容が食い違う事故が3回発生した
# （7PLUS_R全廃後3週間 _query_stats が0件のまま放置・一部ランクのみ合算・
#  そして7SS新設(commit dc89f14)がpicks_historyに16,273行を投入したにも
#  かかわらず _query_stats のIN句に追加されず月次/年次サマリーに一切反映
#  されなかった事故＝本セクション導入の直接の契機）。
#
# 上記4箇所は全てここ（CURRENT_PAPER_RANKS / ABOLISHED_PAPER_RANKS）を参照し、
# 独自にランク一覧をハードコードしないこと。新ランクの追加/廃止時は、この
# セクションのみを更新すればよい（他4ファイルへの追随修正は不要）設計とする。
# ═══════════════════════════════════════════════════════════════════════════


@dataclass(frozen=True)
class PaperRankSpec:
    """1つの現行ペーパーランクの集計メタデータ（picks_history.rank に対応）。"""

    rank: str              # picks_history.rank の内部値（例: "RANK_7S"）
    suffix: str            # race_key の "#" サフィックス（例: "#7S"）
    label: str             # 表示ラベル（例: "7S"）
    in_header_total: bool  # notify_results_wt.py の[7+車]ヘッダー合計(p7b/p7r/p7h・n7)に含めるか
    in_live_report: bool   # live_report_wt.py の集計対象(RANKS)に含めるか


